def phase1_firmware_compatibility_catalog() -> list[dict[str, Any]]:
    """Expose firmware catalog entries without unsupported ARM64 claims."""

    catalog = []
    for item in firmware_compatibility_catalog():
        if item["hardware_model"] in ARM64_VALIDATION_HARDWARE_MODELS:
            catalog.append(
                {
                    **item,
                    "status": "validation_required",
                    "notes": (
                        "ARM64 target; ARM64 image and physical-device validation "
                        "are required before operational support."
                    ),
                }
            )
        elif item["hardware_model"] == "x86_64-edge":
            catalog.append(
                {
                    **item,
                    "notes": "x86 Linux edge baseline validated by Docker smoke.",
                }
            )
        else:
            catalog.append(item)
    return catalog


def phase1_firmware_compatibility_result(
    *,
    hardware_model: str,
    firmware_version: str,
    target_runtime: str,
) -> dict[str, Any]:
    """Require Phase-1 ARM64 image and device proof before a support claim."""

    result = firmware_compatibility_result(
        hardware_model=hardware_model,
        firmware_version=firmware_version,
        target_runtime=target_runtime,
    )
    if result["canonical_hardware_model"] not in ARM64_VALIDATION_HARDWARE_MODELS:
        return result

    result["compatible"] = False
    result["status"] = "requires_review"
    result["risk_level"] = "review_required"
    result["checks"] = [*result["checks"], ARM64_RUNTIME_EVIDENCE_CHECK]
    result["recommendations"] = [
        recommendation
        for recommendation in result["recommendations"]
        if recommendation != FIRMWARE_PILOT_ONBOARDING_RECOMMENDATION
    ] + list(ARM64_RUNTIME_VALIDATION_RECOMMENDATIONS)
    return result

