def restore_table_profile_fingerprint() -> str:
    """Return a stable identifier for the tables covered by restore tests."""

    return hashlib.sha256(
        json.dumps(
            sorted(RESTORE_VERIFICATION_TABLES),
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()[:16]


