def configured_tenant_id() -> str:
    """Return the validated single-customer tenant identifier."""

    candidate = os.getenv(TENANT_ID_ENV, DEFAULT_TENANT_ID).strip().lower()
    if not re.fullmatch(r"[a-z0-9][a-z0-9_-]{1,62}", candidate):
        raise RuntimeError("AGENTIOT_TENANT_ID is invalid")
    return candidate


def configured_deployment_id() -> str | None:
    """Return the opaque activation identifier used to revoke old sessions."""

    candidate = os.getenv(DEPLOYMENT_ID_ENV, "").strip()
    if not candidate:
        return None
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]{7,95}", candidate):
        raise RuntimeError("AGENTIOT_DEPLOYMENT_ID is invalid")
    return candidate


def secure_html_response(content: str, *, status_code: int = 200) -> HTMLResponse:
    """Return HTML with a per-response CSP nonce and no inline bypass."""

    nonce = secrets.token_urlsafe(24)
    nonce_content = re.sub(
        r"<(style|script)(?=[ >])",
        lambda match: f'<{match.group(1)} nonce="{nonce}"',
        content,
    )
    csp = SECURITY_HEADERS["Content-Security-Policy"]
    csp = csp.replace(
        "style-src 'self';", f"style-src 'self' 'nonce-{nonce}';"
    ).replace(
        "script-src 'self';", f"script-src 'self' 'nonce-{nonce}';"
    )
    return HTMLResponse(
        nonce_content,
        status_code=status_code,
        headers={"Content-Security-Policy": csp},
    )
