def specialized_team_graph() -> dict[str, Any]:
    """Return the customer-safe mandatory specialist-team orchestration graph."""

    nodes = [dict(item) for item in MANDATORY_SPECIALIZED_TEAM_ROSTER]
    node_ids = {node["team_id"] for node in nodes}
    edges: list[dict[str, Any]] = []
    for node in nodes:
        for target in node["handoff_to"]:
            if target not in node_ids:
                continue
            edges.append(
                {
                    "from": node["team_id"],
                    "to": target,
                    "protocol": "A2A",
                    "edge_type": "specialist_handoff",
                    "handoff_contract": "pass_fail_evidence_residual_risk_customer_impact",
                    "approval_required": target == "product_approval_team",
                }
            )
    lanes = sorted({node["lane"] for node in nodes})
    return {
        "policy_id": "multi-team-orchestration-required",
        "nodes": nodes,
        "edges": edges,
        "summary": {
            "mandatory_team_count": len(nodes),
            "edge_count": len(edges),
            "lane_count": len(lanes),
            "lanes": lanes,
            "customer_safe_nodes": sum(1 for node in nodes if node["customer_safe"]),
        },
        "quality_gates": {
            "no_self_approval": True,
            "release_requires_product_approval": True,
            "security_review_required": True,
            "visual_review_required_after_ui_change": True,
            "hardware_discovery_requires_allowlisted_evidence": True,
            "customer_bundle_excludes_team_logs": True,
        },
    }


def multi_team_orchestration_policy(graph: dict[str, Any]) -> dict[str, Any]:
    """Return the active non-trivial work routing policy."""

    return {
        "activation_rule": "mandatory_for_non_trivial_work",
        "non_trivial_scope": [
            "code",
            "architecture",
            "ui_ux",
            "backend_api",
            "security_privacy",
            "customer_delivery",
            "contract_requirements",
            "release_governance",
            "tests",
        ],
        "minimum_parallel_lanes": min(4, graph["summary"]["lane_count"]),
        "mandatory_team_count": graph["summary"]["mandatory_team_count"],
        "team_graph_endpoint": "/api/admin/agents",
        "evidence_matrix_endpoint": "/api/orchestration/evidence-matrix",
        "customer_delivery": "customer_safe_role_metadata_only",
        "completion_rule": "every_engaged_team_returns_pass_fail_evidence_risk_and_customer_impact",
        "approval_rule": "no_team_approves_its_own_work",
    }
