def safe_ai_provider_allowed_tools(items: list[Any]) -> list[str]:
    """Return persisted provider tools that remain inside the read-only allowlist."""

    safe: list[str] = []
    for raw in items:
        item = str(raw).strip()
        if item in AI_PROVIDER_ALLOWED_TOOL_ENDPOINTS and item not in safe:
            safe.append(item)
    return safe


def normalize_ai_provider_allowed_tools(requested: list[str]) -> list[str]:
    """Validate admin-selected AI tools before they can reach assistant plans."""

    safe = safe_ai_provider_allowed_tools(list(requested))
    submitted = [str(item).strip() for item in requested if str(item).strip()]
    if len(safe) != len(dict.fromkeys(submitted)):
        raise HTTPException(
            status_code=400,
            detail="Unsupported AI provider tool endpoint",
        )
    return safe or DEFAULT_AI_PROVIDER_POLICY["allowed_tools"].copy()


def safe_assistant_tool_plan_endpoint(endpoint: str) -> str | None:
    """Return a customer-safe read-only endpoint for assistant tool plans."""

    clean = str(endpoint).strip()
    return clean if clean in AI_PROVIDER_ALLOWED_TOOL_ENDPOINTS else None


