def create_admin_session_token(record: dict[str, Any]) -> tuple[str, str]:
    """Issue a short-lived revision-bound admin token."""

    signing_key = configured_admin_token()
    if not signing_key or secret_strength_state(signing_key) != "strong":
        raise HTTPException(status_code=503, detail="Admin authentication unavailable")
    deployment_id = configured_deployment_id()
    if is_production_mode() and not deployment_id:
        raise HTTPException(status_code=503, detail="Admin authentication unavailable")
    issued_at = datetime.now(UTC)
    expires_at = issued_at + timedelta(seconds=ADMIN_SESSION_TTL_SECONDS)
    token = jwt.encode(
        {
            "iss": ADMIN_SESSION_ISSUER,
            "aud": ADMIN_SESSION_AUDIENCE,
            "sub": record["username"],
            "role": record["role"],
            "sid": record["identity_id"],
            "rev": int(record["credential_revision"]),
            "tenant": configured_tenant_id(),
            "deployment": deployment_id or "development",
            "iat": issued_at,
            "nbf": issued_at,
            "exp": expires_at,
            "jti": secrets.token_hex(12),
        },
        signing_key,
        algorithm="HS256",
    )
    return token, expires_at.replace(microsecond=0).isoformat()


def context_from_admin_session(token: str, store: CoreStore) -> OperatorContext:
    """Validate one revision-bound local admin session token."""

    signing_key = configured_admin_token()
    if not signing_key or secret_strength_state(signing_key) != "strong":
        raise HTTPException(status_code=503, detail="Admin authentication unavailable")
    try:
        claims = jwt.decode(
            token,
            signing_key,
            algorithms=["HS256"],
            audience=ADMIN_SESSION_AUDIENCE,
            issuer=ADMIN_SESSION_ISSUER,
            options={
                "require": [
                    "exp",
                    "iat",
                    "nbf",
                    "sub",
                    "sid",
                    "rev",
                    "role",
                    "tenant",
                    "deployment",
                ]
            },
        )
    except PyJWTError as error:
        raise HTTPException(status_code=401, detail="Admin token required") from error
    record = store.get_local_identity_record(str(claims.get("sub", "")))
    if (
        record is None
        or not bool(record["enabled"])
        or record["role"] != "admin"
        or bool(record["password_change_required"])
        or claims.get("role") != "admin"
        or claims.get("sid") != record["identity_id"]
        or int(claims.get("rev", -1)) != int(record["credential_revision"])
        or not secrets.compare_digest(
            str(claims.get("tenant", "")),
            configured_tenant_id(),
        )
        or not secrets.compare_digest(
            str(claims.get("deployment", "")),
            configured_deployment_id() or "development",
        )
    ):
        raise HTTPException(status_code=401, detail="Admin token required")
    return local_identity_context(store, record, provider="admin-password-session")




def local_identity_context(
    store: CoreStore,
    record: dict[str, Any],
    *,
    provider: str = "browser-session",
) -> OperatorContext:
    """Build the current role context for one validated local identity."""

    role = str(record["role"])
    password_change_required = bool(record.get("password_change_required", False))
    policy = next(
        (item for item in store.list_access_role_policies() if item["role"] == role),
        None,
    )
    scopes = (
        [PASSWORD_CHANGE_SCOPE]
        if password_change_required
        else list(policy["scopes"]) if policy else []
    )
    return OperatorContext(
        actor=str(record["username"]),
        role=role,
        scopes=scopes,
        provider=provider,
        password_change_required=password_change_required,
    )


def create_browser_session_token(record: dict[str, Any]) -> tuple[str, str]:
    """Issue a revision-bound browser session without exposing the token."""

    signing_key = configured_browser_session_secret()
    if not signing_key or secret_strength_state(signing_key) != "strong":
        raise HTTPException(status_code=503, detail="Browser authentication unavailable")
    deployment_id = configured_deployment_id()
    if is_production_mode() and not deployment_id:
        raise HTTPException(status_code=503, detail="Browser authentication unavailable")
    issued_at = datetime.now(UTC)
    expires_at = issued_at + timedelta(seconds=BROWSER_SESSION_TTL_SECONDS)
    token = jwt.encode(
        {
            "iss": BROWSER_SESSION_ISSUER,
            "aud": BROWSER_SESSION_AUDIENCE,
            "sub": record["username"],
            "role": record["role"],
            "sid": record["identity_id"],
            "rev": int(record["credential_revision"]),
            "tenant": configured_tenant_id(),
            "deployment": deployment_id or browser_session_deployment_binding(),
            "iat": issued_at,
            "nbf": issued_at,
            "exp": expires_at,
            "jti": secrets.token_hex(12),
        },
        signing_key,
        algorithm="HS256",
    )
    return token, expires_at.replace(microsecond=0).isoformat()


def browser_session_claims(
    request: Request,
) -> tuple[OperatorContext, dict[str, Any]] | None:
    """Validate the cookie against the current account revision and role."""

    token = request.cookies.get(BROWSER_SESSION_COOKIE, "")
    signing_key = configured_browser_session_secret()
    if not token or not signing_key or secret_strength_state(signing_key) != "strong":
        return None
    try:
        claims = jwt.decode(
            token,
            signing_key,
            algorithms=["HS256"],
            audience=BROWSER_SESSION_AUDIENCE,
            issuer=BROWSER_SESSION_ISSUER,
            options={
                "require": [
                    "exp",
                    "iat",
                    "nbf",
                    "sub",
                    "sid",
                    "rev",
                    "role",
                    "tenant",
                    "deployment",
                ]
            },
        )
        store: CoreStore = request.app.state.store
        record = store.get_local_identity_record(str(claims.get("sub", "")))
    except (HTTPException, PyJWTError, ValueError):
        return None
    if (
        record is None
        or not bool(record["enabled"])
        or claims.get("sid") != record["identity_id"]
        or int(claims.get("rev", -1)) != int(record["credential_revision"])
        or str(claims.get("role", "")) != str(record["role"])
        or not secrets.compare_digest(
            str(claims.get("tenant", "")),
            configured_tenant_id(),
        )
        or not secrets.compare_digest(
            str(claims.get("deployment", "")),
            configured_deployment_id() or browser_session_deployment_binding(),
        )
    ):
        return None
    return local_identity_context(store, record), claims


def browser_session_context(request: Request) -> OperatorContext | None:
    """Return the current local browser identity when its cookie is valid."""

    result = browser_session_claims(request)
    return result[0] if result else None


def browser_session_deployment_binding() -> str:
    """Bind browser sessions to one tenant and immutable release runtime."""

    release_identity = "|".join(
        (
            configured_tenant_id(),
            source_commit_id(),
            runtime_manifest_digest(),
        )
    )
    return hashlib.sha256(release_identity.encode("utf-8")).hexdigest()


def cookie_state_change_has_same_origin(request: Request) -> bool:
    """Require a same-origin browser signal for cookie-authenticated writes."""

    if (
        not is_production_mode()
        or request.method.upper() not in {"POST", "PUT", "PATCH", "DELETE"}
        or BROWSER_SESSION_COOKIE not in request.cookies
        or any(
            request.headers.get(name, "").strip()
            for name in ("Authorization", OPERATOR_TOKEN_HEADER, ADMIN_TOKEN_HEADER)
        )
    ):
        return True
    fetch_site = request.headers.get("Sec-Fetch-Site", "").strip().lower()
    if fetch_site and fetch_site != "same-origin":
        return False
    origin = request.headers.get("Origin", "").strip()
    if not origin or origin.lower() == "null":
        return False
    try:
        parsed_origin = urlparse(origin)
        expected_scheme = (
            "https"
            if os.getenv(TLS_TERMINATION_ENV, "").strip().lower() == "reverse-proxy"
            else request.url.scheme.lower()
        )
        parsed_host = urlparse(
            f"{expected_scheme}://{request.headers.get('host', '').strip()}"
        )
        if (
            parsed_origin.scheme.lower() != expected_scheme
            or not parsed_origin.hostname
            or not parsed_host.hostname
            or parsed_origin.username is not None
            or parsed_origin.password is not None
            or parsed_origin.path not in {"", "/"}
            or parsed_origin.params
            or parsed_origin.query
            or parsed_origin.fragment
        ):
            return False
        origin_port = parsed_origin.port or (443 if expected_scheme == "https" else 80)
        host_port = parsed_host.port or (443 if expected_scheme == "https" else 80)
    except ValueError:
        return False
    return secrets.compare_digest(
        parsed_origin.hostname.lower(),
        parsed_host.hostname.lower(),
    ) and origin_port == host_port


def require_local_browser_identity(request: Request) -> OperatorContext:
    """Require a local cookie identity for self-service account changes."""

    identity = browser_session_context(request)
    if identity is None:
        raise HTTPException(status_code=401, detail="Local browser session required")
    return identity


def set_browser_session_cookie(response: Response, token: str) -> None:
    """Set the signed session as an HttpOnly same-site cookie."""

    response.set_cookie(
        key=BROWSER_SESSION_COOKIE,
        value=token,
        max_age=BROWSER_SESSION_TTL_SECONDS,
        httponly=True,
        secure=is_production_mode(),
        samesite="strict",
        path="/",
    )


def clear_browser_session_cookie(response: Response) -> None:
    """Remove both development and production variants of the cookie."""

    for secure in (False, True):
        response.delete_cookie(
            key=BROWSER_SESSION_COOKIE,
            path="/",
            secure=secure,
            httponly=True,
            samesite="strict",
        )


def browser_login_required() -> bool:
    """Return whether browser HTML is protected by the local login page."""

    configured = os.getenv("AGENTIOT_REQUIRE_BROWSER_LOGIN", "").strip().lower()
    if configured in {"1", "true", "yes", "on"}:
        return True
    if configured in {"0", "false", "no", "off"}:
        return False
    return is_production_mode()


def html_login_redirect(request: Request) -> RedirectResponse | None:
    """Redirect unauthenticated browser navigation while leaving APIs explicit."""

    if not browser_login_required() or request.method not in {"GET", "HEAD"}:
        return None
    path = request.url.path
    if path in {"/docs", "/redoc", "/openapi.json"}:
        return None
    if path == "/login" or path.startswith("/static/"):
        return None
    if path == "/login/change-password":
        session = browser_session_claims(request)
        if session is None:
            return RedirectResponse(url="/login?next=/login/change-password", status_code=303)
        return None
    if path.startswith("/api/") or path in {"/healthz", "/readyz"}:
        return None
    accepts = request.headers.get("accept", "").casefold()
    if accepts and "text/html" not in accepts and "*/*" not in accepts:
        return None
    session = browser_session_claims(request)
    if session is not None:
        identity, _claims = session
        if identity.password_change_required and path not in {
            "/settings/access",
            "/login/change-password",
        }:
            return RedirectResponse(url="/login/change-password", status_code=303)
        return None
    next_path = quote(path if path.startswith("/") else "/dashboard", safe="/")
    return RedirectResponse(url=f"/login?next={next_path}", status_code=303)
def require_admin(
    request: Request,
    admin_token: str | None = Security(admin_token_header),
    bearer_credentials: HTTPAuthorizationCredentials | None = Security(
        bearer_token_header
    ),
) -> OperatorContext:
    """Require an admin identity for control-plane changes."""

    if not admin_token and bearer_credentials is None:
        identity = browser_session_context(request)
        if identity is not None:
            if identity.password_change_required:
                raise HTTPException(status_code=403, detail="Password change required")
            if identity.role != "admin":
                raise HTTPException(status_code=403, detail="Admin scope required")
            clear_auth_failures(request, "admin")
            return identity

    expected_admin_token = configured_admin_token()
    if admin_token:
        if expected_admin_token and secrets.compare_digest(
            admin_token, expected_admin_token
        ):
            if is_production_mode() and secret_strength_state(expected_admin_token) != "strong":
                raise HTTPException(status_code=503, detail="Admin authentication unavailable")
            clear_auth_failures(request, "admin")
            return admin_control_context("admin-token", "admin-token")
        try:
            identity = context_from_admin_session(admin_token, request.app.state.store)
        except HTTPException as error:
            if error.status_code == 503:
                raise
        else:
            clear_auth_failures(request, "admin")
            return identity
        record_auth_failure(request, "admin")
        raise HTTPException(status_code=401, detail="Admin token required")
    if bearer_credentials:
        identity = bearer_context_for_request(request, bearer_credentials.credentials)
        if identity.role != "admin":
            record_auth_failure(request, "admin")
            raise HTTPException(status_code=403, detail="Admin scope required")
        clear_auth_failures(request, "admin")
        return identity
    record_auth_failure(request, "admin")
    raise HTTPException(status_code=401, detail="Admin token or bearer required")


def require_scope(required_scope: str) -> Any:
    """Build a dependency that requires one operator scope."""

    def dependency(
        operator: OperatorContext = Depends(require_operator),
    ) -> OperatorContext:
        if required_scope not in operator.scopes:
            raise HTTPException(
                status_code=403, detail=f"Scope required: {required_scope}"
            )
        return operator

    return dependency


def require_admin_scope(required_scope: str) -> Any:
    """Build a dependency that requires one admin role scope."""

    def dependency(admin: OperatorContext = Depends(require_admin)) -> OperatorContext:
        if required_scope not in admin.scopes:
            raise HTTPException(
                status_code=403, detail=f"Admin scope required: {required_scope}"
            )
        return admin

    return dependency


def require_operator(
    request: Request,
    operator_token: str | None = Security(operator_token_header),
    bearer_credentials: HTTPAuthorizationCredentials | None = Security(
        bearer_token_header
    ),
    admin_token: str | None = Security(admin_token_header),
) -> OperatorContext:
    """Validate the configured operator token without logging token material."""

    if not admin_token and not operator_token and bearer_credentials is None:
        identity = browser_session_context(request)
        if identity is not None:
            clear_auth_failures(request, "operator")
            return identity

    if admin_token:
        return require_admin(request, admin_token, bearer_credentials)
    expected_token = configured_operator_token()
    if operator_token and expected_token:
        if secrets.compare_digest(operator_token, expected_token):
            if is_production_mode() and configured_operator_token_strength() == "weak":
                record_auth_failure(request, "operator")
                raise HTTPException(status_code=503, detail=OPERATOR_TOKEN_RUNTIME_ERROR)
            clear_auth_failures(request, "operator")
            return OperatorContext()
        record_auth_failure(request, "operator")
        raise HTTPException(status_code=401, detail="Operator token required")
    if bearer_credentials:
        identity = bearer_context_for_request(request, bearer_credentials.credentials)
        clear_auth_failures(request, "operator")
        return identity
    if expected_token is None and identity_provider_config()["state"] != "configured":
        record_auth_failure(request, "operator")
        raise HTTPException(status_code=503, detail=OPERATOR_TOKEN_CONFIG_ERROR)
    record_auth_failure(request, "operator")
    raise HTTPException(status_code=401, detail="Operator token required")


def optional_operator_context(
    request: Request,
    admin_token: str | None = Security(admin_token_header),
    operator_token: str | None = Security(operator_token_header),
    bearer_credentials: HTTPAuthorizationCredentials | None = Security(
        bearer_token_header
    ),
) -> OperatorContext | None:
    """Return an operator context when supplied, otherwise keep read flow public."""

    if admin_token:
        return require_admin(request, admin_token, bearer_credentials)
    if not operator_token and bearer_credentials is None:
        identity = browser_session_context(request)
        if identity is not None and identity.password_change_required:
            return None
        return identity
    return require_operator(request, operator_token, bearer_credentials, None)


def require_authenticated_in_production(
    operator: OperatorContext | None = Depends(optional_operator_context),
) -> OperatorContext | None:
    """Require identity when customer data or browser access is protected."""

    if (is_production_mode() or browser_login_required()) and operator is None:
        raise HTTPException(status_code=401, detail="Operator token required")
    if operator is not None and operator.password_change_required:
        raise HTTPException(status_code=403, detail="Password change required")
    return operator


def require_assistant_access(
    operator: OperatorContext | None = Depends(optional_operator_context),
) -> OperatorContext | None:
    """Allow anonymous development preview or an identity with agent-run scope."""

    if operator is None:
        if is_production_mode():
            raise HTTPException(status_code=401, detail="Operator token required")
        return None
    if operator.password_change_required:
        raise HTTPException(status_code=403, detail="Password change required")
    if "agent:run" not in set(operator.scopes):
        raise HTTPException(status_code=403, detail="Scope required: agent:run")
    return operator


def require_agent_read_context(
    operator: OperatorContext | None = Depends(optional_operator_context),
) -> OperatorContext:
    """Require authenticated agent-registry read access."""

    if operator is None:
        raise HTTPException(status_code=401, detail="Operator token required")
    if "agent:read" not in set(operator.scopes):
        raise HTTPException(status_code=403, detail="Scope required: agent:read")
    return operator


def is_production_mode() -> bool:
    """Return whether the application should use production-safe defaults."""

    return os.getenv("AGENTIOT_ENV", "development").lower() == "production"


def allowed_hosts() -> list[str]:
    """Return configured trusted hosts for production deployments."""

    configured = os.getenv("AGENTIOT_ALLOWED_HOSTS", "")
    hosts = [host.strip() for host in configured.split(",") if host.strip()]
    if hosts:
        if is_production_mode() and "*" in hosts:
            raise RuntimeError("Wildcard trusted host is not allowed in production")
        return hosts
    if is_production_mode():
        raise RuntimeError("AGENTIOT_ALLOWED_HOSTS is required in production")
    return ["*"]


def cors_allowed_origins() -> list[str]:
    """Return explicit browser CORS origins without enabling wildcard production."""

    configured = os.getenv(CORS_ALLOWED_ORIGINS_ENV, "")
    origins = [origin.strip() for origin in configured.split(",") if origin.strip()]
    if is_production_mode() and "*" in origins:
        raise RuntimeError("Wildcard CORS origin is not allowed in production")
    return origins


def offhost_restore_receipt_public_key() -> Any | None:
    """Return the deployment-owned Ed25519 receipt verification key."""

    if Ed25519PublicKey is None or serialization is None:
        return None
    key_pem = (
        configured_secret_value(
            OFFHOST_RESTORE_RECEIPT_PUBLIC_KEY_ENV,
            OFFHOST_RESTORE_RECEIPT_PUBLIC_KEY_FILE_ENV,
        )
        or ""
    ).strip()
    if not key_pem:
        return None
    try:
        key = serialization.load_pem_public_key(key_pem.encode("utf-8"))
    except (TypeError, ValueError):
        return None
    return key if isinstance(key, Ed25519PublicKey) else None


def offhost_restore_receipt_signature_verified(payload: dict[str, Any]) -> bool:
    """Verify one purpose-bound Ed25519 restore receipt signature."""

    key = offhost_restore_receipt_public_key()
    supplied = str(payload.get("receipt_signature") or "")
    if key is None or not supplied.startswith(OFFHOST_RESTORE_RECEIPT_SIGNATURE_PREFIX):
        return False
    encoded_signature = supplied.removeprefix(
        OFFHOST_RESTORE_RECEIPT_SIGNATURE_PREFIX
    )
    try:
        signature = base64.urlsafe_b64decode(
            encoded_signature + "=" * (-len(encoded_signature) % 4)
        )
    except (ValueError, UnicodeError):
        return False
    if len(signature) != 64:
        return False
    unsigned = {
        name: value
        for name, value in payload.items()
        if name != "receipt_signature"
    }
    message = b"agentiot-offhost-restore-v5\0" + json.dumps(
        unsigned,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    try:
        key.verify(signature, message)
    except (InvalidSignature, ValueError):
        return False
    return True


def offhost_restore_receipt_key_id() -> str | None:
    """Return a non-secret identifier for the dedicated receipt key."""

    key = offhost_restore_receipt_public_key()
    if key is None or serialization is None:
        return None
    raw_key = key.public_bytes(
        encoding=serialization.Encoding.Raw,
        format=serialization.PublicFormat.Raw,
    )
    return hashlib.sha256(raw_key).hexdigest()


def offhost_restore_liveness_public_key() -> Any | None:
    """Return the independent host-verifier liveness public key."""

    if Ed25519PublicKey is None or serialization is None:
        return None
    key_pem = (
        configured_secret_value(
            OFFHOST_RESTORE_LIVENESS_PUBLIC_KEY_ENV,
            OFFHOST_RESTORE_LIVENESS_PUBLIC_KEY_FILE_ENV,
        )
        or ""
    ).strip()
    if not key_pem:
        return None
    try:
        key = serialization.load_pem_public_key(key_pem.encode("utf-8"))
    except (TypeError, ValueError):
        return None
    return key if isinstance(key, Ed25519PublicKey) else None


def offhost_restore_liveness_signature_verified(payload: dict[str, Any]) -> bool:
    """Verify one purpose-bound independent liveness signature."""

    key = offhost_restore_liveness_public_key()
    supplied = str(payload.get("liveness_signature") or "")
    if key is None or not supplied.startswith(OFFHOST_RESTORE_LIVENESS_SIGNATURE_PREFIX):
        return False
    encoded_signature = supplied.removeprefix(
        OFFHOST_RESTORE_LIVENESS_SIGNATURE_PREFIX
    )
    try:
        signature = base64.urlsafe_b64decode(
            encoded_signature + "=" * (-len(encoded_signature) % 4)
        )
    except (ValueError, UnicodeError):
        return False
    if len(signature) != 64:
        return False
    unsigned = {
        name: value
        for name, value in payload.items()
        if name != "liveness_signature"
    }
    message = b"agentiot-offhost-liveness-v1\0" + json.dumps(
        unsigned,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    try:
        key.verify(signature, message)
    except (InvalidSignature, ValueError):
        return False
    return True


def offhost_restore_liveness_key_id() -> str | None:
    """Return a non-secret identifier for the independent liveness key."""

    key = offhost_restore_liveness_public_key()
    if key is None or serialization is None:
        return None
    raw_key = key.public_bytes(
        encoding=serialization.Encoding.Raw,
        format=serialization.PublicFormat.Raw,
    )
    return hashlib.sha256(raw_key).hexdigest()


def read_bounded_regular_file(path: Path, max_bytes: int) -> bytes:
    """Read one no-follow regular file through a stable open descriptor."""

    descriptor = os.open(
        path,
        os.O_RDONLY
        | getattr(os, "O_NOFOLLOW", 0)
        | getattr(os, "O_CLOEXEC", 0),
    )
    try:
        before = os.fstat(descriptor)
        if (
            not stat.S_ISREG(before.st_mode)
            or before.st_nlink != 1
            or before.st_size <= 0
            or before.st_size > max_bytes
        ):
            raise ValueError("Receipt file identity is invalid")
        chunks: list[bytes] = []
        remaining = max_bytes + 1
        while remaining > 0:
            chunk = os.read(descriptor, min(65_536, remaining))
            if not chunk:
                break
            chunks.append(chunk)
            remaining -= len(chunk)
        content = b"".join(chunks)
        after = os.fstat(descriptor)
        if (
            before.st_dev != after.st_dev
            or before.st_ino != after.st_ino
            or before.st_size != after.st_size
            or before.st_nlink != after.st_nlink
            or len(content) != after.st_size
            or len(content) > max_bytes
        ):
            raise ValueError("Receipt file changed during read")
        return content
    finally:
        os.close(descriptor)


def strict_json_loads(content: str) -> Any:
    """Decode JSON while rejecting duplicate keys and floating-point values."""

    def object_from_pairs(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
        result: dict[str, Any] = {}
        for key, value in pairs:
            if key in result:
                raise ValueError("Duplicate JSON key")
            result[key] = value
        return result

    def reject_float(_value: str) -> float:
        raise ValueError("Floating-point JSON values are not supported")

    return json.loads(
        content,
        object_pairs_hook=object_from_pairs,
        parse_float=reject_float,
    )


def offhost_restore_liveness_status(
    *,
    receipt: dict[str, Any],
    receipt_digest: str,
    now: datetime,
) -> dict[str, Any]:
    """Validate a recent, independently signed host-side namespace proof."""

    configured_path = os.getenv(OFFHOST_RESTORE_LIVENESS_FILE_ENV, "").strip()
    if not configured_path:
        return {"state": "liveness_not_configured"}
    path = Path(configured_path).expanduser()
    if not path.is_absolute():
        return {"state": "liveness_path_invalid"}
    try:
        liveness_bytes = read_bounded_regular_file(path, 65_536)
        payload = strict_json_loads(liveness_bytes.decode("utf-8"))
    except (OSError, UnicodeError, ValueError, json.JSONDecodeError):
        return {"state": "liveness_invalid"}
    if not isinstance(payload, dict) or set(payload) != OFFHOST_RESTORE_LIVENESS_FIELDS:
        return {"state": "liveness_invalid"}
    checked_at = str(payload.get("checked_at") or "")
    expires_at = str(payload.get("expires_at") or "")
    parsed_checked_at = parse_audit_timestamp(checked_at)
    parsed_expires_at = parse_audit_timestamp(expires_at)
    nonce = str(payload.get("nonce") or "")
    provider_object_version = str(payload.get("provider_object_version") or "")
    retention_until = str(payload.get("retention_until") or "")
    parsed_retention_until = parse_audit_timestamp(retention_until)
    supplied_signature = str(payload.get("liveness_signature") or "")
    structurally_valid = (
        payload.get("schema_version") == OFFHOST_RESTORE_LIVENESS_SCHEMA
        and payload.get("status") == "verified"
        and re.fullmatch(r"ed25519:[A-Za-z0-9_-]{86}", supplied_signature)
        is not None
        and re.fullmatch(r"[a-f0-9]{64}", nonce) is not None
        and re.fullmatch(r"sha256:[a-f0-9]{64}", str(payload["receipt_digest"]))
        is not None
        and re.fullmatch(r"[a-f0-9]{64}", str(payload["receipt_key_id"]))
        is not None
        and re.fullmatch(r"[a-f0-9]{64}", str(payload["liveness_key_id"]))
        is not None
        and re.fullmatch(
            r"[A-Za-z0-9][A-Za-z0-9._:-]{7,127}",
            str(payload["deployment_id"]),
        )
        is not None
        and re.fullmatch(r"sha256:[a-f0-9]{64}", str(payload["backup_digest"]))
        is not None
        and re.fullmatch(r"sha256:[a-f0-9]{64}", str(payload["storage_profile_fingerprint"]))
        is not None
        and str(payload["filesystem_type"]) in {"cifs", "nfs", "nfs4"}
        and re.fullmatch(r"[1-9][0-9]*", str(payload["mount_id"])) is not None
        and re.fullmatch(r"sha256:[a-f0-9]{64}", str(payload["mount_source_fingerprint"]))
        is not None
        and payload.get("namespace_check")
        == "reopen_nofollow_mount_identity_match"
        and re.fullmatch(
            r"sha256:[a-f0-9]{64}", str(payload["provider_attestation_digest"])
        )
        is not None
        and re.fullmatch(r"[a-f0-9]{64}", str(payload["provider_key_id"]))
        is not None
        and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:-]{0,127}", provider_object_version)
        is not None
        and parsed_checked_at is not None
        and parsed_expires_at is not None
        and parsed_expires_at > parsed_checked_at
        and parsed_expires_at
        <= parsed_checked_at + timedelta(seconds=OFFHOST_RECEIPT_LIVENESS_SECONDS)
    )
    if not structurally_valid:
        return {"state": "liveness_invalid"}
    if offhost_restore_liveness_public_key() is None:
        return {"state": "liveness_signature_unavailable"}
    if not offhost_restore_liveness_signature_verified(payload):
        return {"state": "liveness_signature_invalid"}
    liveness_key_id = offhost_restore_liveness_key_id() or ""
    receipt_key_id = str(receipt.get("receipt_key_id") or "")
    if str(payload["liveness_key_id"]) != liveness_key_id:
        return {"state": "liveness_key_mismatch"}
    if liveness_key_id == receipt_key_id:
        return {"state": "liveness_key_not_separated"}
    if str(payload["provider_key_id"]) == receipt_key_id:
        return {"state": "provider_key_not_separated"}
    bindings_match = (
        str(payload["receipt_digest"]) == receipt_digest
        and str(payload["receipt_key_id"]) == receipt_key_id
        and str(payload["tenant_id"]) == str(receipt.get("tenant_id") or "")
        and str(payload["deployment_id"])
        == str(receipt.get("deployment_id") or "")
        and str(payload["backup_digest"])
        == str(receipt.get("backup_digest") or "")
        and str(payload["backup_object_name"])
        == str(receipt.get("backup_object_name") or "")
        and str(payload["storage_profile_fingerprint"])
        == str(receipt.get("storage_profile_fingerprint") or "")
        and str(payload["filesystem_type"])
        == str(receipt.get("filesystem_type") or "")
        and str(payload["mount_id"]) == str(receipt.get("mount_id") or "")
        and str(payload["mount_source_fingerprint"])
        == str(receipt.get("mount_source_fingerprint") or "")
    )
    if not bindings_match:
        return {"state": "liveness_binding_mismatch"}
    if parsed_checked_at > now + timedelta(
        seconds=BACKUP_EVIDENCE_FUTURE_TOLERANCE_SECONDS
    ):
        return {"state": "liveness_timestamp_invalid"}
    if parsed_expires_at <= now:
        return {"state": "liveness_expired"}
    if payload.get("provider_immutability") != "object_lock_attested":
        return {"state": "immutability_unattested"}
    if parsed_retention_until is None or parsed_retention_until <= now:
        return {"state": "immutability_expired"}
    return {
        "state": "verified",
        "checked_at": checked_at,
        "nonce_digest": hashlib.sha256(bytes.fromhex(nonce)).hexdigest(),
        "liveness_digest": "sha256:" + hashlib.sha256(liveness_bytes).hexdigest(),
        "provider_object_version": provider_object_version,
        "retention_until": retention_until,
        "storage_immutability": "object_lock_attested",
    }


def verify_mounted_offhost_backup(
    *,
    expected_digest: str,
    expected_size: int,
    liveness_digest: str,
) -> str:
    """Verify one mounted backup once per signed liveness observation."""

    configured_path = os.getenv(OFFHOST_RESTORE_BACKUP_FILE_ENV, "").strip()
    if not configured_path:
        return "backup_object_not_configured"
    configured = Path(configured_path).expanduser()
    if not configured.is_absolute():
        return "backup_object_path_invalid"
    if configured.is_symlink():
        return "backup_object_unavailable"
    path = configured
    descriptor = -1
    try:
        descriptor = os.open(
            path,
            os.O_RDONLY
            | getattr(os, "O_NOFOLLOW", 0)
            | getattr(os, "O_CLOEXEC", 0),
        )
        before = os.fstat(descriptor)
        if (
            not stat.S_ISREG(before.st_mode)
            or before.st_nlink != 1
            or before.st_size != expected_size
            or before.st_size <= 0
        ):
            return "backup_object_invalid"
        cache_key = (
            liveness_digest,
            before.st_dev,
            before.st_ino,
            before.st_size,
            before.st_mtime_ns,
            before.st_ctime_ns,
        )
        with OFFHOST_BACKUP_VERIFY_LOCK:
            cached_result = OFFHOST_BACKUP_VERIFY_CACHE.get(cache_key)
            if cached_result is not None:
                return cached_result
            digest = hashlib.sha256()
            offset = 0
            while offset < before.st_size:
                chunk = os.pread(
                    descriptor,
                    min(1024 * 1024, before.st_size - offset),
                    offset,
                )
                if not chunk:
                    return "backup_object_invalid"
                digest.update(chunk)
                offset += len(chunk)
            after = os.fstat(descriptor)
            entry = configured.stat(follow_symlinks=False)
            if (
                before.st_dev != after.st_dev
                or before.st_ino != after.st_ino
                or before.st_size != after.st_size
                or entry.st_dev != after.st_dev
                or entry.st_ino != after.st_ino
                or entry.st_size != after.st_size
            ):
                return "backup_object_changed"
            actual_digest = "sha256:" + digest.hexdigest()
            result = (
                "verified"
                if hmac.compare_digest(actual_digest, expected_digest)
                else "backup_object_digest_mismatch"
            )
            if len(OFFHOST_BACKUP_VERIFY_CACHE) >= 16:
                OFFHOST_BACKUP_VERIFY_CACHE.clear()
            OFFHOST_BACKUP_VERIFY_CACHE[cache_key] = result
        return result
    except OSError:
        return "backup_object_unavailable"
    finally:
        if descriptor >= 0:
            os.close(descriptor)


def enforce_network_discovery_scope(cidr: str, *, production: bool) -> None:
    """Restrict active discovery to deployment-owned RFC1918 ranges."""

    del production
    configured = os.getenv(NETWORK_DISCOVERY_ALLOWED_CIDRS_ENV, "").strip()
    if not configured:
        raise HTTPException(
            status_code=503,
            detail="Network discovery allowlist is not configured",
        )
    try:
        requested = ipaddress.ip_network(cidr.strip(), strict=False)
        allowed = [
            ipaddress.ip_network(value.strip(), strict=False)
            for value in configured.split(",")
            if value.strip()
        ]
    except ValueError as error:
        raise HTTPException(
            status_code=400,
            detail="Network discovery scope or allowlist is invalid",
        ) from error
    valid_allowlist = bool(allowed) and all(
        isinstance(network, ipaddress.IPv4Network)
        and any(network.subnet_of(private) for private in RFC1918_NETWORKS)
        for network in allowed
    )
    if not isinstance(requested, ipaddress.IPv4Network) or not valid_allowlist:
        raise HTTPException(
            status_code=503,
            detail="Network discovery allowlist is invalid",
        )
    if not any(requested.subnet_of(network) for network in allowed):
        raise HTTPException(
            status_code=403,
            detail="Network discovery scope is outside the deployment allowlist",
        )


def write_private_runtime_json(path: Path, payload: dict[str, Any]) -> None:
    """Atomically write one owner-only runtime state file."""

    path.parent.mkdir(parents=True, exist_ok=True)
    descriptor, temporary_name = tempfile.mkstemp(
        prefix=f".{path.name}.",
        suffix=".tmp",
        dir=path.parent,
    )
    temporary = Path(temporary_name)
    try:
        with os.fdopen(descriptor, "w", encoding="utf-8") as handle:
            json.dump(payload, handle, sort_keys=True, separators=(",", ":"))
            handle.write("\n")
            handle.flush()
            os.fchmod(handle.fileno(), 0o600)
            os.fsync(handle.fileno())
        os.replace(temporary, path)
        directory_fd = os.open(
            path.parent,
            os.O_RDONLY
            | getattr(os, "O_DIRECTORY", 0)
            | getattr(os, "O_NOFOLLOW", 0)
            | getattr(os, "O_CLOEXEC", 0),
        )
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
    finally:
        temporary.unlink(missing_ok=True)


def record_offhost_liveness_replay_state(
    *,
    tenant_id: str,
    deployment_id: str,
    nonce_digest: str,
    checked_at: str,
    receipt_digest: str,
    liveness_digest: str,
) -> str:
    """Atomically consume one independent liveness nonce per tenant deployment."""

    configured_path = os.getenv(OFFHOST_RESTORE_LEDGER_FILE_ENV, "").strip()
    if not configured_path or fcntl is None:
        return "replay_ledger_not_configured"
    configured = Path(configured_path).expanduser()
    if not configured.is_absolute():
        return "replay_ledger_path_invalid"
    if configured.is_symlink():
        return "replay_ledger_path_invalid"
    path = configured
    lock_path = path.with_name(path.name + ".lock")
    lock_descriptor = -1
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        lock_descriptor = os.open(
            lock_path,
            os.O_RDWR
            | os.O_CREAT
            | getattr(os, "O_NOFOLLOW", 0)
            | getattr(os, "O_CLOEXEC", 0),
            0o600,
        )
        lock_stat = os.fstat(lock_descriptor)
        if (
            not stat.S_ISREG(lock_stat.st_mode)
            or lock_stat.st_uid != os.geteuid()
            or lock_stat.st_mode & 0o077
        ):
            return "replay_ledger_invalid"
        fcntl.flock(lock_descriptor, fcntl.LOCK_EX)
        ledger: dict[str, Any] = {
            "schema_version": "agentiot.offhost-replay-ledger.v2",
            "deployments": {},
        }
        if path.exists():
            decoded = strict_json_loads(
                read_bounded_regular_file(path, 65_536).decode("utf-8")
            )
            if (
                not isinstance(decoded, dict)
                or decoded.get("schema_version")
                != "agentiot.offhost-replay-ledger.v2"
                or not isinstance(decoded.get("deployments"), dict)
            ):
                return "replay_ledger_invalid"
            ledger = decoded
        deployments = dict(ledger["deployments"])
        deployment_key = hashlib.sha256(
            f"{tenant_id}\0{deployment_id}".encode("utf-8")
        ).hexdigest()
        current = deployments.get(deployment_key)
        candidate_time = parse_audit_timestamp(checked_at)
        if candidate_time is None:
            return "replay_ledger_invalid"
        if isinstance(current, dict):
            current_nonce = str(current.get("nonce_digest") or "")
            current_liveness_digest = str(current.get("liveness_digest") or "")
            current_receipt_digest = str(current.get("receipt_digest") or "")
            current_time = parse_audit_timestamp(str(current.get("checked_at") or ""))
            if current_nonce == nonce_digest:
                if not (
                    hmac.compare_digest(current_liveness_digest, liveness_digest)
                    and hmac.compare_digest(current_receipt_digest, receipt_digest)
                ):
                    return "replay_conflict"
                return "recorded"
            if current_time is None or candidate_time <= current_time:
                return "replay_detected"
        deployments[deployment_key] = {
            "tenant_id": tenant_id,
            "deployment_id": deployment_id,
            "nonce_digest": nonce_digest,
            "checked_at": checked_at,
            "receipt_digest": receipt_digest,
            "liveness_digest": liveness_digest,
        }
        ledger["deployments"] = deployments
        write_private_runtime_json(path, ledger)
        return "recorded"
    except (OSError, UnicodeError, ValueError, json.JSONDecodeError):
        return "replay_ledger_invalid"
    finally:
        if lock_descriptor >= 0:
            if fcntl is not None:
                try:
                    fcntl.flock(lock_descriptor, fcntl.LOCK_UN)
                except OSError:
                    pass
            os.close(lock_descriptor)


def offhost_restore_receipt_status(cadence_hours: int) -> dict[str, Any]:
    """Validate a deployment-owned off-host restore receipt without paths."""

    required = is_production_mode() or env_flag_enabled(
        OFFHOST_RESTORE_REQUIRED_ENV
    )
    configured_path = os.getenv(OFFHOST_RESTORE_RECEIPT_FILE_ENV, "").strip()
    empty = {
        "required": required,
        "state": "not_configured" if required else "not_required",
        "verified_at": None,
        "backup_digest": None,
        "verified_tables": None,
        "checked_records": None,
        "release_bound": False,
        "identity_bound": False,
        "signature_verified": False,
        "receipt_key_bound": False,
        "receipt_file_bound": False,
        "deployment_bound": False,
        "backup_object_verified": False,
        "replay_protected": False,
        "storage_profile_id": None,
        "filesystem_type": None,
        "durability": None,
        "backup_object_name": None,
        "publication": None,
        "writer_isolation": None,
        "storage_immutability": None,
        "restore_consumer_requirement": None,
    }
    if not configured_path:
        return empty
    receipt_path = Path(configured_path)
    try:
        receipt_bytes = read_bounded_regular_file(receipt_path, 65_536)
        payload = strict_json_loads(receipt_bytes.decode("utf-8"))
    except (OSError, UnicodeError, ValueError, json.JSONDecodeError):
        return {**empty, "state": "invalid"}
    if not isinstance(payload, dict):
        return {**empty, "state": "invalid"}
    if payload.get("schema_version") == OFFHOST_RESTORE_LEGACY_RECEIPT_SCHEMA:
        return {**empty, "state": "legacy_receipt_rejected"}
    verified_at = str(payload.get("verified_at") or "")
    parsed_at = parse_audit_timestamp(verified_at)
    digest = str(payload.get("backup_digest") or "").lower()
    verified_tables = payload.get("verified_tables")
    checked_records = payload.get("checked_records")
    release_bound = str(payload.get("release_version") or "") == __version__
    identity_bound = (
        str(payload.get("tenant_id") or "") == configured_tenant_id()
        and str(payload.get("source_commit") or "") == source_commit_id()
        and str(payload.get("runtime_digest") or "") == runtime_manifest_digest()
    )
    deployment_bound = (
        str(payload.get("deployment_id") or "") == (configured_deployment_id() or "")
    )
    public_key_available = offhost_restore_receipt_public_key() is not None
    supplied_signature = str(payload.get("receipt_signature") or "")
    signature_verified = offhost_restore_receipt_signature_verified(payload)
    receipt_key_bound = str(payload.get("receipt_key_id") or "") == (
        offhost_restore_receipt_key_id() or ""
    )
    configured_file_digest = os.getenv(
        OFFHOST_RESTORE_RECEIPT_DIGEST_ENV,
        "",
    ).strip().lower()
    actual_file_digest = "sha256:" + hashlib.sha256(receipt_bytes).hexdigest()
    receipt_file_bound = bool(
        re.fullmatch(r"sha256:[a-f0-9]{64}", configured_file_digest)
        and hmac.compare_digest(configured_file_digest, actual_file_digest)
    )
    storage_profile_id = str(payload.get("storage_profile_id") or "")
    filesystem_type = str(payload.get("filesystem_type") or "").lower()
    mount_id = str(payload.get("mount_id") or "")
    mount_source_fingerprint = str(
        payload.get("mount_source_fingerprint") or ""
    ).lower()
    durability = str(payload.get("durability") or "")
    backup_size_bytes = payload.get("backup_size_bytes")
    backup_object_name = str(payload.get("backup_object_name") or "")
    publication = str(payload.get("publication") or "")
    writer_isolation = str(payload.get("writer_isolation") or "")
    storage_immutability = str(payload.get("storage_immutability") or "")
    retention_until = str(payload.get("retention_until") or "")
    parsed_retention_until = parse_audit_timestamp(retention_until)
    storage_profile_fingerprint = str(
        payload.get("storage_profile_fingerprint") or ""
    )
    restore_consumer_requirement = str(
        payload.get("restore_consumer_requirement") or ""
    )
    run_id = str(payload.get("run_id") or "")
    structurally_valid = (
        set(payload) == OFFHOST_RESTORE_RECEIPT_FIELDS
        and payload.get("schema_version") == OFFHOST_RESTORE_RECEIPT_SCHEMA
        and payload.get("status") == "verified"
        and payload.get("quick_check") == "ok"
        and payload.get("storage_separation") == "verified_remote_mount"
        and re.fullmatch(
            r"ed25519:[A-Za-z0-9_-]{86}", supplied_signature
        )
        is not None
        and re.fullmatch(
            r"[a-f0-9]{64}", str(payload.get("receipt_key_id") or "")
        )
        is not None
        and re.fullmatch(
            r"[A-Za-z0-9][A-Za-z0-9._:-]{7,127}",
            str(payload.get("deployment_id") or ""),
        )
        is not None
        and re.fullmatch(r"[a-z0-9][a-z0-9._-]{1,62}", storage_profile_id)
        is not None
        and re.fullmatch(
            r"sha256:[a-f0-9]{64}", storage_profile_fingerprint
        )
        is not None
        and filesystem_type in {"cifs", "nfs", "nfs4"}
        and re.fullmatch(r"[1-9][0-9]*", mount_id) is not None
        and re.fullmatch(
            r"sha256:[a-f0-9]{64}",
            mount_source_fingerprint,
        )
        is not None
        and durability == "file_fsync_and_directory_fsync"
        and re.fullmatch(
            r"agentiot-greenovax-[A-Za-z0-9.-]{1,120}-"
            r"[0-9]{8}T[0-9]{6}Z-[a-f0-9]{8}\.sqlite",
            backup_object_name,
        )
        is not None
        and publication == "renameat2_noreplace"
        and writer_isolation == "owner_uid_match_no_world_write"
        and storage_immutability in {"not_attested", "object_lock_attested"}
        and restore_consumer_requirement
        == "reopen_nofollow_match_signed_sha256_each_readiness"
        and isinstance(backup_size_bytes, int)
        and backup_size_bytes > 0
        and re.fullmatch(r"restore-[a-z0-9t-]{8,80}", run_id) is not None
        and payload.get("customer_safe") is True
        and re.fullmatch(r"sha256:[a-f0-9]{64}", digest) is not None
        and isinstance(verified_tables, int)
        and verified_tables >= len(RESTORE_VERIFICATION_TABLES)
        and isinstance(checked_records, int)
        and checked_records >= 0
        and parsed_at is not None
        and (
            (
                storage_immutability == "not_attested"
                and payload.get("retention_until") is None
            )
            or (
                storage_immutability == "object_lock_attested"
                and parsed_retention_until is not None
            )
        )
    )
    if not structurally_valid:
        return {**empty, "state": "invalid"}
    now = datetime.now(UTC)
    backup_object_state = "not_checked"
    replay_state = "not_checked"
    liveness: dict[str, Any] = {"state": "not_checked"}
    if not public_key_available:
        state = "signature_unavailable"
    elif not signature_verified:
        state = "signature_invalid"
    elif not receipt_key_bound:
        state = "receipt_key_mismatch"
    elif not configured_file_digest:
        state = "receipt_digest_unavailable"
    elif not receipt_file_bound:
        state = "receipt_digest_mismatch"
    elif not release_bound:
        state = "release_mismatch"
    elif not identity_bound:
        state = "identity_mismatch"
    elif not deployment_bound:
        state = "deployment_mismatch"
    elif parsed_at > now + timedelta(
        seconds=BACKUP_EVIDENCE_FUTURE_TOLERANCE_SECONDS
    ):
        state = "invalid_timestamp"
    elif (now - parsed_at).total_seconds() > cadence_hours * 3600:
        state = "stale"
    else:
        liveness = offhost_restore_liveness_status(
            receipt=payload,
            receipt_digest=actual_file_digest,
            now=now,
        )
        if liveness["state"] != "verified":
            state = str(liveness["state"])
        else:
            backup_object_state = verify_mounted_offhost_backup(
                expected_digest=digest,
                expected_size=int(backup_size_bytes),
                liveness_digest=str(liveness["liveness_digest"]),
            )
            if backup_object_state != "verified":
                state = backup_object_state
            else:
                replay_state = record_offhost_liveness_replay_state(
                    tenant_id=str(payload["tenant_id"]),
                    deployment_id=str(payload["deployment_id"]),
                    nonce_digest=str(liveness["nonce_digest"]),
                    checked_at=str(liveness["checked_at"]),
                    receipt_digest=actual_file_digest,
                    liveness_digest=str(liveness["liveness_digest"]),
                )
                state = "recorded" if replay_state == "recorded" else replay_state
    return {
        "required": required,
        "state": state,
        "verified_at": verified_at,
        "backup_digest": digest,
        "verified_tables": verified_tables,
        "checked_records": checked_records,
        "release_bound": release_bound,
        "identity_bound": identity_bound,
        "signature_verified": signature_verified,
        "receipt_key_bound": receipt_key_bound,
        "receipt_file_bound": receipt_file_bound,
        "deployment_bound": deployment_bound,
        "backup_object_verified": backup_object_state == "verified",
        "replay_protected": replay_state == "recorded",
        "storage_profile_id": storage_profile_id,
        "filesystem_type": filesystem_type,
        "durability": durability,
        "backup_object_name": backup_object_name,
        "publication": publication,
        "writer_isolation": writer_isolation,
        "storage_immutability": liveness.get(
            "storage_immutability",
            storage_immutability,
        ),
        "retention_until": liveness.get("retention_until", retention_until or None),
        "restore_consumer_requirement": restore_consumer_requirement,
    }


def backup_retention_status(store: CoreStore | None = None) -> dict[str, Any]:
    """Return backup-retention readiness without exposing policy text or paths."""

    policy = os.getenv(BACKUP_POLICY_ENV, "").strip()
    retention_days = env_int(BACKUP_RETENTION_DAYS_ENV, 30, 1, 3650)
    cadence_hours = env_int(BACKUP_CADENCE_HOURS_ENV, 24, 1, 168)
    restore_test_at = os.getenv(BACKUP_LAST_RESTORE_TEST_AT_ENV, "").strip()
    restore_evidence = store.latest_restore_test_evidence() if store else None
    restore_test_state = "manual_timestamp_only" if restore_test_at else "not_recorded"
    restore_profile_current: bool | None = None
    restore_evidence_age_hours: float | None = None
    if restore_evidence:
        restore_test_at = str(restore_evidence["restore_test_at"])
        restore_test_state = str(restore_evidence["restore_test_state"])
        if restore_test_state == "recorded":
            restore_profile_current = (
                restore_evidence.get("restore_table_profile_fingerprint")
                == restore_table_profile_fingerprint()
                and int(restore_evidence.get("restore_verified_tables") or 0)
                == len(RESTORE_VERIFICATION_TABLES)
            )
            parsed_restore_at = parse_audit_timestamp(restore_test_at)
            now = datetime.now(UTC)
            if not restore_profile_current:
                restore_test_state = "profile_mismatch"
            elif parsed_restore_at is None or parsed_restore_at > now + timedelta(
                seconds=BACKUP_EVIDENCE_FUTURE_TOLERANCE_SECONDS
            ):
                restore_test_state = "invalid_timestamp"
            else:
                restore_evidence_age_hours = max(
                    0.0,
                    (now - parsed_restore_at).total_seconds() / 3600,
                )
                if restore_evidence_age_hours > cadence_hours:
                    restore_test_state = "stale"
    policy_configured = bool(policy)
    off_host_restore = offhost_restore_receipt_status(cadence_hours)
    local_restore_ready = restore_test_state == "recorded"
    off_host_restore_ready = (
        not off_host_restore["required"]
        or off_host_restore["state"] == "recorded"
    )
    status = (
        "ready"
        if policy_configured and local_restore_ready and off_host_restore_ready
        else "restore_review_required"
        if policy_configured
        else "customer_action_required"
    )
    return {
        "status": status,
        "control_id": "backup-retention",
        "policy_configured": policy_configured,
        "retention_days": retention_days,
        "cadence_hours": cadence_hours,
        "restore_test_state": restore_test_state,
        "restore_profile_current": restore_profile_current,
        "restore_evidence_age_hours": (
            round(restore_evidence_age_hours, 2)
            if restore_evidence_age_hours is not None
            else None
        ),
        "policy_fingerprint": secret_fingerprint(policy),
        "restore_test_at": restore_test_at or None,
        "restore_audit_event_id": (
            int(restore_evidence["restore_audit_event_id"])
            if restore_evidence
            else None
        ),
        "restore_verified_tables": (
            int(restore_evidence["restore_verified_tables"])
            if restore_evidence
            else None
        ),
        "restore_checked_records": (
            int(restore_evidence["restore_checked_records"])
            if restore_evidence
            else None
        ),
        "restore_evidence_fingerprint": (
            str(restore_evidence["restore_evidence_fingerprint"])
            if restore_evidence
            else None
        ),
        "off_host_restore_required": off_host_restore["required"],
        "off_host_restore_state": off_host_restore["state"],
        "off_host_restore_at": off_host_restore["verified_at"],
        "off_host_backup_digest": off_host_restore["backup_digest"],
        "off_host_verified_tables": off_host_restore["verified_tables"],
        "evidence": (
            "Backup policy, local restore, and off-host restore evidence are current."
            if status == "ready" and off_host_restore["required"]
            else "Backup policy metadata is configured with bounded retention and cadence."
            if policy_configured
            else "Customer-approved backup policy metadata is required before live operational data is kept."
        ),
        "next_gate": (
            "backup_policy_configuration"
            if not policy_configured
            else "off_host_restore_review"
            if local_restore_ready and not off_host_restore_ready
            else "production_owner_review"
            if local_restore_ready
            else "restore_test_review"
        ),
        "customer_safe": True,
    }


def public_access_url_status() -> dict[str, Any]:
    """Return a secret-free public access URL status for deployment evidence."""

    raw_url = os.getenv(PUBLIC_ACCESS_URL_ENV, "").strip()
    if not raw_url:
        return {"configured": False, "url": None}
    parsed = urlparse(raw_url)
    if (
        parsed.scheme not in {"http", "https"}
        or not parsed.hostname
        or parsed.username
        or parsed.password
        or SECRET_LIKE_PATTERN.search(raw_url)
        or PRIVATE_PATH_PATTERN.search(raw_url)
        or not public_access_hostname_allowed(parsed.hostname)
    ):
        return {"configured": False, "url": None}
    port = f":{parsed.port}" if parsed.port else ""
    safe_url = f"{parsed.scheme}://{parsed.hostname}{port}"
    return {"configured": True, "url": safe_url}


def public_access_hostname_allowed(hostname: str) -> bool:
    """Return whether a public access host is safe to show in customer reports."""

    host = hostname.strip().lower().rstrip(".")
    if not host or host in {"localhost", "host.docker.internal"}:
        return False
    if host.endswith(".local"):
        return False
    try:
        ipaddress.ip_address(host)
        return False
    except ValueError:
        return "." in host


def tls_browser_trust_status() -> dict[str, Any]:
    """Return TLS trust posture without certificate material or local paths."""

    source = os.getenv(TLS_CERT_SOURCE_ENV, "self-signed-lab").strip().lower()
    trusted_sources = {
        "customer-ca",
        "customer-managed-ca",
        "managed-ca",
        "public-ca",
        "tailscale",
    }
    browser_trusted = (
        env_flag_enabled(TLS_BROWSER_TRUSTED_ENV) or source in trusted_sources
    )
    return {
        "certificate_source": source or "self-signed-lab",
        "browser_trusted": browser_trusted,
        "public_access": public_access_url_status(),
        "trust_requirement": (
            "Browser-trusted DNS certificate or customer-approved local trust is required for public review."
            if not browser_trusted
            else "Browser trust has been declared by the deployment runtime."
        ),
    }


def production_secret_free_preflight(
    production: bool,
    store: CoreStore | None = None,
    mqtt_runtime_status: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Return secret-free preflight checks for customer-owned go-live controls."""

    trusted_hosts = allowed_hosts()
    host_ready = trusted_hosts != ["*"]
    tls_mode = os.getenv(TLS_TERMINATION_ENV, "").strip().lower()
    tls_terminated = tls_mode == "reverse-proxy"
    tls_trust = tls_browser_trust_status()
    tls_ready = tls_terminated and tls_trust["browser_trusted"]
    tls_state = (
        "ready"
        if tls_ready
        else "review_required" if tls_terminated else "customer_action_required"
    )
    backup_status = backup_retention_status(store)
    backup_ready = backup_status["status"] == "ready"
    restore_ready = (
        backup_status["restore_test_state"] == "recorded"
        and (
            not backup_status["off_host_restore_required"]
            or backup_status["off_host_restore_state"] == "recorded"
        )
    )
    idp_config = identity_provider_config()
    idp_ready = idp_config["state"] == "configured"
    mqtt_config = mqtt_broker_config()
    runtime_status = mqtt_runtime_status or {}
    mqtt_ready = bool(mqtt_config["host"]) and mqtt_runtime_ready(
        mqtt_config,
        connected=bool(runtime_status.get("connected")),
        last_error=runtime_status.get("last_error"),
        production=production,
    )
    checks = [
        {
            "check_id": "reverse-proxy-tls",
            "label": "Browser-trusted reverse-proxy TLS",
            "state": tls_state,
            "priority": "P0",
            "can_close_without_customer_secret": True,
            "customer_decision_required": not tls_ready,
            "runtime_signals": {
                "production_mode": production,
                "trusted_hosts_configured": host_ready,
                "tls_termination_mode": (
                    "reverse-proxy" if tls_terminated else "not_configured"
                ),
                "certificate_source": tls_trust["certificate_source"],
                "browser_trusted": tls_trust["browser_trusted"],
                "public_access_configured": tls_trust["public_access"]["configured"],
                "public_access_url": tls_trust["public_access"]["url"],
            },
            "required_evidence": tls_trust["trust_requirement"],
            "next_gate": (
                "production_owner_review"
                if tls_ready
                else "trusted_tls_certificate_review"
                if tls_terminated
                else "customer_tls_configuration"
            ),
            "recording_boundary": "Record owner evidence after browser verification; no certificates, keys, host paths, or contact data are accepted here.",
        },
        {
            "check_id": "backup-retention",
            "label": "Backup and retention policy",
            "state": backup_status["status"],
            "priority": "P0",
            "can_close_without_customer_secret": True,
            "customer_decision_required": not backup_ready,
            "runtime_signals": {
                "policy_configured": backup_status["policy_configured"],
                "retention_days": backup_status["retention_days"],
                "cadence_hours": backup_status["cadence_hours"],
                "restore_test_state": backup_status["restore_test_state"],
                "policy_fingerprint": backup_status["policy_fingerprint"],
                "restore_test_at": backup_status["restore_test_at"],
                "restore_audit_event_id": backup_status["restore_audit_event_id"],
                "restore_checked_records": backup_status["restore_checked_records"],
                "off_host_restore_required": backup_status[
                    "off_host_restore_required"
                ],
                "off_host_restore_state": backup_status[
                    "off_host_restore_state"
                ],
                "off_host_restore_at": backup_status["off_host_restore_at"],
                "off_host_backup_digest": backup_status[
                    "off_host_backup_digest"
                ],
            },
            "required_evidence": "Customer-approved retention metadata plus current local and off-host restore evidence are required without exposing backup paths.",
            "next_gate": backup_status["next_gate"],
            "recording_boundary": "Store only metadata and fingerprint evidence; never store backup paths, credentials, policy text, or contact data.",
        },
        {
            "check_id": "backup-restore-test",
            "label": "Backup restore test",
            "state": "ready" if restore_ready else "review_required",
            "priority": "P1",
            "can_close_without_customer_secret": True,
            "customer_decision_required": not restore_ready,
            "runtime_signals": {
                "restore_test_state": backup_status["restore_test_state"],
                "restore_test_at": backup_status["restore_test_at"],
                "restore_audit_event_id": backup_status["restore_audit_event_id"],
                "restore_checked_records": backup_status["restore_checked_records"],
                "off_host_restore_state": backup_status[
                    "off_host_restore_state"
                ],
                "off_host_restore_at": backup_status["off_host_restore_at"],
            },
            "required_evidence": "Local integrity verification and an independently stored restore receipt are recorded before live operational data retention is accepted.",
            "next_gate": "production_owner_review" if restore_ready else "restore_test_review",
            "recording_boundary": "Record timestamp-style evidence only; do not store restore logs or backup file locations.",
        },
        {
            "check_id": "identity-provider",
            "label": "Identity provider",
            "state": "ready" if idp_ready else "customer_action_required",
            "priority": "P0",
            "can_close_without_customer_secret": False,
            "customer_decision_required": not idp_ready,
            "runtime_signals": {
                "state": idp_config["state"],
                "issuer_configured": bool(idp_config["issuer_configured"]),
                "audience_configured": bool(idp_config["audience_configured"]),
                "jwks_configured": bool(idp_config["jwks_configured"]),
                "shared_secret_configured": bool(idp_config["shared_secret_configured"]),
                "validation_method": idp_config["validation_method"],
            },
            "required_evidence": "Customer identity policy must provide issuer, audience, and a validated signing source before bearer-token go-live.",
            "next_gate": "production_owner_review" if idp_ready else "customer_identity_configuration",
            "recording_boundary": "Store readiness metadata only; do not store passwords, API keys, private keys, tokens, or user contact data.",
        },
        {
            "check_id": "mqtt-broker-subscriber",
            "label": "MQTT broker subscriber",
            "state": "ready" if mqtt_ready else "customer_action_required",
            "priority": "P0",
            "can_close_without_customer_secret": False,
            "customer_decision_required": not mqtt_ready,
            "runtime_signals": {
                "broker_configured": bool(mqtt_config["host"]),
                "runtime_connected": bool(runtime_status.get("connected")),
                "runtime_status": runtime_status.get("status", "not_configured"),
                "topic_prefix_configured": bool(mqtt_config["topic_prefix"]),
                "tls_requested": bool(mqtt_config["tls_enabled"]),
                "auth_configured": bool(mqtt_config["username"] or mqtt_config["password"]),
                "autostart_requested": bool(mqtt_config["autostart"]),
            },
            "required_evidence": "Customer broker host, topic namespace, authentication, TLS policy, and field test window must be approved before live device ingestion.",
            "next_gate": "production_owner_review" if mqtt_ready else "customer_mqtt_broker_configuration",
            "recording_boundary": "Store connectivity metadata and fingerprints only; do not store broker passwords, certificate material, raw topics with private identifiers, or device secrets.",
        },
    ]
    ready_count = sum(1 for item in checks if item["state"] == "ready")
    action_required_count = sum(
        1 for item in checks if item["state"] != "ready"
    )
    return {
        "status": "ready" if action_required_count == 0 else "action_required",
        "version": __version__,
        "prepared_for": CUSTOMER_NAME,
        "prepared_by": CONTRACTOR_NAME,
        "summary": {
            "checked_control_count": len(checks),
            "ready_count": ready_count,
            "action_required_count": action_required_count,
            "recordable_without_secret_count": sum(
                1 for item in checks if item["can_close_without_customer_secret"]
            ),
            "customer_secret_required_count": sum(
                1 for item in checks if not item["can_close_without_customer_secret"]
            ),
        },
        "checks": checks,
        "evidence_links": [
            {"label": "Production hardening", "endpoint": "/api/production/hardening"},
            {"label": "Secret-free preflight", "endpoint": "/api/production/preflight"},
            {"label": "Backup retention", "endpoint": "/api/production/backup-retention"},
            {"label": "Identity policy", "endpoint": "/api/access/policy"},
            {"label": "MQTT broker", "endpoint": "/api/adapters/mqtt/broker/status"},
            {"label": "Production action plan", "endpoint": "/api/production/action-plan"},
        ],
        "privacy": {
            "customer_safe": True,
            "credential_values_returned": False,
            "certificate_material_returned": False,
            "backup_paths_returned": False,
            "policy_text_returned": False,
            "contact_data_returned": False,
            "admin_write_endpoints_returned": False,
        },
    }


def public_settings(production: bool, store: CoreStore | None = None) -> list[dict[str, Any]]:
    """Return customer-safe deployment readiness without secrets."""

    trusted_hosts = allowed_hosts()
    host_state = "development wildcard" if trusted_hosts == ["*"] else "configured"
    docs_state = "hidden in production" if production else "visible for development"
    items = [
        {
            "control": "Runtime mode",
            "state": "production" if production else "development",
            "evidence": "AGENTIOT_ENV controls production-safe defaults.",
        },
        {
            "control": "Operator write gate",
            "state": "enabled",
            "evidence": f"State-changing APIs require {OPERATOR_TOKEN_HEADER} or a valid bearer role.",
        },
        {
            "control": "Identity provider",
            "state": identity_provider_config()["state"],
            "evidence": "Bearer token validation checks issuer, audience, expiry, role, and scope.",
        },
        {
            "control": "Trusted hosts",
            "state": host_state,
            "evidence": "Host allowlist is environment configurable.",
        },
        {
            "control": "Persistence",
            "state": "sqlite",
            "evidence": "Edge-friendly local store for Phase 2 baseline records.",
        },
        {
            "control": "Configuration management",
            "state": "enabled",
            "evidence": "Operator-managed profiles define desired firmware and telemetry interval.",
        },
        {
            "control": "Firmware compatibility",
            "state": "enabled",
            "evidence": "Read-only checks evaluate hardware, firmware version, and target runtime.",
        },
        {
            "control": "MQTT broker subscriber",
            "state": "configured" if mqtt_broker_config()["host"] else "not_configured",
            "evidence": "Broker host, topic filter, auth, TLS, and autostart are environment configurable.",
        },
        {
            "control": "Bounded simulation",
            "state": "enabled",
            "evidence": "Operator-approved simulation is capped at 8 devices and 96 telemetry samples.",
        },
        {
            "control": "API documentation",
            "state": docs_state,
            "evidence": "Interactive docs are hidden when production mode is active.",
        },
        {
            "control": "Delivery runtime",
            "state": "docker",
            "evidence": "Docker image and compose runtime are part of the release package.",
        },
    ]
    if store is not None:
        governance = ai_resource_governance(store)
        credential_count = sum(
            1 for item in governance["credentials"] if item["credential_configured"]
        )
        items.extend(
            [
                {
                    "control": "AI model services",
                    "state": "configured" if credential_count else "waiting_for_credentials",
                    "evidence": (
                        f"{credential_count} cloud/local model credential profile(s) are "
                        "configured with fingerprint-only responses."
                    ),
                },
                {
                    "control": "AI token ledger",
                    "state": "enabled",
                    "evidence": (
                        f"{governance['token_usage']['summary']['window_count']} usage "
                        "window(s) store token counts only, never prompts or answers."
                    ),
                },
                {
                    "control": "AI memory policy",
                    "state": governance["recommendation"]["status"],
                    "evidence": (
                        f"{governance['memory_policy']['max_memory_mb']} MB cap, "
                        f"{governance['memory_policy']['retention_hours']} hour retention, "
                        f"{governance['recommendation']['usage_percent']}% estimated use."
                    ),
                },
            ]
        )
    return items


def production_hardening_status(store: CoreStore, production: bool) -> dict[str, Any]:
    """Return customer-safe production hardening status."""

    trusted_hosts = allowed_hosts()
    token_or_identity = (
        operator_token_ready_for_runtime(production)
        or identity_provider_config()["state"] == "configured"
    )
    docs_hidden = production
    identity_ready = identity_provider_config()["state"] == "configured"
    mqtt_ready = bool(mqtt_broker_config()["host"])
    backup_status = backup_retention_status(store)
    tls_mode = os.getenv(TLS_TERMINATION_ENV, "").strip().lower()
    tls_terminated = tls_mode == "reverse-proxy"
    tls_trust = tls_browser_trust_status()
    tls_ready = tls_terminated and tls_trust["browser_trusted"]
    tls_state = (
        "ready"
        if tls_ready
        else "review_required" if tls_terminated else "customer_action_required"
    )
    items = [
        {
            "control_id": "runtime-mode",
            "control": "Runtime mode",
            "state": "ready" if production else "development_visible",
            "evidence": "Production mode disables interactive API documentation.",
        },
        {
            "control_id": "trusted-hosts",
            "control": "Trusted hosts",
            "state": "ready" if trusted_hosts != ["*"] else "development_visible",
            "evidence": "Host allowlist is required before production operation.",
        },
        {
            "control_id": "operator-write-gate",
            "control": "Operator write gate",
            "state": "ready" if token_or_identity else "action_required",
            "evidence": "Write actions require a strong operator token or bearer identity in production.",
        },
        {
            "control_id": "identity-provider",
            "control": "Identity provider",
            "state": "ready" if identity_ready else "customer_action_required",
            "evidence": "Issuer, audience, expiry, role, and scope are validated when configured.",
        },
        {
            "control_id": "mqtt-broker-subscriber",
            "control": "MQTT broker subscriber",
            "state": "ready" if mqtt_ready else "customer_action_required",
            "evidence": "Customer broker host, topic filter, auth, and TLS settings are required for live field devices.",
        },
        {
            "control_id": "interactive-api-documentation",
            "control": "Interactive API documentation",
            "state": "ready" if docs_hidden else "development_visible",
            "evidence": "OpenAPI, Swagger UI, and ReDoc are hidden in production mode.",
        },
        {
            "control_id": "reverse-proxy-tls",
            "control": "Browser-trusted reverse-proxy TLS",
            "state": tls_state,
            "evidence": tls_trust["trust_requirement"],
            "certificate_source": tls_trust["certificate_source"],
            "browser_trusted": tls_trust["browser_trusted"],
            "public_access_configured": tls_trust["public_access"]["configured"],
            "public_access_url": tls_trust["public_access"]["url"],
            "tls_termination_mode": "reverse-proxy" if tls_terminated else "not_configured",
        },
        {
            "control_id": "backup-retention",
            "control": "Backup and retention",
            "state": backup_status["status"],
            "evidence": backup_status["evidence"],
            "retention_days": backup_status["retention_days"],
            "cadence_hours": backup_status["cadence_hours"],
            "restore_test_state": backup_status["restore_test_state"],
            "policy_fingerprint": backup_status["policy_fingerprint"],
        },
        {
            "control_id": "clean-customer-release",
            "control": "Clean customer release",
            "state": "ready",
            "evidence": "Release builder excludes non-customer governance and execution material.",
        },
        {
            "control_id": "customer-feedback-loop",
            "control": "Customer feedback loop",
            "state": "ready",
            "evidence": "Bounded feedback endpoint records role, area, rating, and comment only.",
        },
    ]
    recorded_controls = {
        item["control_id"]: item for item in store.list_production_readiness_controls()
    }
    for item in items:
        recorded = recorded_controls.get(item["control_id"])
        if recorded:
            item["state"] = recorded["state"]
            item["evidence"] = recorded["evidence"]
            item["owner"] = recorded["owner"]
            item["source"] = "readiness_control"
            item["updated_at"] = recorded["updated_at"]
        else:
            item["owner"] = "system"
            item["source"] = "system"
            item["updated_at"] = None
    score = 0
    for item in items:
        if item["state"] == "ready":
            score += 12
        elif item["state"] == "development_visible":
            score += 8
        elif item["state"] == "review_required":
            score += 6
    all_ready = all(item["state"] == "ready" for item in items)
    return {
        "status": "ok",
        "ready": all_ready,
        "readiness_score": min(score, 100),
        "next_gate": (
            "production_owner_decision"
            if all_ready
            else "customer_feedback_and_production_owner_approval"
        ),
        "items": items,
    }


def customer_feedback_summary(store: CoreStore) -> dict[str, Any]:
    """Return bounded feedback aggregates for owner review."""

    feedback = store.list_customer_feedback()
    areas: dict[str, int] = {}
    rating_total = 0
    for item in feedback:
        area = str(item.get("area", "unknown"))
        areas[area] = areas.get(area, 0) + 1
        rating_total += int(item.get("rating") or 0)
    count = len(feedback)
    average_rating = round(rating_total / count, 2) if count else 0.0
    return {
        "status": "ok",
        "feedback_count": count,
        "average_rating": average_rating,
        "areas": areas,
        "stored_contact_data": False,
        "next_gate": "production_owner_feedback_review",
    }


def production_approval_package(store: CoreStore, production: bool) -> dict[str, Any]:
    """Return customer-safe decision package for production owner signoff."""

    hardening = production_hardening_status(store, production)
    feedback = customer_feedback_summary(store)
    feedback_count = feedback["feedback_count"]
    ai_route = ai_routing_status(store)
    model_matrix = ai_model_benchmark_matrix(store, production)
    backup_status = backup_retention_status(store)
    credential_count = sum(
        1
        for item in store.list_model_credentials()
        if item.get("credential_configured")
    )
    recorded_decisions = {
        item["decision_id"]: item for item in store.list_owner_decisions()
    }
    decision_items = [
        {
            "decision_id": "release-baseline",
            "decision": "Release baseline",
            "state": "ready",
            "evidence": f"Version {__version__} source, tests, Docker, license, and release manifest are prepared.",
        },
        {
            "decision_id": "phase-1-closure",
            "decision": "Phase 1 commercial baseline review",
            "state": "customer_action_required",
            "evidence": (
                "Owner must approve the recorded commercial baseline v1.7 metadata, "
                "without implying workshop, procurement, hardware, handover, or "
                "contractual milestone acceptance."
            ),
        },
        {
            "decision_id": "production-hardening",
            "decision": "Production hardening",
            "state": "owner_review_required",
            "evidence": f"Readiness score {hardening['readiness_score']} with customer action items.",
        },
        {
            "decision_id": "hosting-owner",
            "decision": "Hosting owner",
            "state": "customer_action_required",
            "evidence": "Customer must confirm DNS, reverse proxy, monitoring, and operating owner.",
        },
        {
            "decision_id": "reverse-proxy-tls",
            "decision": "Reverse-proxy TLS",
            "state": "customer_action_required",
            "evidence": "Public placement requires HTTPS termination before go-live.",
        },
        {
            "decision_id": "backup-retention",
            "decision": "Backup and retention",
            "state": backup_status["status"],
            "evidence": (
                "Backup policy metadata and restore evidence are ready for owner review."
                if backup_status["status"] == "ready"
                else "Backup policy metadata is configured; restore evidence is still required."
                if backup_status["status"] == "restore_review_required"
                else "Customer-approved retention policy is required before live operational data is kept."
            ),
        },
        {
            "decision_id": "identity-provider",
            "decision": "Identity provider",
            "state": (
                "ready"
                if identity_provider_config()["state"] == "configured"
                else "customer_action_required"
            ),
            "evidence": "Issuer, audience, expiry, role, and scope validation must match customer identity policy.",
        },
        {
            "decision_id": "mqtt-broker-subscriber",
            "decision": "MQTT broker subscriber",
            "state": (
                "ready"
                if mqtt_broker_config()["host"]
                else "customer_action_required"
            ),
            "evidence": "Customer broker endpoint, topic namespace, authentication, TLS policy, and field connectivity evidence are required before live MQTT ingestion.",
        },
        {
            "decision_id": "ai-model-route-approval",
            "decision": "AI model route approval",
            "state": "customer_action_required",
            "evidence": (
                f"Active route {ai_route['active_route']} with "
                f"{credential_count} configured credential source(s), "
                f"runtime_allowed={ai_route['runtime_allowed']}, and "
                f"{model_matrix['summary']['average_fit_score']}% model-route fit. "
                "Owner must approve fallback-only delivery or provide approved "
                "local/cloud credentials before external parity claims."
            ),
        },
        {
            "decision_id": "customer-feedback",
            "decision": "Customer feedback",
            "state": "ready_for_review" if feedback_count else "waiting_for_feedback",
            "evidence": f"{feedback_count} feedback record(s) available for owner review.",
        },
        {
            "decision_id": "phase-2-closure",
            "decision": "Phase 2 closure",
            "state": "pending_owner_signoff",
            "evidence": "Final closure depends on feedback review and production-owner decisions.",
        },
    ]
    for item in decision_items:
        recorded = recorded_decisions.get(item["decision_id"])
        if not recorded:
            item["source"] = "system"
            item["decided_by"] = None
            item["decision_note"] = ""
            item["updated_at"] = None
            continue
        item["state"] = recorded["state"]
        item["source"] = "owner_decision"
        item["decided_by"] = recorded["decided_by"]
        item["decision_note"] = recorded["decision_note"]
        item["updated_at"] = recorded["updated_at"]
        item["evidence"] = f"{item['evidence']} Owner decision recorded: {recorded['state']}."
    open_decisions = [
        item for item in decision_items if item["state"] not in {"ready", "approved"}
    ]
    secret_or_runtime_config_ids = {
        "identity-provider",
        "mqtt-broker-subscriber",
        "ai-model-route-approval",
    }
    owner_approved = not open_decisions
    next_owner_action = (
        open_decisions[0]["evidence"] if open_decisions else "All owner decisions are approved."
    )
    summary = {
        "decision_count": len(decision_items),
        "open_decision_count": len(open_decisions),
        "ready_decision_count": sum(
            1 for item in decision_items if item["state"] in {"ready", "approved"}
        ),
        "customer_action_required_count": sum(
            1 for item in decision_items if item["state"] == "customer_action_required"
        ),
        "owner_review_required_count": sum(
            1 for item in decision_items if item["state"] == "owner_review_required"
        ),
        "secret_or_runtime_config_required_count": sum(
            1 for item in open_decisions if item["decision_id"] in secret_or_runtime_config_ids
        ),
        "feedback_count": feedback_count,
        "hardening_readiness_score": hardening["readiness_score"],
        "active_ai_route": ai_route["active_route"],
        "model_credential_source_count": credential_count,
        "customer_decision_required": bool(open_decisions),
        "next_owner_action": next_owner_action,
    }
    return {
        "status": "owner_approved" if owner_approved else "owner_review_required",
        "release_version": __version__,
        "prepared_for": CUSTOMER_NAME,
        "prepared_by": CONTRACTOR_NAME,
        "next_gate": "phase_3_final_acceptance"
        if owner_approved
        else "production_owner_signoff",
        "summary": summary,
        "decision_items": decision_items,
        "evidence_links": [
            {"label": "Production hardening", "endpoint": "/api/production/hardening"},
            {"label": "Backup retention", "endpoint": "/api/production/backup-retention"},
            {"label": "MQTT broker", "endpoint": "/api/adapters/mqtt/broker/status"},
            {"label": "Production action plan", "endpoint": "/api/production/action-plan"},
            {"label": "Feedback summary", "endpoint": "/api/customer/feedback/summary"},
            {"label": "Release manifest", "endpoint": "/api/version"},
            {"label": "AI routing", "endpoint": "/api/ai/routing"},
            {"label": "AI model benchmarks", "endpoint": "/api/ai/model-benchmarks"},
            {"label": "AI evaluations", "endpoint": "/api/ai/evaluations/runs"},
            {"label": "Operations evidence", "endpoint": "/api/operations/evidence"},
            {"label": "Owner decision register", "endpoint": "/api/production/approval-package"},
        ],
    }


def display_action_packets(actions: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Group repeated customer-safe actions for operator display only."""

    priority_rank = {"P0": 0, "P1": 1, "P2": 2}
    groups: dict[tuple[Any, ...], dict[str, Any]] = {}
    for action in actions:
        boundary = action.get("approval_boundary") or action.get("safe_next_step", "")
        category = str(action.get("blocking_category", "review_required"))
        key = (
            category,
            bool(action.get("customer_decision_required")),
            bool(action.get("can_close_without_customer_secret")),
            str(action.get("owner_agent_id", "unassigned")),
            str(action.get("evidence_endpoint", "")),
            str(boundary),
        )
        priority = str(action.get("priority", "P2"))
        label = str(action.get("label") or action.get("action") or "Review action")
        required_input = str(
            action.get("required_input")
            or action.get("required_evidence")
            or "Customer-safe evidence required"
        )
        packet = groups.setdefault(
            key,
            {
                "display_id": f"action-packet-{len(groups) + 1}",
                "priority": priority,
                "blocking_category": category,
                "customer_decision_required": bool(
                    action.get("customer_decision_required")
                ),
                "can_close_without_customer_secret": bool(
                    action.get("can_close_without_customer_secret")
                ),
                "customer_secret_required_count": 0,
                "customer_decision_required_count": 0,
                "engineering_closeable_action_count": 0,
                "owner_agent_id": str(action.get("owner_agent_id", "unassigned")),
                "evidence_endpoint": str(action.get("evidence_endpoint", "")),
                "approval_boundary": str(boundary),
                "safe_next_step": str(boundary),
                "acceptance_impact": str(
                    action.get("acceptance_impact", "requires_owner_review")
                ),
                "required_input": required_input,
                "required_evidence": required_input,
                "action": label,
                "label": label,
                "occurrence_count": 0,
                "source_action_ids": [],
                "source_labels": [],
                "source_types": [],
                "states": [],
                "customer_safe": True,
            },
        )
        if priority_rank.get(priority, 9) < priority_rank.get(packet["priority"], 9):
            packet["priority"] = priority
        action_id = str(
            action.get("action_id", "action-" + str(packet["occurrence_count"] + 1))
        )
        if action_id not in packet["source_action_ids"]:
            packet["source_action_ids"].append(action_id)
        source_label = str(action.get("label") or action.get("action") or action_id)
        if source_label not in packet["source_labels"]:
            packet["source_labels"].append(source_label)
        source_type = str(action.get("source_type", "handoff_action"))
        if source_type not in packet["source_types"]:
            packet["source_types"].append(source_type)
        state = str(
            action.get("state") or action.get("acceptance_gate", "review_required")
        )
        if state not in packet["states"]:
            packet["states"].append(state)
        packet["occurrence_count"] += 1
        if action.get("customer_decision_required"):
            packet["customer_decision_required_count"] += 1
        if not action.get("can_close_without_customer_secret"):
            packet["customer_secret_required_count"] += 1
        if (
            category in {"admin_evidence", "development_visible"}
            and action.get("can_close_without_customer_secret")
            and not action.get("customer_decision_required")
        ):
            packet["engineering_closeable_action_count"] += 1

    display_packets = list(groups.values())
    for packet in display_packets:
        if packet["occurrence_count"] <= 1:
            continue
        labels = [str(item) for item in packet.get("source_labels", []) if str(item)]
        category = str(packet.get("blocking_category", "review_required"))
        label_text = ", ".join(labels[:3])
        if len(labels) > 3:
            label_text += f", and {len(labels) - 3} more"
        if category == "customer_runtime_config":
            if {"Identity provider", "MQTT broker subscriber"}.issubset(set(labels)):
                label_text = "Identity provider and MQTT broker setup"
            else:
                label_text = "Customer runtime configuration"
        elif category == "customer_decision":
            label_text = "Production go-live decisions"
        elif category == "owner_signoff":
            label_text = "Customer feedback and Phase 2 signoff"
        elif not label_text:
            label_text = "Owner review actions"
        packet["action"] = label_text
        packet["label"] = label_text
    return display_packets


def production_action_plan(store: CoreStore, production: bool) -> dict[str, Any]:
    """Return actionable, customer-safe tasks for production owner signoff."""

    hardening = production_hardening_status(store, production)
    approval = production_approval_package(store, production)
    open_controls = [
        item for item in hardening["items"] if item.get("state") != "ready"
    ]
    open_decisions = [
        item
        for item in approval["decision_items"]
        if item.get("state") not in {"ready", "approved"}
    ]

    def priority_for(state: str) -> str:
        if state in {"customer_action_required", "owner_review_required"}:
            return "P0"
        if state in {"pending_owner_signoff", "waiting_for_feedback"}:
            return "P1"
        return "P2"

    def blocker_metadata(source_type: str, source_id: str, state: str) -> dict[str, Any]:
        if state == "development_visible":
            category = "development_visible"
            can_close_without_secret = True
        elif source_type == "production_control":
            if source_id in {"identity-provider", "mqtt-broker-subscriber"}:
                category = "customer_runtime_config"
                can_close_without_secret = False
            elif source_id in {"reverse-proxy-tls", "backup-retention"}:
                category = "customer_runtime_config"
                can_close_without_secret = True
            else:
                category = "admin_evidence"
                can_close_without_secret = True
        elif source_id in {"customer-feedback", "phase-2-closure"}:
            category = "owner_signoff"
            can_close_without_secret = True
        elif source_id == "ai-model-route-approval":
            category = "customer_decision"
            can_close_without_secret = False
        else:
            category = "customer_decision"
            can_close_without_secret = True
        return {
            "blocking_category": category,
            "can_close_without_customer_secret": can_close_without_secret,
            "approval_boundary": (
                "Customer-safe runtime evidence only; this action does not replace "
                "formal customer acceptance."
            ),
        }

    actions: list[dict[str, Any]] = []
    for item in open_controls:
        state = str(item.get("state", "review_required"))
        control_id = str(item["control_id"])
        actions.append(
            {
                "action_id": f"control-{control_id}",
                "source_type": "production_control",
                "source_id": control_id,
                "label": item["control"],
                "state": state,
                "priority": priority_for(state),
                "owner_agent_id": "admin_governance_agent",
                "evidence_endpoint": "/api/production/hardening",
                "admin_action": "requires_admin_console",
                "required_evidence": item["evidence"],
                "customer_decision_required": state in {
                    "customer_action_required",
                    "owner_review_required",
                },
                "customer_safe": True,
                **blocker_metadata("production_control", control_id, state),
            }
        )
    for item in open_decisions:
        state = str(item.get("state", "review_required"))
        decision_id = str(item["decision_id"])
        actions.append(
            {
                "action_id": f"decision-{decision_id}",
                "source_type": "owner_decision",
                "source_id": decision_id,
                "label": item["decision"],
                "state": state,
                "priority": priority_for(state),
                "owner_agent_id": "project_delivery_coordinator",
                "evidence_endpoint": "/api/production/approval-package",
                "admin_action": "requires_admin_console",
                "required_evidence": item["evidence"],
                "customer_decision_required": state not in {"ready", "approved"},
                "customer_safe": True,
                **blocker_metadata("owner_decision", decision_id, state),
            }
        )
    action_count = len(actions)
    category_counts: dict[str, int] = {}
    secret_free_close_count = 0
    engineering_closeable_action_count = 0
    for action in actions:
        category = str(action["blocking_category"])
        category_counts[category] = category_counts.get(category, 0) + 1
        if action["can_close_without_customer_secret"]:
            secret_free_close_count += 1
        if (
            category in {"admin_evidence", "development_visible"}
            and action["can_close_without_customer_secret"]
            and not action["customer_decision_required"]
        ):
            engineering_closeable_action_count += 1
    display_actions = display_action_packets(actions)
    return {
        "status": "ready" if action_count == 0 else "action_required",
        "version": __version__,
        "prepared_for": CUSTOMER_NAME,
        "prepared_by": CONTRACTOR_NAME,
        "summary": {
            "action_count": action_count,
            "open_control_count": len(open_controls),
            "open_decision_count": len(open_decisions),
            "readiness_score": hardening["readiness_score"],
            "approval_status": approval["status"],
            "next_gate": approval["next_gate"],
            "customer_decision_required": any(
                action["customer_decision_required"] for action in actions
            ),
            "blocking_categories": category_counts,
            "secret_free_close_count": secret_free_close_count,
            "engineering_closeable_action_count": engineering_closeable_action_count,
            "display_action_count": len(display_actions),
        },
        "next_action": (
            "Record the highest-priority production control evidence that can be closed without customer approval."
            if engineering_closeable_action_count
            else (
                "Collect customer runtime configuration, owner decisions, or formal signoff; do not close these by code."
                if action_count
                else "Proceed to Phase 3 final acceptance packaging."
            )
        ),
        "actions": actions,
        "display_actions": display_actions,
        "evidence_links": [
            {"label": "Production hardening", "endpoint": "/api/production/hardening"},
            {"label": "Secret-free preflight", "endpoint": "/api/production/preflight"},
            {"label": "Backup retention", "endpoint": "/api/production/backup-retention"},
            {"label": "Owner approval", "endpoint": "/api/production/approval-package"},
            {"label": "AI route decision", "endpoint": "/api/ai/model-benchmarks"},
        ],
        "privacy": {
            "credential_values_returned": False,
            "local_paths_returned": False,
            "contact_data_returned": False,
            "admin_write_endpoints_returned": False,
            "operator_runbook_returned": False,
            "customer_safe": True,
        },
    }


def owner_decision_question(packet: dict[str, Any]) -> str:
    """Return one customer-safe owner question for a grouped action packet."""

    category = str(packet.get("blocking_category", "review_required"))
    label = str(packet.get("label") or packet.get("action") or "Owner decision")
    if category == "customer_runtime_config":
        return (
            "Which runtime configuration or secure credential path should be "
            f"approved for {label}?"
        )
    if category == "customer_decision":
        return f"Which owner decision should be recorded for {label}?"
    if category == "owner_signoff":
        return f"Can the owner sign off {label} based on the listed evidence?"
    if category in {"admin_evidence", "development_visible"}:
        return f"Can engineering record the remaining runtime evidence for {label}?"
    return f"What is the approved next step for {label}?"


def owner_decision_answer_options(packet: dict[str, Any]) -> list[str]:
    """Return bounded answer options without accepting secrets or contact data."""

    category = str(packet.get("blocking_category", "review_required"))
    if category == "customer_runtime_config":
        if int(packet.get("customer_secret_required_count", 0) or 0) > 0:
            return [
                "Provide configuration through the secure admin channel",
                "Approve fallback-only delivery for this phase",
                "Defer until customer infrastructure is available",
            ]
        return [
            "Approve customer-provided runtime evidence",
            "Request a revised runtime plan",
            "Defer until acceptance review",
        ]
    if category == "customer_decision":
        return [
            "Approve the proposed delivery state",
            "Reject and request correction",
            "Keep open for customer review",
        ]
    if category == "owner_signoff":
        return [
            "Sign off the phase gate",
            "Request additional evidence",
            "Keep gate open",
        ]
    return [
        "Record engineering evidence",
        "Request owner review",
        "Keep open",
    ]


def production_owner_decision_brief(
    store: CoreStore, production: bool
) -> dict[str, Any]:
    """Return manager-readable questions needed to close Phase 2."""

    plan = production_action_plan(store, production)
    approval = production_approval_package(store, production)
    packets = list(plan.get("display_actions") or [])
    questions = []
    for index, packet in enumerate(packets, start=1):
        question = {
            "question_id": f"owner-question-{index}",
            "priority": packet.get("priority", "P2"),
            "blocking_category": packet.get("blocking_category", "review_required"),
            "question": owner_decision_question(packet),
            "required_evidence": packet.get(
                "required_evidence",
                packet.get("required_input", "Owner evidence required"),
            ),
            "answer_options": owner_decision_answer_options(packet),
            "acceptance_impact": packet.get(
                "acceptance_impact", "requires_owner_review"
            ),
            "owner_agent_id": packet.get(
                "owner_agent_id", "project_delivery_coordinator"
            ),
            "evidence_endpoint": packet.get(
                "evidence_endpoint", "/api/production/action-plan"
            ),
            "safe_to_record_without_secret": bool(
                packet.get("can_close_without_customer_secret")
            ),
            "customer_secret_required_count": int(
                packet.get("customer_secret_required_count", 0) or 0
            ),
            "customer_decision_required_count": int(
                packet.get("customer_decision_required_count", 0) or 0
            ),
            "source_action_ids": list(packet.get("source_action_ids") or []),
            "customer_safe": True,
        }
        questions.append(question)

    question_count = len(questions)
    return {
        "status": "ready" if question_count == 0 else "action_required",
        "version": __version__,
        "prepared_for": CUSTOMER_NAME,
        "prepared_by": CONTRACTOR_NAME,
        "summary": {
            "question_count": question_count,
            "p0_question_count": sum(
                1 for item in questions if item["priority"] == "P0"
            ),
            "customer_secret_required_count": sum(
                item["customer_secret_required_count"] for item in questions
            ),
            "customer_decision_required_count": sum(
                item["customer_decision_required_count"] for item in questions
            ),
            "phase2_closure_policy": "owner_decision_required",
            "phase2_owner_question_status": (
                "open" if question_count else "resolved"
            ),
            "contractual_milestone_progress": "not_calculated",
            "customer_acceptance_claimed": False,
            "phase12_union_ready": question_count == 0,
            "must_not_fake": True,
            "next_gate": approval["next_gate"],
        },
        "next_action": (
            "Answer the P0 owner questions or approve fallback-only delivery "
            "before Phase 2 closure."
            if question_count
            else "Proceed to Phase 3 final acceptance packaging."
        ),
        "questions": questions,
        "evidence_links": [
            {"label": "Production action plan", "endpoint": "/api/production/action-plan"},
            {"label": "Owner approval", "endpoint": "/api/production/approval-package"},
            {"label": "Final handoff console", "endpoint": "/api/delivery/handoff-console"},
        ],
        "privacy": {
            "credential_values_returned": False,
            "local_paths_returned": False,
            "contact_data_returned": False,
            "admin_write_endpoints_returned": False,
            "operator_runbook_returned": False,
            "customer_safe": True,
        },
    }


def production_admin_action_plan(store: CoreStore, production: bool) -> dict[str, Any]:
    """Return admin-gated write guidance for production action closure."""

    public_plan = production_action_plan(store, production)
    admin_actions: list[dict[str, Any]] = []
    for action in public_plan["actions"]:
        item = dict(action)
        source_id = str(item["source_id"])
        if item["source_type"] == "production_control":
            item.update(
                {
                    "method": "PATCH",
                    "admin_endpoint": f"/api/admin/production/readiness-controls/{source_id}",
                    "required_scope": "access:manage",
                    "request_schema": {
                        "state": "ready | review_required | customer_action_required | development_visible",
                        "evidence": "4-260 chars; no contact data, secrets, local paths, or policy text",
                        "owner": "2-80 chars; role label only, no contact data",
                    },
                }
            )
        else:
            item.update(
                {
                    "method": "PATCH",
                    "admin_endpoint": f"/api/admin/production/decisions/{source_id}",
                    "required_scope": "admin:delivery:approve",
                    "request_schema": {
                        "state": "approved | rejected | ready | pending_owner_signoff | waiting_for_feedback | customer_action_required",
                        "decided_by": "2-80 chars; role label only, no contact data",
                        "decision_note": "4-260 chars; no contact data, secrets, local paths, or policy text",
                    },
                }
            )
        item["write_boundary"] = (
            "Admin guidance only. Runtime evidence and owner decisions remain "
            "separate from formal customer acceptance; no credentials or private "
            "execution logs are accepted."
        )
        admin_actions.append(item)
    return {
        **public_plan,
        "actions": admin_actions,
        "summary": {
            **public_plan["summary"],
            "admin_action_count": len(admin_actions),
            "required_scope": "access:manage",
        },
        "public_action_plan_endpoint": "/api/production/action-plan",
        "admin_console_endpoint": "/api/admin/production/action-plan",
        "privacy": {
            **public_plan["privacy"],
            "admin_write_endpoints_returned": True,
            "public_exposure": False,
            "credential_values_returned": False,
            "contact_data_returned": False,
            "local_paths_returned": False,
        },
    }


