PUBLIC_REDACTION_LABEL = "redacted_public_view"
SENSITIVE_AGENT_FIELDS = (
    "instruction_template",
    "operating_brief",
    "handoff_policy",
    "quality_gate_policy",
)


def prompt_value_hash(value: str) -> str:
    """Return a short stable hash for prompt-contract diff evidence."""

    return hashlib.sha256(value.encode("utf-8")).hexdigest()[:16]


def agent_prompt_contract_snapshot(agent: dict[str, Any]) -> dict[str, str]:
    """Return the versioned prompt-contract fields for one agent."""

    return {
        field: str(agent.get(field, "") or "")
        for field in AGENT_PROMPT_VERSION_FIELDS
    }


def agent_prompt_trace_reference(agent: dict[str, Any]) -> dict[str, Any]:
    """Return redacted prompt and Agent Card references for A2A traces."""

    snapshot = agent_prompt_contract_snapshot(agent)
    prompt_material = json.dumps(snapshot, sort_keys=True, separators=(",", ":"))
    return {
        "agent_card_id": f"agent-card.{agent['agent_id']}.v1",
        "prompt_ref": f"agent.{agent['agent_id']}.contract",
        "prompt_version": int(agent.get("prompt_contract_version") or 1),
        "prompt_content_hash": prompt_value_hash(prompt_material),
        "prompt_contract_endpoint": (
            f"/api/admin/agents/{agent['agent_id']}/prompt-contract/history"
        ),
    }


def agent_prompt_contract_diff(
    before: dict[str, str],
    after: dict[str, str],
    *,
    include_sensitive: bool,
) -> list[dict[str, Any]]:
    """Return field-level prompt-contract diff evidence."""

    items = []
    for field in AGENT_PROMPT_VERSION_FIELDS:
        before_value = str(before.get(field, "") or "")
        after_value = str(after.get(field, "") or "")
        if before_value == after_value:
            continue
        item: dict[str, Any] = {
            "field": field,
            "before_hash": prompt_value_hash(before_value),
            "after_hash": prompt_value_hash(after_value),
            "before_chars": len(before_value),
            "after_chars": len(after_value),
        }
        if include_sensitive:
            item["before"] = before_value
            item["after"] = after_value
        else:
            item["before"] = PUBLIC_REDACTION_LABEL
            item["after"] = PUBLIC_REDACTION_LABEL
        items.append(item)
    return items


def prompt_artifact_snapshot(artifact: dict[str, Any]) -> dict[str, str]:
    """Return versioned fields for one instruction artifact."""

    return {
        field: str(artifact.get(field, "") or "")
        for field in PROMPT_ARTIFACT_VERSION_FIELDS
    }


def prompt_artifact_diff(
    before: dict[str, str],
    after: dict[str, str],
    *,
    include_sensitive: bool,
) -> list[dict[str, Any]]:
    """Return field-level instruction artifact diff evidence."""

    items = []
    for field in PROMPT_ARTIFACT_VERSION_FIELDS:
        before_value = str(before.get(field, "") or "")
        after_value = str(after.get(field, "") or "")
        if before_value == after_value:
            continue
        item: dict[str, Any] = {
            "field": field,
            "before_hash": prompt_value_hash(before_value),
            "after_hash": prompt_value_hash(after_value),
            "before_chars": len(before_value),
            "after_chars": len(after_value),
        }
        if include_sensitive:
            item["before"] = before_value
            item["after"] = after_value
        else:
            item["before"] = PUBLIC_REDACTION_LABEL
            item["after"] = PUBLIC_REDACTION_LABEL
        items.append(item)
    return items


def public_subject_ref(value: str | None) -> str:
    """Return a stable public reference without exposing an identity."""

    if not value:
        return "subject-redacted"
    digest = hashlib.sha256(value.encode("utf-8")).hexdigest()[:12]
    return f"subject-{digest}"


def redact_audit_event(row: dict[str, Any]) -> dict[str, Any]:
    """Return audit metadata without actor or raw detail text."""

    event_type = str(row.get("event_type", ""))
    subject = str(row.get("subject_id", ""))
    return {
        "audit_event_id": row.get("audit_event_id"),
        "event_type": event_type,
        "subject_id": public_subject_ref(subject)
        if event_type.startswith("access.user.")
        else subject,
        "actor": "redacted",
        "detail_redacted": True,
        "created_at": row.get("created_at"),
    }


def redact_audit_events(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Return public audit metadata for customer-safe views."""

    return [redact_audit_event(row) for row in rows]


def redact_access_role_policy(row: dict[str, Any]) -> dict[str, Any]:
    """Return a public role policy without admin actor metadata."""

    item = row.copy()
    item.pop("updated_by", None)
    item["detail_level"] = "customer_safe_summary"
    return item


def redact_access_user_assignment(row: dict[str, Any]) -> dict[str, Any]:
    """Return user assignment state without identity or notes."""

    return {
        "assignment_ref": public_subject_ref(str(row.get("subject_id", ""))),
        "role": row.get("role"),
        "status": row.get("status"),
        "scopes_count": len(row.get("scopes") or []),
        "updated_at": row.get("updated_at"),
        "detail_level": "customer_safe_summary",
    }


def redact_dashboard_agent(agent: dict[str, Any]) -> dict[str, Any]:
    """Return an agent registry row without managed playbook text."""

    item = agent.copy()
    for field in SENSITIVE_AGENT_FIELDS:
        if field in item:
            item[field] = PUBLIC_REDACTION_LABEL
    item.pop("updated_by", None)
    item["playbook_redacted"] = True
    item["detail_level"] = "customer_safe_summary"
    return item


def redact_agent_run(row: dict[str, Any]) -> dict[str, Any]:
    """Return agent task evidence without actor identity or raw answers."""

    item = row.copy()
    item.pop("answer", None)
    item.pop("actor", None)
    item["answer_redacted"] = True
    item["detail_level"] = "customer_safe_summary"
    return item


def redact_evidence_finding(row: dict[str, Any]) -> dict[str, Any]:
    """Return finding evidence without actor/update metadata."""

    item = row.copy()
    item.pop("updated_by", None)
    if item.get("source") == "release_mission":
        evidence = str(item.get("evidence", ""))
        evidence_version = release_mission_evidence_version(evidence)
        evidence_current = release_mission_evidence_is_current(evidence)
        item["evidence_version"] = evidence_version
        item["evidence_current"] = evidence_current
        item["evidence"] = (
            f"Current release mission evidence for version {evidence_version}."
            if evidence_current
            else "Release mission evidence requires a current-version rerun."
        )
        item["lesson"] = (
            "Run release mission after each release version change; do not expose "
            "operator labels in customer findings."
        )
    item["detail_level"] = "customer_safe_summary"
    return item


def redact_provider_policy(policy: dict[str, Any]) -> dict[str, Any]:
    """Return AI provider policy without operator metadata."""

    item = policy.copy()
    item.pop("updated_by", None)
    item["credential_values"] = "not_returned"
    item["detail_level"] = "customer_safe_summary"
    return item


def redact_model_credential(item: dict[str, Any]) -> dict[str, Any]:
    """Return public model-service readiness without fingerprints or env refs."""

    return {
        "provider": item.get("provider"),
        "auth_mode": item.get("auth_mode"),
        "endpoint_configured": bool(item.get("endpoint_configured")),
        "username_configured": bool(item.get("username_configured")),
        "password_configured": bool(item.get("password_configured")),
        "api_key_configured": bool(item.get("api_key_configured")),
        "credential_configured": bool(item.get("credential_configured")),
        "secret_storage": "configured_or_external" if item.get("credential_configured") else "not_configured",
        "detail_level": "customer_safe_summary",
    }


def redact_ai_resource_governance(payload: dict[str, Any]) -> dict[str, Any]:
    """Return public model governance without credential fingerprints or env names."""

    item = payload.copy()
    item["credentials"] = [redact_model_credential(row) for row in payload.get("credentials", [])]
    token_usage = dict(payload.get("token_usage", {}))
    token_usage.pop("latest_events", None)
    token_usage["privacy"] = {
        **dict(token_usage.get("privacy", {})),
        "latest_events_returned": False,
        "usage_ids_returned": False,
        "model_names_returned": False,
        "usage_sources_returned": False,
    }
    item["token_usage"] = token_usage
    runtime = dict(payload.get("runtime_configuration", {}))
    runtime.pop("local_endpoints", None)
    runtime.pop("local_endpoint_summary", None)
    for key in (
        "local_runtime_gate_env",
        "cloud_runtime_gate_env",
        "local_model_env",
        "cloud_provider_env",
        "credential_env_refs_supported",
    ):
        runtime.pop(key, None)
    runtime["detail_level"] = "customer_safe_summary"
    item["runtime_configuration"] = runtime
    memory_policy = dict(payload.get("memory_policy", {}))
    memory_policy.pop("updated_by", None)
    memory_policy["detail_level"] = "customer_safe_summary"
    item["memory_policy"] = memory_policy
    item["privacy"] = {
        **dict(payload.get("privacy", {})),
        "credential_fingerprints_returned": False,
        "credential_env_refs_returned": False,
        "operator_metadata_returned": False,
    }
    return item


def redact_assistant_interaction_ledger(payload: dict[str, Any]) -> dict[str, Any]:
    """Return public assistant evidence without actor/session/message identifiers."""

    item = payload.copy()
    public_items = []
    for row in payload.get("items", []):
        public_items.append(
            {
                "interaction_ref": public_subject_ref(str(row.get("interaction_id", ""))),
                "prompt_category": row.get("prompt_category"),
                "response_status": row.get("response_status"),
                "outcome": row.get("outcome"),
                "requires_human_approval": bool(row.get("requires_human_approval")),
                "grounding_count": row.get("grounding_count", 0),
                "knowledge_count": row.get("knowledge_count", 0),
                "latency_ms": row.get("latency_ms", 0),
                "detail_level": "customer_safe_summary",
            }
        )
    public_proposals = []
    for row in payload.get("tool_proposals", []):
        public_proposals.append(
            {
                "proposal_ref": public_subject_ref(str(row.get("proposal_id", ""))),
                "owner_agent_id": row.get("owner_agent_id"),
                "execution_state": row.get("execution_state"),
                "requires_human_approval": bool(row.get("requires_human_approval")),
                "target_required_scope": row.get("target_required_scope"),
                "tool_executed": bool(row.get("tool_executed")),
                "detail_level": "customer_safe_summary",
            }
        )
    public_feedback = []
    for row in payload.get("feedback", []):
        public_feedback.append(
            {
                "feedback_ref": public_subject_ref(str(row.get("feedback_id", ""))),
                "category": row.get("category"),
                "rating": row.get("rating"),
                "outcome": row.get("outcome"),
                "follow_up_required": bool(row.get("follow_up_required")),
                "detail_level": "customer_safe_summary",
            }
        )
    item["items"] = public_items
    item["tool_proposals"] = public_proposals
    item["feedback"] = public_feedback
    item["privacy"] = {
        **dict(payload.get("privacy", {})),
        "operator_identity": "redacted_public_view",
        "session_ids_returned": "false",
        "message_ids_returned": "false",
        "prompt_hash_returned": "false",
        "route_internals_returned": "false",
    }
    item["detail_level"] = "customer_safe_summary"
    return item


def redact_release_gap_closure_console(payload: dict[str, Any]) -> dict[str, Any]:
    """Return public release-gap status without executable runbook details."""

    item = payload.copy()
    redacted_plan = []
    for row in payload.get("gate_closure_plan", []):
        safe = row.copy()
        safe.pop("request_body", None)
        safe.pop("safe_command", None)
        safe["run_endpoint"] = "redacted_operator_view"
        safe["method"] = "redacted_operator_view"
        safe["runnable_now"] = False
        safe["detail_level"] = "customer_safe_summary"
        redacted_plan.append(safe)
    item["gate_closure_plan"] = redacted_plan
    redacted_actions = []
    for row in payload.get("action_queue", []):
        safe = row.copy()
        safe.pop("request_body", None)
        safe.pop("safe_command", None)
        if safe.get("method") == "POST" or safe.get("source") == "release_gap":
            safe["run_endpoint"] = "redacted_operator_view"
            safe["method"] = "redacted_operator_view"
            safe["runnable_now"] = False
            safe["safe_next_step"] = (
                "Use the authenticated dashboard run control; credential values are not returned."
            )
        safe["detail_level"] = "customer_safe_summary"
        redacted_actions.append(safe)
    item["action_queue"] = redacted_actions
    redacted_handoff_plan = []
    for row in payload.get("handoff_acceptance_plan", []):
        safe = row.copy()
        safe.pop("request_body", None)
        safe.pop("safe_command", None)
        safe["detail_level"] = "customer_safe_summary"
        redacted_handoff_plan.append(safe)
    item["handoff_acceptance_plan"] = redacted_handoff_plan
    auth_gate = dict(payload.get("auth_gate", {}))
    auth_gate["required_runtime_setup"] = []
    auth_gate["detail_level"] = "customer_safe_summary"
    item["auth_gate"] = auth_gate
    sequence = []
    for row in payload.get("execution_sequence", []):
        safe = row.copy()
        safe.pop("safe_command", None)
        safe["method"] = "redacted_operator_view" if safe.get("method") == "POST" else safe.get("method")
        safe["detail_level"] = "customer_safe_summary"
        sequence.append(safe)
    item["execution_sequence"] = sequence
    item["privacy"] = {
        **dict(payload.get("privacy", {})),
        "operator_runbook_returned": "false",
        "request_body_returned": "false",
    }
    item["detail_level"] = "customer_safe_summary"
    return item


def full_admin_view(operator: OperatorContext | None, required_scope: str) -> bool:
    """Return whether a read request may include admin control-plane detail."""

    return bool(
        operator
        and operator.role == "admin"
        and required_scope in set(operator.scopes)
    )


def agent_panel_read_scope(agent_id: str) -> str:
    """Return the granular panel read scope owned by one agent."""

    panel_scopes = {
        "operations_coordinator": "panel:operate:read",
        "device_fleet_agent": "panel:assets:read",
        "alert_recovery_agent": "panel:alerts:read",
        "ai_diagnosis_agent": "panel:intelligence:read",
        "reporting_compliance_agent": "panel:delivery:read",
        "ui_ux_experience_auditor": "panel:operate:read",
        "admin_governance_agent": "panel:admin:read",
    }
    return panel_scopes.get(agent_id, "panel:operate:read")


def agent_data_scopes(agent_id: str) -> list[str]:
    """Return data scopes an agent may read or propose actions for."""

    data_scopes = {
        "operations_coordinator": ["data:devices:read", "data:alerts:read", "data:reports:read"],
        "device_fleet_agent": ["data:devices:read", "data:devices:write", "data:telemetry:read"],
        "alert_recovery_agent": ["data:alerts:read", "data:alerts:write", "data:recovery:write"],
        "ai_diagnosis_agent": ["data:telemetry:read", "data:alerts:read", "data:reports:read"],
        "reporting_compliance_agent": ["data:reports:read"],
        "ui_ux_experience_auditor": ["data:reports:read"],
        "admin_governance_agent": ["data:reports:read"],
    }
    return data_scopes.get(agent_id, ["data:reports:read"])


def access_scope_catalog(agents: list[dict[str, Any]] | None = None) -> dict[str, Any]:
    """Return customer-safe granular RBAC scope catalog metadata."""

    agent_action_scopes = [
        {
            "scope": "agent:run",
            "surface": "Agent orchestra",
            "description": "Run supervised agent tasks through approved dashboard routes.",
        }
    ]
    if agents:
        agent_action_scopes.extend(
            {
                "scope": f"agent:{agent['agent_id']}:run",
                "surface": agent["display_name"],
                "description": f"Run supervised tasks owned by {agent['display_name']}.",
            }
            for agent in agents
        )
    scope_count = sum(
        len(group)
        for group in (
            PANEL_SCOPE_CATALOG,
            agent_action_scopes,
            DATA_SCOPE_CATALOG,
            ADMIN_SCOPE_CATALOG,
        )
    )
    return {
        "schema_version": "rbac.scope_catalog.v1",
        "default_decision": "deny",
        "unknown_bearer_role_decision": "deny",
        "role_policy": "built_in_operator_admin_bearer_only",
        "scope_count": scope_count,
        "panel_scopes": PANEL_SCOPE_CATALOG,
        "agent_action_scopes": agent_action_scopes,
        "data_scopes": DATA_SCOPE_CATALOG,
        "admin_scopes": ADMIN_SCOPE_CATALOG,
        "legacy_scopes_supported": [
            "device:write",
            "telemetry:write",
            "recovery:approve",
            "agent:read",
            "agent:manage",
            "access:manage",
            "report:read",
        ],
    }


def access_policy(
    store: CoreStore | None = None, *, include_assignments: bool = False
) -> dict[str, Any]:
    """Return role groups and identity-provider readiness."""

    roles = store.list_access_role_policies() if store else ACCESS_ROLES.copy()
    assignments = store.list_access_user_assignments() if store else []
    agents = store.list_dashboard_agents() if store else DEFAULT_DASHBOARD_AGENTS
    return {
        "roles": [redact_access_role_policy(role) for role in roles],
        "user_assignments": [
            redact_access_user_assignment(item) for item in assignments
        ]
        if include_assignments
        else [],
        "scope_catalog": access_scope_catalog(agents),
        "identity_provider": identity_provider_config(),
        "human_approval_required": True,
        "status": "ok",
    }


def choose_agent_for_goal(
    agents: list[dict[str, Any]], goal: str, preferred_agent_id: str | None
) -> dict[str, Any]:
    """Choose the primary agent for a bounded orchestration task."""

    enabled = {agent["agent_id"]: agent for agent in agents if agent["enabled"]}
    if preferred_agent_id:
        preferred = enabled.get(preferred_agent_id)
        if not preferred:
            raise HTTPException(status_code=400, detail="Preferred agent is unavailable")
        return preferred
    lowered = goal.lower()
    for agent_id, keywords in AGENT_GOAL_KEYWORDS.items():
        if agent_id in enabled and any(keyword in lowered for keyword in keywords):
            return enabled[agent_id]
    return enabled.get("operations_coordinator") or next(iter(enabled.values()))


def build_agent_route(
    agents: list[dict[str, Any]], primary_agent: dict[str, Any]
) -> list[str]:
    """Build a compact A2A route for one agent task."""

    available = {agent["agent_id"] for agent in agents if agent["enabled"]}
    route = ["operations_coordinator", primary_agent["agent_id"]]
    route.extend(primary_agent["connected_agents"][:2])
    return list(dict.fromkeys(agent for agent in route if agent in available))


def build_a2a_trace(
    agents: list[dict[str, Any]], route: list[str]
) -> list[dict[str, Any]]:
    """Build customer-safe A2A message envelopes for an agent route."""

    by_id = {agent["agent_id"]: agent for agent in agents}
    trace_seed = "|".join(route) or "empty-route"
    trace_id = f"a2a-{hashlib.sha256(trace_seed.encode('utf-8')).hexdigest()[:12]}"
    timestamp = utc_now()
    trace = []
    for index, agent_id in enumerate(route):
        agent = by_id[agent_id]
        next_agent = route[index + 1] if index + 1 < len(route) else "operator"
        step = index + 1
        prompt_reference = agent_prompt_trace_reference(agent)
        metadata = {
            "step": step,
            "from": agent_id,
            "to": next_agent,
            "protocol": agent["a2a_card"]["protocol"],
            "input": agent["a2a_card"]["input"],
            "output": agent["a2a_card"]["output"],
            "analysis_profile_id": agent["analysis_profile_id"],
            "model_route": agent["model_route"],
            "trace_policy": agent["trace_policy"],
            "eval_profile": agent["eval_profile"],
            "approval_required": agent["a2a_card"]["approval_required"],
            **prompt_reference,
        }
        message_id = f"{trace_id}-{step:02d}"
        parts = [
            {
                "kind": "text",
                "text": (
                    f"{agent['display_name']} hands off "
                    f"{agent['a2a_card']['output']} to {next_agent}."
                ),
            }
        ]
        trace.append(
            {
                "id": message_id,
                "from": agent_id,
                "to": next_agent,
                "type": A2A_MESSAGE_TYPE,
                "schema_version": A2A_SCHEMA_VERSION,
                "payload": {
                    "messageId": message_id,
                    "role": "agent",
                    "parts": parts,
                    "metadata": metadata,
                },
                "trace_id": trace_id,
                "ts": timestamp,
                "kind": "message",
                "messageId": message_id,
                "role": "agent",
                "parts": parts,
                "metadata": metadata,
                "step": step,
                "protocol": metadata["protocol"],
                "input": metadata["input"],
                "output": metadata["output"],
                "analysis_profile_id": metadata["analysis_profile_id"],
                "model_route": metadata["model_route"],
                "trace_policy": metadata["trace_policy"],
                "eval_profile": metadata["eval_profile"],
                "approval_required": metadata["approval_required"],
                "agent_card_id": metadata["agent_card_id"],
                "prompt_ref": metadata["prompt_ref"],
                "prompt_version": metadata["prompt_version"],
                "prompt_content_hash": metadata["prompt_content_hash"],
                "prompt_contract_endpoint": metadata["prompt_contract_endpoint"],
            }
        )
    return trace


def a2a_trace_has_canonical_envelopes(trace: list[dict[str, Any]]) -> bool:
    """Return whether every A2A trace item exposes the canonical envelope."""

    required = {
        "id",
        "from",
        "to",
        "type",
        "schema_version",
        "payload",
        "trace_id",
        "ts",
        "agent_card_id",
        "prompt_ref",
        "prompt_version",
        "prompt_content_hash",
    }
    return bool(trace) and all(required.issubset(item) for item in trace)


def normalize_a2a_trace(
    agents: list[dict[str, Any]], route: list[str], trace: list[dict[str, Any]]
) -> list[dict[str, Any]]:
    """Upgrade stored legacy traces to the current customer-safe envelope shape."""

    return trace if a2a_trace_has_canonical_envelopes(trace) else build_a2a_trace(agents, route)

def assistant_evidence_links(grounding: list[dict[str, Any]]) -> list[dict[str, str]]:
    """Map grounding records to customer-safe API evidence links."""

    endpoint_by_type = {
        "alert": "/api/alerts",
        "telemetry": "/api/telemetry",
        "recovery_proposal": "/api/recovery/proposals",
    }
    links = [
        {
            "type": item["type"],
            "id": str(item["id"]),
            "endpoint": endpoint_by_type.get(item["type"], "/api/operations/summary"),
        }
        for item in grounding
    ]
    links.extend(
        [
            {
                "type": "operations",
                "id": "summary",
                "endpoint": "/api/operations/summary",
            },
            {
                "type": "reports",
                "id": "dashboard",
                "endpoint": "/api/reports/dashboard",
            },
            {
                "type": "agents",
                "id": "registry",
                "endpoint": "/api/admin/agents",
            },
        ]
    )
    return links


def assistant_plan(
    *,
    grounding: list[dict[str, Any]],
    route: list[str],
    provider_status: str,
) -> list[dict[str, Any]]:
    """Return a compact operator plan tied to runtime evidence."""

    has_alert = any(item["type"] == "alert" for item in grounding)
    has_telemetry = any(item["type"] == "telemetry" for item in grounding)
    has_recovery = any(item["type"] == "recovery_proposal" for item in grounding)
    return [
        {
            "step": 1,
            "agent": route[0] if route else "operations_coordinator",
            "action": "Read current runtime summary and classify operational risk.",
            "evidence_required": ["/api/operations/summary"],
            "status": "ready" if grounding else "waiting_for_runtime_records",
        },
        {
            "step": 2,
            "agent": route[1] if len(route) > 1 else "ai_diagnosis_agent",
            "action": "Ground the answer in alert and telemetry records before model text.",
            "evidence_required": ["/api/alerts", "/api/telemetry"],
            "status": "ready" if has_alert and has_telemetry else "waiting_for_evidence",
        },
        {
            "step": 3,
            "agent": "alert_recovery_agent",
            "action": "Prepare recovery guidance and keep execution behind human approval.",
            "evidence_required": ["/api/recovery/proposals", "/api/audit/events"],
            "status": "ready" if has_recovery else "waiting_for_recovery_proposal",
        },
        {
            "step": 4,
            "agent": "reporting_compliance_agent",
            "action": "Expose customer-safe evidence links and report status for review.",
            "evidence_required": ["/api/reports/dashboard"],
            "status": provider_status,
        },
    ]


def assistant_activity_log(
    *,
    grounding: list[dict[str, Any]],
    agent_route: list[str],
    provider_runtime: dict[str, Any] | None,
    assistant_plan: list[dict[str, Any]],
    status: str,
) -> list[dict[str, Any]]:
    """Return visible per-agent activity for this assistant turn."""

    runtime = provider_runtime or {}
    model = str(runtime.get("model") or "not_configured")
    provider_state = str(runtime.get("status") or "skipped")
    items: list[dict[str, Any]] = []
    for index, step in enumerate(assistant_plan[:6], start=1):
        agent = str(step.get("agent") or (agent_route[index - 1] if index <= len(agent_route) else "operations_coordinator"))
        if index == 1 and grounding:
            result = "; ".join(
                f"{item.get('type')} {item.get('id')} {item.get('summary')}"
                for item in grounding[:3]
            )
        elif index == 2 and status == "provider_runtime" and provider_state == "completed":
            result = f"Live model {model} answered from runtime evidence."
        elif index == 2:
            result = f"Model route stayed on grounded review ({provider_state})."
        elif index == 3:
            recovery = next((item for item in grounding if item.get("type") == "recovery_proposal"), None)
            result = (
                f"Recovery {recovery.get('id')} is {recovery.get('summary')}; execution stays behind approval."
                if recovery
                else "No recovery proposal is waiting."
            )
        else:
            result = str(step.get("action") or "Recorded evidence for operator review.")
        items.append(
            {
                "step": index,
                "agent": agent,
                "result": result[:220],
                "status": "done" if step.get("status") in {"ready", "provider_runtime", "completed"} or status == "provider_runtime" else str(step.get("status") or "review"),
            }
        )
    return items


def format_operator_assistant_answer(response: ChatResponse) -> str:
    """Normalize assistant text into the operator five-label format."""

    body = str(response.answer or "").strip()
    if body.startswith("Finding:"):
        body = body[len("Finding:") :].strip()
    for label in (
        "Evidence:",
        "Agents:",
        "Next review:",
        "Approval:",
        "Evidence used:",
        "Owner route:",
    ):
        marker = f"\n{label}"
        if marker in body:
            body = body.split(marker, 1)[0].strip()
        elif body.startswith(label):
            body = ""
    finding = next(
        (line.strip() for line in body.splitlines() if line.strip()),
        "",
    )
    evidence: list[str] = []
    for item in response.grounding:
        marker = f"[{item.get('type')}:{item.get('id')}]"
        if marker not in evidence:
            evidence.append(marker)
    for item in response.knowledge_grounding[:2]:
        marker = f"[rag_knowledge:{item.get('id')}]"
        if marker not in evidence:
            evidence.append(marker)
    route = " -> ".join(response.agent_route[:4]) if response.agent_route else "operations_coordinator"
    next_review = (
        response.next_actions[0]
        if response.next_actions
        else "Review the latest alert and telemetry before any recovery decision."
    )
    approval = (
        "required before recovery execution"
        if response.requires_human_approval
        else "not required for this read-only review"
    )
    finding = finding or "No diagnosis is available from current runtime evidence."
    return (
        f"Finding: {finding}\n"
        f"Evidence: {', '.join(evidence) if evidence else 'none'}\n"
        f"Agents: {route}\n"
        f"Next review: {next_review}\n"
        f"Approval: {approval}"
    )


def assistant_next_actions(
    grounding: list[dict[str, Any]], provider_status: str
) -> list[str]:
    """Return bounded next actions for operator review."""

    if not grounding:
        return [
            "Connect or bootstrap a pilot device before asking for operational diagnosis.",
            "Review /api/operations/preview for a read-only workflow.",
            "Run bounded simulation only in development when evidence is needed.",
        ]
    actions = [
        "Review latest alert and telemetry together before acting.",
        "Inspect device power, network, cooling, and sensor placement.",
        "Approve recovery only after physical checks and operator signoff.",
    ]
    if provider_status != "provider_runtime":
        actions.append("Run or configure approved AI provider evals before claiming model-level assistance.")
    return actions


def assistant_follow_up_contract(
    response: ChatResponse, message: str | None = None
) -> dict[str, Any]:
    """Return a input-redacted coworker follow-up contract for one answer."""

    category = assistant_prompt_category(message or "")
    owner_agent_id = (
        "ai_diagnosis_agent"
        if "ai_diagnosis_agent" in response.agent_route
        else response.agent_route[0]
        if response.agent_route
        else "operations_coordinator"
    )
    evidence_endpoints = list(
        dict.fromkeys(
            [
                *(item.get("endpoint", "") for item in response.evidence_links),
                "/api/operations/summary",
                "/api/reports/dashboard",
                "/api/assistant/quality-report",
            ]
        )
    )
    evidence_endpoints = [item for item in evidence_endpoints if item.startswith("/")]
    known_now = [
        f"category={category}",
        f"route={response.status}",
        f"runtime_records={len(response.grounding)}",
        f"knowledge_matches={len(response.knowledge_grounding)}",
        f"confidence={response.confidence}",
    ]
    if response.agent_route:
        known_now.append(f"owner_agent={owner_agent_id}")
    missing_before_action = []
    if not response.grounding:
        missing_before_action.append("live telemetry, alert, or recovery evidence")
    if not response.knowledge_grounding:
        missing_before_action.append("matching RAG knowledge evidence")
    if response.status != "provider_runtime":
        missing_before_action.append("approved provider-runtime activation evidence")
    if response.requires_human_approval:
        missing_before_action.append("human approval before recovery execution")
    if not missing_before_action:
        missing_before_action.append("no blocking evidence gap before operator review")
    next_best_action = (
        response.next_actions[0]
        if response.next_actions
        else "Open the operations summary and verify evidence before action."
    )
    safe_follow_up_question = (
        "Which linked evidence item should I inspect next before proposing an action?"
        if response.grounding
        else "Which asset or telemetry source should I connect before diagnosis?"
    )
    ready = bool(
        known_now
        and missing_before_action
        and next_best_action
        and safe_follow_up_question
    )
    return {
        "status": "ready" if ready else "review_required",
        "contract_id": "follow-up-"
        + assistant_prompt_hash(
            "|".join(
                [
                    category,
                    response.status,
                    response.confidence,
                    str(len(response.grounding)),
                ]
            )
        ),
        "owner_agent_id": owner_agent_id,
        "known_now": known_now,
        "missing_before_action": missing_before_action,
        "next_best_action": next_best_action,
        "safe_follow_up_question": safe_follow_up_question,
        "evidence_endpoints": evidence_endpoints,
        "privacy": {
            "raw_prompt_returned": False,
            "answer_text_returned": False,
            "provider_payload_returned": False,
        },
    }


ANSWER_ALIGNMENT_TERMS = {
    "operational_risk": ("alert", "telemetry", "risk", "temperature", "recovery"),
    "recovery_control": ("recovery", "approval", "operator", "human", "proposal"),
    "device_fleet": ("device", "asset", "mqtt", "firmware", "sensor"),
    "reporting_evidence": ("report", "evidence", "audit", "test", "delivery"),
    "ai_routing": ("route", "model", "rag", "provider", "agent"),
    "general_operations": ("operations", "evidence", "review", "status"),
}


def compose_grounded_coworker_answer(
    *,
    message: str,
    grounding: list[dict[str, Any]],
    knowledge_grounding: list[dict[str, Any]],
    agent_route: list[str],
    provider_status: str,
) -> str:
    """Compose a deterministic coworker answer from available evidence."""

    category = assistant_prompt_category(message)
    owner = agent_route[1] if len(agent_route) > 1 else agent_route[0] if agent_route else "operations_coordinator"
    route_label = " -> ".join(agent_route[:4]) if agent_route else owner
    runtime_by_type = {item["type"]: item for item in grounding}
    parts: list[str] = []

    if not grounding:
        parts.append(
            "No live runtime evidence is available, so I will not make a device-specific diagnosis."
        )
        parts.append(
            f"Use non-AI troubleshooting for {category}: register or verify the asset, connect telemetry, check recent alerts, inspect device power and network state, then verify sensor placement."
        )
    else:
        parts.append(
            f"Grounded operational answer for {category}: route {owner} is handling the review through {route_label}."
        )
        alert = runtime_by_type.get("alert")
        if alert:
            parts.append(f"The active risk signal is {alert['summary']} [{alert['type']}:{alert['id']}].")
        telemetry = runtime_by_type.get("telemetry")
        if telemetry:
            parts.append(
                f"The latest telemetry evidence is {telemetry['summary']} [{telemetry['type']}:{telemetry['id']}], so compare it with the alert before acting."
            )
        proposal = runtime_by_type.get("recovery_proposal")
        if proposal:
            parts.append(
                f"Recovery is in state {proposal['summary']} [{proposal['type']}:{proposal['id']}]; keep execution behind human approval and physical checks."
            )
        if provider_status == "provider_chat_gate_blocked":
            parts.append(
                "The provider route is intentionally blocked until credential, connectivity, identity, grounding, and eval gates pass."
            )
        elif provider_status != "provider_runtime":
            parts.append(
                "No external model call is being claimed; this answer uses deterministic runtime and RAG evidence only."
            )

    if knowledge_grounding:
        support = knowledge_grounding[0]
        parts.append(
            f"Supporting RAG evidence [{support['type']}:{support['id']}] says: {support['summary']}"
        )
    else:
        parts.append("No matching RAG knowledge item was selected for this question.")

    parts.append(
        "Next operational step: validate the evidence in the linked APIs, then approve any recovery action only after operator signoff."
    )
    return " ".join(parts)


def assistant_answer_alignment_gate(
    response: ChatResponse, message: str | None
) -> dict[str, Any]:
    """Check that the answer text visibly uses selected evidence."""

    category = assistant_prompt_category(message or "")
    terms = ANSWER_ALIGNMENT_TERMS.get(category, ANSWER_ALIGNMENT_TERMS["general_operations"])
    answer = response.answer.lower()
    citations = assistant_citation_items(response)
    citation_hits = 0
    for item in citations:
        source_id = str(item.get("source_id", "")).lower()
        source_type = str(item.get("source_type", "")).lower()
        bracket = f"[{source_type}:{source_id}]"
        if bracket in answer or (source_id and source_id in answer):
            citation_hits += 1
    category_ready = any(term in answer for term in terms)
    route_ready = any(agent.lower() in answer for agent in response.agent_route[:3])
    provider_grounded = response.status == "provider_runtime" and bool(response.grounding)
    ready = bool(citations) and citation_hits > 0 and category_ready and (route_ready or provider_grounded)
    return {
        "gate": "query_evidence_alignment",
        "status": "ready" if ready else "review_required",
        "evidence": (
            f"{citation_hits}/{len(citations)} visible citation reference(s), "
            f"category={category}, route_visible={route_ready}."
        ),
    }


def append_evidence_footer_to_provider_answer(
    answer: str,
    *,
    grounding: list[dict[str, Any]],
    knowledge_grounding: list[dict[str, Any]],
    agent_route: list[str],
) -> str:
    """Append customer-safe evidence labels to provider text when missing."""

    markers = []
    for item in grounding:
        marker = f"[{item['type']}:{item['id']}]"
        if marker.lower() not in answer.lower():
            markers.append(marker)
    for item in knowledge_grounding[:1]:
        marker = f"[{item['type']}:{item['id']}]"
        if marker.lower() not in answer.lower():
            markers.append(marker)
    if not markers:
        return answer
    route = " -> ".join(agent_route[:4]) if agent_route else "operations_coordinator"
    return f"{answer} Evidence used: {', '.join(markers)}. Owner route: {route}."


PROVIDER_ACCEPTANCE_STOP_TERMS = {
    "alert",
    "alerts",
    "answer",
    "current",
    "evidence",
    "grounded",
    "model",
    "operations",
    "provider",
    "reference",
    "references",
    "runtime",
    "selected",
    "status",
    "summary",
    "telemetry",
}

PROVIDER_RESPONSE_ABUSE_PATTERNS: tuple[tuple[str, re.Pattern[str]], ...] = (
    (
        "secret_like_material",
        re.compile(
            r"(?i)(sk-[A-Za-z0-9_-]{12,}|ghp_[A-Za-z0-9_]{12,}|"
            r"AIza[0-9A-Za-z_-]{12,}|xox[baprs]-[0-9A-Za-z-]{12,}|"
            r"client[_ -]?secret|api[_ -]?key\s*[:=]|authorization\s*:\s*bearer)"
        ),
    ),
    (
        "local_or_private_path",
        re.compile(
            r"(?i)([A-Z]:\\(?:Users|Windows|ProgramData)\\|"
            r"/(?:home|root|etc|var)/[^\s]+|file://|\\\\[A-Za-z0-9_.-]+\\)"
        ),
    ),
    (
        "prompt_injection_text",
        re.compile(
            r"(?i)(ignore\s+(?:all\s+)?(?:previous|prior|system|developer)\s+"
            r"instructions|reveal\s+(?:the\s+)?(?:system|developer)\s+prompt|"
            r"jailbreak|do\s+not\s+follow\s+the\s+policy)"
        ),
    ),
    (
        "tool_call_payload",
        re.compile(
            r"(?i)(\"(?:tool|tool_name|function|arguments|command|path)\"\s*:|"
            r"\btool_calls?\b|\bfunction_call\b|<tool_call>)"
        ),
    ),
)


def provider_acceptance_terms(
    grounding: list[dict[str, Any]], knowledge_grounding: list[dict[str, Any]]
) -> list[str]:
    """Return material evidence terms the raw provider answer may cite."""

    terms: set[str] = set()
    for item in [*grounding, *knowledge_grounding[:3]]:
        for value in (item.get("id"), item.get("summary")):
            for candidate in re.findall(r"[a-z0-9][a-z0-9_.:-]{2,}", str(value).lower()):
                candidate = candidate.strip("._:-")
                if candidate in PROVIDER_ACCEPTANCE_STOP_TERMS:
                    continue
                if any(ch.isdigit() for ch in candidate) or any(
                    marker in candidate for marker in ("-", "_", ":")
                ):
                    terms.add(candidate)
    return sorted(terms)


def provider_answer_has_unsafe_action_language(
    answer: str,
    grounding: list[dict[str, Any]] | None = None,
    knowledge_grounding: list[dict[str, Any]] | None = None,
) -> bool:
    """Return True only for first-person or cohort action claims."""

    del grounding, knowledge_grounding
    text = PROHIBITION_ACTION_RE.sub(" ", answer)
    return bool(UNSAFE_ACTION_CLAIM_RE.search(text))


def provider_answer_acceptance_gate(
    answer: str,
    grounding: list[dict[str, Any]],
    knowledge_grounding: list[dict[str, Any]],
) -> dict[str, Any]:
    """Reject provider text that is not visibly grounded before footer injection."""

    answer_text = answer.lower()
    terms = provider_acceptance_terms(grounding, knowledge_grounding)
    matched_terms = [term for term in terms if term and term in answer_text][:8]
    blocking_gates: list[str] = []
    if not matched_terms:
        blocking_gates.append("missing_evidence_reference")
    if provider_answer_has_unsafe_action_language(
        answer, grounding, knowledge_grounding
    ):
        blocking_gates.append("unsafe_action_language")
    for gate, pattern in PROVIDER_RESPONSE_ABUSE_PATTERNS:
        if pattern.search(answer):
            blocking_gates.append(gate)
    return {
        "status": "rejected" if blocking_gates else "ready",
        "policy": "raw_provider_answer_must_reference_runtime_or_rag_evidence",
        "matched_evidence_terms": matched_terms,
        "evidence_term_count": len(terms),
        "blocking_gates": blocking_gates,
        "raw_answer_returned": False,
    }


def assistant_safe_identifier(value: str | None, fallback: str, max_length: int = 80) -> str:
    """Return a customer-safe opaque identifier for session correlation."""

    candidate = (value or "").strip()
    candidate = re.sub(r"[^A-Za-z0-9_.:-]+", "-", candidate).strip("-_.:")
    if not candidate:
        candidate = fallback
    return candidate[:max_length]


def assistant_session_state(
    *,
    message: str,
    requested_session_id: str | None,
    client_message_id: str | None,
    parent_message_id: str | None,
    response: ChatResponse,
    interaction: dict[str, Any] | None,
    latency_ms: int,
) -> dict[str, Any]:
    """Build input-redacted assistant session state for UI and audit evidence."""

    prompt_hash = assistant_prompt_hash(message)
    interaction_id = interaction["interaction_id"] if interaction else None
    if interaction:
        session_id = interaction.get("session_id") or assistant_safe_identifier(
            requested_session_id, f"asst-session-{prompt_hash}"
        )
        message_id = interaction.get("message_id") or assistant_safe_identifier(
            client_message_id, f"asst-msg-{prompt_hash}-{interaction_id[-6:]}"
        )
        parent_id = interaction.get("parent_message_id")
    else:
        session_id = assistant_safe_identifier(
            requested_session_id, f"asst-session-{prompt_hash}"
        )
        message_id = assistant_safe_identifier(client_message_id, f"asst-msg-{prompt_hash}")
        parent_id = assistant_safe_identifier(parent_message_id, "", 80) if parent_message_id else None
    turn_state = (
        "awaiting_human_approval" if response.requires_human_approval else "answered"
    )
    return {
        "session_id": session_id,
        "message_id": message_id,
        "parent_message_id": parent_id,
        "interaction_id": interaction_id,
        "turn_index": "ledger_recorded" if interaction else "preview",
        "turn_state": turn_state,
        "can_regenerate": True,
        "can_stop": False,
        "cancellable": False,
        "context_policy": "runtime_rag_a2a_evidence_only",
        "storage_policy": "sha256_16_prompt_hash_only",
        "last_response_status": response.status,
        "latency_ms": max(0, latency_ms),
        "next_expected_input": (
            "operator_approval_or_follow_up"
            if response.requires_human_approval
            else "follow_up_question"
        ),
        "ledger_endpoint": "/api/assistant/interactions",
        "closed_loop_endpoint": "/api/evidence/findings",
        "proposal_state_endpoint": "/api/assistant/interactions",
        "raw_prompt_stored": False,
        "answer_text_stored": False,
    }


def assistant_session_context(
    store: CoreStore,
    *,
    session_id: str,
    parent_message_id: str | None,
    current_interaction_id: str | None,
    actor: str,
) -> dict[str, Any]:
    """Build bounded follow-up context from input-redacted ledger metadata."""

    parent_id = (
        assistant_safe_identifier(parent_message_id, "", 80)
        if parent_message_id
        else None
    )
    prior_turns = [
        item
        for item in store.list_assistant_interactions()
        if item.get("session_id") == session_id
        and item.get("actor") == actor
        and item.get("interaction_id") != current_interaction_id
    ]
    prior_turns.sort(
        key=lambda item: (
            str(item.get("created_at") or ""),
            str(item.get("interaction_id") or ""),
        )
    )
    empty_context = {
        "status": "new_session",
        "prior_turn_count": 0,
        "parent_message_id": parent_id,
        "parent_match": False,
        "last_prior_turn": None,
        "category_counts": {},
        "status_counts": {},
        "evidence_counts": {"runtime": 0, "knowledge": 0, "total": 0},
        "safe_context_fields": [
            "session_id",
            "message_id",
            "parent_message_id",
            "prompt_category",
            "response_status",
            "confidence",
            "evidence_count",
            "knowledge_count",
        ],
        "storage_policy": "sha256_16_prompt_hash_only",
        "raw_prompt_stored": False,
        "answer_text_stored": False,
        "provider_payload_stored": False,
        "isolation_policy": "session_id_actor_parent_match",
    }
    if not prior_turns:
        return empty_context
    if not parent_id:
        return {**empty_context, "status": "parent_required"}
    parent_turn = next(
        (item for item in prior_turns if item.get("message_id") == parent_id), None
    )
    if not parent_turn:
        return {**empty_context, "status": "parent_not_found"}
    category_counts: dict[str, int] = {}
    status_counts: dict[str, int] = {}
    evidence_total = 0
    knowledge_total = 0
    for item in prior_turns:
        category = str(item.get("prompt_category") or "uncategorized")
        status = str(item.get("response_status") or "unknown")
        category_counts[category] = category_counts.get(category, 0) + 1
        status_counts[status] = status_counts.get(status, 0) + 1
        evidence_total += int(item.get("evidence_count") or 0)
        knowledge_total += int(item.get("knowledge_count") or 0)
    last_turn = prior_turns[-1] if prior_turns else None
    last_prior_turn = (
        {
            "message_id": last_turn["message_id"],
            "response_status": last_turn["response_status"],
            "confidence": last_turn["confidence"],
            "prompt_category": last_turn["prompt_category"],
            "evidence_count": last_turn["evidence_count"],
            "knowledge_count": last_turn["knowledge_count"],
        }
        if last_turn
        else None
    )
    return {
        "status": "context_available" if prior_turns else "new_session",
        "prior_turn_count": len(prior_turns),
        "parent_message_id": parent_id,
        "parent_match": bool(parent_turn),
        "last_prior_turn": last_prior_turn,
        "category_counts": category_counts,
        "status_counts": status_counts,
        "evidence_counts": {
            "runtime": evidence_total,
            "knowledge": knowledge_total,
            "total": evidence_total + knowledge_total,
        },
        "safe_context_fields": [
            "session_id",
            "message_id",
            "parent_message_id",
            "prompt_category",
            "response_status",
            "confidence",
            "evidence_count",
            "knowledge_count",
        ],
        "storage_policy": "sha256_16_prompt_hash_only",
        "raw_prompt_stored": False,
        "answer_text_stored": False,
        "provider_payload_stored": False,
        "isolation_policy": "session_id_actor_parent_match",
    }


def assistant_tool_owner(endpoint: str) -> str:
    """Map application tool endpoints to the owning dashboard agent."""

    if "/recovery" in endpoint or "/alerts" in endpoint:
        return "alert_recovery_agent"
    if "/rag" in endpoint or "/chat" in endpoint or "/ai/" in endpoint:
        return "ai_diagnosis_agent"
    if "/agents" in endpoint or "/admin" in endpoint:
        return "admin_governance_agent"
    if "/reports" in endpoint or "/delivery" in endpoint:
        return "reporting_compliance_agent"
    return "operations_coordinator"


def assistant_recovery_approval_endpoint(proposal_id: str) -> str:
    """Build the bounded recovery approval endpoint for a known proposal id."""

    safe_id = safe_assistant_proposal_id(proposal_id)
    return f"/api/recovery/proposals/{safe_id}/approve"


def assistant_recovery_target_from_endpoint(endpoint: str) -> str | None:
    """Extract a recovery proposal id from a bounded approval endpoint."""

    match = re.fullmatch(
        r"/api/recovery/proposals/([A-Za-z0-9_.:-]{4,80})/approve",
        endpoint,
    )
    return match.group(1) if match else None


def assistant_tool_plan_endpoints(response: ChatResponse, allowed_tools: list[str]) -> list[str]:
    """Return customer-safe read-only API tools for assistant evidence plans."""

    endpoints: list[str] = []
    for item in response.evidence_links:
        endpoint = safe_assistant_tool_plan_endpoint(item["endpoint"])
        if endpoint:
            endpoints.append(endpoint)
    endpoints.extend(safe_ai_provider_allowed_tools(allowed_tools))
    return list(dict.fromkeys(endpoints))[:10]


def assistant_hitl_recovery_tools(response: ChatResponse) -> list[dict[str, Any]]:
    """Return app-owned recovery approval proposals outside provider tool policy."""

    tools: list[dict[str, Any]] = []
    for item in response.evidence_links:
        if item.get("type") != "recovery_proposal" or not item.get("id"):
            continue
        tools.append(
            {
                "tool_id": assistant_recovery_approval_endpoint(str(item["id"])),
                "purpose": "prepare approval-gated recovery action",
                "mcp_boundary": "application_api_tool",
                "call_type": "approval_gated_write",
                "approval_required": True,
            }
        )
    return tools


def assistant_tool_proposals(
    response: ChatResponse, session: dict[str, Any]
) -> list[dict[str, Any]]:
    """Return HITL-bounded application tool proposals without executing them."""

    package = response.coworker_package or {}
    tool_plan = package.get("tool_plan") or []
    if not tool_plan:
        tool_plan = [
            {
                "tool_id": endpoint,
                "purpose": "read evidence",
                "mcp_boundary": "application_api_tool",
                "call_type": "read",
                "approval_required": False,
            }
            for item in response.evidence_links
            for endpoint in [safe_assistant_tool_plan_endpoint(item.get("endpoint", ""))]
            if endpoint
        ]
    normalized_plan: list[dict[str, Any]] = []
    seen_endpoints: set[str] = set()
    for item in tool_plan:
        endpoint = safe_assistant_tool_plan_endpoint(
            str(item.get("tool_id") or item.get("endpoint") or "")
        )
        if not endpoint or endpoint in seen_endpoints:
            continue
        seen_endpoints.add(endpoint)
        normalized_plan.append(
            {
                "tool_id": endpoint,
                "purpose": item.get("purpose", "read evidence"),
                "mcp_boundary": item.get("mcp_boundary", "application_api_tool"),
                "call_type": "read",
                "approval_required": False,
            }
        )
    hitl_plan: list[dict[str, Any]] = []
    for item in assistant_hitl_recovery_tools(response):
        endpoint = str(item["tool_id"])
        if endpoint in seen_endpoints:
            continue
        seen_endpoints.add(endpoint)
        hitl_plan.append(item)
    proposal_plan = normalized_plan[: max(0, 8 - len(hitl_plan))] + hitl_plan[:8]
    proposals: list[dict[str, Any]] = []
    for index, item in enumerate(proposal_plan, start=1):
        endpoint = str(item["tool_id"])
        write_like = False
        if item.get("call_type") != "read" or bool(item.get("approval_required")):
            write_like = True
        proposal_hash = hashlib.sha256(
            f"{session.get('session_id', 'preview')}:{endpoint}:{index}".encode("utf-8")
        ).hexdigest()[:10]
        proposals.append(
            {
                "proposal_id": f"tool-proposal-{index:02d}-{proposal_hash}",
                "session_id": session.get("session_id"),
                "tool_id": endpoint,
                "endpoint": endpoint,
                "method": "POST" if write_like else "GET",
                "title": (
                    "Prepare approval-gated action" if write_like else "Open evidence view"
                ),
                "purpose": item.get("purpose", "Support grounded operator decision"),
                "owner_agent_id": assistant_tool_owner(endpoint),
                "mcp_boundary": item.get("mcp_boundary", "application_api_tool"),
                "a2a_schema_version": "a2a.envelope.v1",
                "requires_human_approval": bool(write_like),
                "execution_allowed": not write_like,
                "execution_state": (
                    "blocked_until_human_approval" if write_like else "read_only_ready"
                ),
                "acceptance_gate": (
                    "operator_scope_and_hitl_approval"
                    if write_like
                    else "read_only_customer_safe_evidence"
                ),
                "risk": "controlled_write" if write_like else "read_only",
                "evidence_endpoint": endpoint if endpoint.startswith("/") else "/api/operations/summary",
                "status": "proposed",
            }
        )
    return proposals


def assistant_apply_persisted_tool_state(
    store: CoreStore, proposals: list[dict[str, Any]], session: dict[str, Any]
) -> list[dict[str, Any]]:
    """Merge durable prepared proposal state into current workbench proposals."""

    persisted = {
        item["proposal_id"]: item
        for item in store.list_assistant_tool_proposals(
            session_id=session.get("session_id")
        )
    }
    merged: list[dict[str, Any]] = []
    for proposal in proposals:
        saved = persisted.get(proposal["proposal_id"])
        if not saved:
            merged.append(proposal)
            continue
        item = dict(proposal)
        item.update(
            {
                "execution_allowed": saved["execution_allowed"],
                "execution_state": saved["execution_state"],
                "target_required_scope": saved["target_required_scope"],
                "audit_event_id": saved["audit_event_id"],
                "finding_id": saved["finding_id"],
                "prepared_at": saved["updated_at"],
                "approved_at": (
                    saved["updated_at"]
                    if saved["execution_state"] == "approved_recorded"
                    else None
                ),
                "status": (
                    "approved"
                    if saved["execution_state"] == "approved_recorded"
                    else "prepared"
                ),
            }
        )
        merged.append(item)
    return merged


