def rag_quality_console(store: CoreStore) -> dict[str, Any]:
    """Return deterministic RAG quality evidence without provider calls."""

    base = rag_knowledge_base(store)
    metrics = base["metrics"]
    profiles = store.list_ai_analysis_profiles()
    active_profile = profiles["active_profile"]
    retrieval_probes: list[dict[str, Any]] = []
    grounding_gaps: list[dict[str, Any]] = []
    maintenance_items: list[dict[str, Any]] = []
    ready_probe_count = 0
    for probe in RAG_QUALITY_PROBES:
        result = rag_search(store, probe["query"], top_k=3)
        matches = result["matches"]
        top_match = matches[0] if matches else {
            "doc_id": "missing",
            "title": "No customer-safe match",
            "category": probe["target_category"],
            "summary": "No matching RAG document is available for this probe.",
            "endpoint": "/api/rag/search",
            "score": 0,
        }
        score = int(top_match.get("score", 0) or 0)
        state = "ready" if matches and score >= 2 else "review_required"
        if state == "ready":
            ready_probe_count += 1
        else:
            grounding_gaps.append(
                {
                    "gap_id": probe["probe_id"] + "-gap",
                    "owner_agent_id": probe["owner_agent_id"],
                    "severity": "medium",
                    "finding": "Retrieval probe needs stronger customer-safe evidence coverage.",
                    "evidence_endpoint": "/api/rag/search",
                }
            )
        retrieval_probes.append(
            {
                "probe_id": probe["probe_id"],
                "query": probe["query"],
                "owner_agent_id": probe["owner_agent_id"],
                "target_category": probe["target_category"],
                "state": state,
                "match_count": len(matches),
                "top_match": {
                    "doc_id": top_match["doc_id"],
                    "title": top_match["title"],
                    "category": top_match["category"],
                    "summary": top_match["summary"],
                    "endpoint": top_match["endpoint"],
                    "score": score,
                },
            }
        )
    if not grounding_gaps:
        maintenance_items.append(
            {
                "item_id": "rag-continuous-review",
                "owner_agent_id": "ai_diagnosis_agent",
                "severity": "low",
                "state": "maintenance",
                "blocking": False,
                "finding": "Continue bounded retrieval regression checks before release claims.",
                "evidence_endpoint": "/api/qa/evidence-report",
            }
        )
    document_score = min(40, int(metrics["document_count"]) * 8)
    category_score = min(30, int(metrics["category_count"]) * 10)
    probe_score = min(30, ready_probe_count * 8)
    coverage_score = min(100, document_score + category_score + probe_score)
    status = "ready" if coverage_score >= 80 else "review_required"
    action_plan = [
        {
            "action_id": "rag-probe-regression",
            "owner_agent_id": "ai_diagnosis_agent",
            "priority": "high" if status != "ready" else "normal",
            "action": "Run retrieval probes before delivery and keep every answer grounded in local evidence.",
            "evidence_endpoint": "/api/rag/quality-console",
        },
        {
            "action_id": "rag-gap-review",
            "owner_agent_id": "reporting_compliance_agent",
            "priority": "normal",
            "action": "Record grounding gaps in the customer-safe evidence pack.",
            "evidence_endpoint": "/api/qa/evidence-report",
        },
        {
            "action_id": "rag-admin-maintenance",
            "owner_agent_id": "admin_governance_agent",
            "priority": "normal",
            "action": "Maintain RAG documents through the admin update endpoint with customer-safe text only.",
            "evidence_endpoint": "/api/admin/rag/knowledge/{doc_id}",
        },
    ]
    return {
        "status": status,
        "version": __version__,
        "prepared_for": CUSTOMER_NAME,
        "prepared_by": CONTRACTOR_NAME,
        "summary": {
            "document_count": metrics["document_count"],
            "category_count": metrics["category_count"],
            "coverage_score": coverage_score,
            "retrieval_probe_count": len(retrieval_probes),
            "ready_probe_count": ready_probe_count,
            "grounding_gap_count": len(grounding_gaps),
            "maintenance_item_count": len(maintenance_items),
            "storage_policy": "customer_safe_knowledge_only",
        },
        "profile_alignment": {
            "profile_id": active_profile["profile_id"],
            "routing_layer": active_profile["routing_layer"],
            "answer_layer": active_profile["answer_layer"],
            "rag_mode": "runtime_and_delivery_evidence",
            "evaluation_gate": active_profile["evaluation_gate"],
        },
        "retrieval_probes": retrieval_probes,
        "grounding_gaps": grounding_gaps,
        "maintenance_items": maintenance_items,
        "action_plan": action_plan,
        "charts": [
            {
                "chart_id": "rag-quality-coverage",
                "title": "RAG Quality Coverage",
                "type": "bar",
                "unit": "score",
                "series": [
                    {"label": "Documents", "value": document_score},
                    {"label": "Categories", "value": category_score},
                    {"label": "Retrieval probes", "value": probe_score},
                ],
            },
            {
                "chart_id": "rag-retrieval-probes",
                "title": "RAG Retrieval Probes",
                "type": "bar",
                "unit": "probes",
                "series": [
                    {"label": "Ready", "value": ready_probe_count},
                    {"label": "Review", "value": len(retrieval_probes) - ready_probe_count},
                    {"label": "Gaps", "value": len(grounding_gaps)},
                    {"label": "Maintenance", "value": len(maintenance_items)},
                ],
            },
        ],
        "evidence_links": [
            {"label": "Knowledge base", "endpoint": "/api/rag/knowledge-base"},
            {"label": "Search evidence", "endpoint": "/api/rag/search"},
            {"label": "Quality console", "endpoint": "/api/rag/quality-console"},
        ],
        "privacy": {
            "provider_calls": "none",
            "prompt_storage": "not_stored",
            "local_paths": "not_exposed",
            "contact_data": "not_accepted",
        },
    }



def rag_grounding_for_message(
    store: CoreStore, message: str
) -> list[dict[str, Any]]:
    """Return compact RAG grounding records for assistant answers."""

    result = rag_search(store, message, top_k=3)
    return [
        {
            "type": "rag_knowledge",
            "id": item["doc_id"],
            "summary": item["summary"],
            "endpoint": "/api/rag/search",
            "score": item["score"],
        }
        for item in result["matches"]
    ]


def execute_agent_task(
    store: CoreStore,
    request: AgentTaskRequest,
    actor: str,
    production: bool,
    control_hooks: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Execute a bounded, audited agent task and optional product control action."""

    agents = store.list_dashboard_agents()
    if not any(agent["enabled"] for agent in agents):
        raise HTTPException(status_code=503, detail="No enabled dashboard agents")
    primary_agent = choose_agent_for_goal(
        agents, request.goal, request.preferred_agent_id
    )
    route = build_agent_route(agents, primary_agent)
    trace = build_a2a_trace(agents, route)
    summary = operation_summary(store, production)
    routing = ai_routing_status(store)
    evidence = [
        {"label": "Operations summary", "endpoint": "/api/operations/summary"},
        {"label": "Agent registry", "endpoint": "/api/admin/agents"},
        {"label": "Dashboard reports", "endpoint": "/api/reports/dashboard"},
        {"label": "Analysis profiles", "endpoint": "/api/admin/ai/analysis-profiles"},
    ]
    control_action = request.action or action_from_goal(request.goal)
    if str(request.goal or "").strip().lower().startswith("autopilot mission"):
        control_action = None
    control_result: dict[str, Any] | None = None
    requires_human_approval = (
        primary_agent["mode"] == "approval_required"
        or summary["counters"]["pending_recovery"] > 0
        or any(item["approval_required"] for item in trace)
    )
    answer = (
        f"{primary_agent['display_name']} handled the task through "
        f"{len(route)} agent step(s). Current state is "
        f"{summary['operational_state']}; next action is "
        f"{summary['next_actions'][0]} Assistant route is "
        f"{routing['active_route']}. Agent profile is "
        f"{primary_agent['analysis_profile_id']} with model route "
        f"{primary_agent['model_route']}."
    )
    if control_action:
        hooks = control_hooks or {}
        control_result = run_control_action(
            store,
            control_action,
            actor=actor,
            mqtt_status=hooks.get("mqtt_status"),
            http_check=hooks.get("http_check"),
            cmdb_builder=hooks.get("cmdb_builder"),
            autopilot=hooks.get("autopilot"),
        )
        requires_human_approval = requires_human_approval or bool(
            control_result.get("hitl")
        )
        answer = (
            f"{answer} Control action {control_action} completed with status "
            f"{control_result.get('status')}."
        )
        evidence.append(
            {
                "label": "Agentic control",
                "endpoint": "/api/control/dashboard",
            }
        )
    result = store.add_agent_run(
        goal=request.goal,
        primary_agent_id=primary_agent["agent_id"],
        route=route,
        trace=trace,
        evidence=evidence,
        answer=answer,
        requires_human_approval=requires_human_approval,
        actor=actor,
    )
    store.add_evidence_finding(
        source="agent_task",
        subject_id=result["run_id"],
        outcome=primary_agent["agent_id"],
        severity="review_required" if requires_human_approval else "info",
        evidence=(
            f"Route length {len(route)}; state {summary['operational_state']}; "
            f"approval required {requires_human_approval}."
        ),
        lesson="Preserve A2A route, evidence links, and HITL boundary before closing the task.",
    )
    result["analysis_profile_id"] = primary_agent["analysis_profile_id"]
    result["model_route"] = primary_agent["model_route"]
    result["trace_policy"] = primary_agent["trace_policy"]
    if control_result is not None:
        result["control"] = control_result
    return result


def autopilot_mission_summary(agent_runs: list[dict[str, Any]]) -> dict[str, Any]:
    """Summarize stored agent autopilot mission runs from task evidence."""

    autopilot_runs = [
        run for run in agent_runs if run["goal"].startswith("Autopilot mission:")
    ]
    latest_runs: list[dict[str, Any]] = []
    if autopilot_runs:
        latest_label = autopilot_runs[-1]["goal"].split(" for ", 1)[0]
        latest_runs = [run for run in autopilot_runs if run["goal"].startswith(latest_label)]
    runs = latest_runs or autopilot_runs
    expected_agents = sum(
        1 for agent in DEFAULT_DASHBOARD_AGENTS if agent.get("enabled", True)
    )
    return {
        "status": "completed" if runs else "waiting_for_run",
        "runs_created": len(runs),
        "expected_agents": expected_agents,
        "agent_ids": [run["primary_agent_id"] for run in runs],
        "approval_required_runs": sum(
            1 for run in runs if run["requires_human_approval"]
        ),
        "a2a_trace_steps": sum(len(run["a2a_trace"]) for run in runs),
        "latest_run_id": runs[-1]["run_id"] if runs else None,
        "created_at": runs[-1]["created_at"] if runs else None,
    }


def run_agent_autopilot_mission(
    store: CoreStore,
    request: AgentAutopilotRequest,
    *,
    actor: str,
    production: bool,
) -> dict[str, Any]:
    """Activate every section agent once and persist A2A evidence."""

    agents = store.list_dashboard_agents()
    selected_agents = [
        agent for agent in agents if request.include_disabled or agent["enabled"]
    ]
    if not selected_agents:
        raise HTTPException(status_code=503, detail="No dashboard agents available")
    mission_id = f"agent-autopilot-{int(time.time() * 1000)}-{secrets.token_hex(2)}"
    created_at = utc_now()
    runs = []
    for agent in selected_agents:
        goal = (
            f"Autopilot mission: {request.mission_label} for "
            f"{agent['display_name']}. Review the owned section, A2A links, "
            "evidence endpoints, quality gate, and next action."
        )
        result = execute_agent_task(
            store,
            AgentTaskRequest(goal=goal, preferred_agent_id=agent["agent_id"]),
            actor=actor,
            production=production,
        )
        runs.append(result)
    summary = {
        "enabled_agents": sum(1 for agent in selected_agents if agent["enabled"]),
        "selected_agents": len(selected_agents),
        "runs_created": len(runs),
        "approval_required_runs": sum(
            1 for run in runs if run["requires_human_approval"]
        ),
        "a2a_trace_steps": sum(len(run["a2a_trace"]) for run in runs),
        "evidence_links": sum(len(run["evidence"]) for run in runs),
    }
    store.add_evidence_finding(
        source="agent_autopilot",
        subject_id=mission_id,
        outcome="all_enabled_agents",
        severity="review_required" if summary["approval_required_runs"] else "info",
        evidence=(
            f"{summary['runs_created']} run(s), "
            f"{summary['a2a_trace_steps']} A2A step(s), "
            f"{summary['approval_required_runs']} approval-gated run(s)."
        ),
        lesson="Run the section-agent autopilot after UI or workflow changes so every dashboard owner creates current evidence.",
    )
    return {
        "status": "completed",
        "mission_id": mission_id,
        "mission_label": request.mission_label,
        "summary": summary,
        "agent_ids": [run["primary_agent_id"] for run in runs],
        "runs": runs,
        "created_at": created_at,
    }


def architecture_decision_register(store: CoreStore) -> dict[str, Any]:
    """Return customer-safe ADR governance for the agent orchestra."""

    agents = {agent["agent_id"]: agent for agent in store.list_dashboard_agents()}
    sections = dashboard_section_ownership_matrix(store, list(agents.values()))
    items = []
    for decision in AGENT_ARCHITECTURE_DECISIONS:
        owner = agents.get(decision["owner_agent_id"])
        governed_sections = [
            section["section_id"]
            for section in sections
            if section["owner_agent_id"] == decision["owner_agent_id"]
            or any(endpoint in decision["evidence_endpoints"] for endpoint in section["evidence_endpoints"])
        ]
        items.append(
            {
                **decision,
                "owner_agent": owner["display_name"] if owner else "Unassigned",
                "owner_enabled": bool(owner and owner["enabled"]),
                "governed_sections": sorted(set(governed_sections)),
                "customer_safe": all(
                    endpoint.startswith("/") for endpoint in decision["evidence_endpoints"]
                )
                and bool(decision["acceptance_gates"]),
            }
        )
    return {
        "status": "ok",
        "version": __version__,
        "prepared_for": CUSTOMER_NAME,
        "prepared_by": CONTRACTOR_NAME,
        "summary": {
            "total": len(items),
            "accepted": sum(1 for item in items if item["status"] == "accepted"),
            "customer_safe": sum(1 for item in items if item["customer_safe"]),
            "governed_sections": len({section for item in items for section in item["governed_sections"]}),
            "acceptance_gates": sum(len(item["acceptance_gates"]) for item in items),
        },
        "standards": {
            "adr": "Architecture Decision Record register with owner and acceptance gates",
            "a2a": "A2A-compatible product profile for discovery, routing, handoff, and audited results",
            "guardrails": "HITL, RBAC, trace, eval, and customer-safe evidence boundaries",
            "privacy": "No raw operator inputs, secrets, local paths, or restricted build artifacts in customer outputs",
        },
        "items": items,
    }


def agent_orchestration_registry(
    store: CoreStore, *, include_sensitive: bool = False
) -> dict[str, Any]:
    """Return agent registry, standards, and A2A edges."""

    source_agents = store.list_dashboard_agents()
    agents = source_agents if include_sensitive else [
        redact_dashboard_agent(agent) for agent in source_agents
    ]
    edges = []
    for agent in source_agents:
        for target in agent["connected_agents"]:
            edges.append(
                {
                    "from": agent["agent_id"],
                    "to": target,
                    "protocol": agent["a2a_card"]["protocol"],
                    "approval_required": agent["a2a_card"]["approval_required"],
                }
            )
    team_graph = specialized_team_graph()
    return {
        "status": "ok",
        "version": __version__,
        "prepared_for": CUSTOMER_NAME,
        "prepared_by": CONTRACTOR_NAME,
        "detail_level": "full" if include_sensitive else "customer_safe_summary",
        "orchestration_policy": multi_team_orchestration_policy(team_graph),
        "team_graph": team_graph,
        "standards": {
            "adr": "ADR-0001 Agent-Orchestrated Dashboard",
            "a2a": "A2A-compatible product profile for discovery, routing, handoff, and audited results",
            "a2a_message_envelope": "{id, from, to, type, schema_version, payload, trace_id, ts}",
            "mcp_boundary": "Agents use application-owned API tools; external tool providers stay behind configured adapters.",
            "human_approval": "Recovery and admin changes require human approval or admin role scope.",
            "evals": "Grounding, fallback, provider-label, approval, and report completeness checks are required before release.",
            "adr_register": "/api/architecture/adr",
        },
        "agents": agents,
        "edges": edges,
        "admin_controls": {
            "read_endpoint": "/api/admin/agents",
            "update_endpoint": "/api/admin/agents/{agent_id}",
            "required_role": "admin",
            "required_scope": "agent:manage",
            "detail_level": "full" if include_sensitive else "customer_safe_summary",
        },
        "control_plane": {
            "agent_endpoint": "/api/admin/agents/{agent_id}",
            "profile_endpoint": "/api/admin/ai/analysis-profiles",
            "provider_endpoint": "/api/admin/ai/provider-policy",
            "task_endpoint": "/api/agents/tasks",
            "adr_endpoint": "/api/architecture/adr",
            "trace_standard": "Agents SDK trace semantics",
            "eval_standard": "Trace grading, grounding, A2A handoff, guardrail, and HITL gates",
        },
    }


def agent_prompt_contract(
    agent: dict[str, Any], *, include_sensitive: bool = False
) -> dict[str, Any]:
    """Return one managed instruction contract with public redaction."""

    evidence_endpoints = sorted(
        set(
            agent["tools"]
            + [
                "/api/admin/agents",
                "/api/admin/agents/prompt-contracts",
                "/api/architecture/adr",
                "/api/agents/tasks",
            ]
        )
    )
    if include_sensitive:
        evidence_endpoints.append("/api/admin/agents/{agent_id}/prompt-contract")
    return {
        "managed_prompt_id": f"agent.{agent['agent_id']}.contract",
        "agent_id": agent["agent_id"],
        "display_name": agent["display_name"],
        "section": agent["section"],
        "role": agent["role"],
        "mode": agent["mode"],
        "enabled": agent["enabled"],
        "analysis_profile_id": agent["analysis_profile_id"],
        "model_route": agent["model_route"],
        "trace_policy": agent["trace_policy"],
        "eval_profile": agent["eval_profile"],
        "instruction_template": agent["instruction_template"] if include_sensitive else PUBLIC_REDACTION_LABEL,
        "operating_brief": agent["operating_brief"] if include_sensitive else PUBLIC_REDACTION_LABEL,
        "handoff_policy": agent["handoff_policy"] if include_sensitive else PUBLIC_REDACTION_LABEL,
        "quality_gate_policy": agent["quality_gate_policy"] if include_sensitive else PUBLIC_REDACTION_LABEL,
        "input_contract": agent["a2a_card"]["input"],
        "output_contract": agent["a2a_card"]["output"],
        "a2a_protocol": agent["a2a_card"]["protocol"],
        "a2a_links": agent["connected_agents"],
        "approval_required": agent["a2a_card"]["approval_required"],
        "adr_id": AGENT_ADR_ID,
        "editable_fields": [
            "instruction_template",
            "operating_brief",
            "handoff_policy",
            "quality_gate_policy",
            "eval_profile",
        ],
        "prompt_storage": "versioned_templates_only",
        "customer_delivery": "runtime_policy_record_only",
        "safety_rules": [
            "Use only customer-safe runtime evidence policies.",
            "Do not include credentials, personal contact data, or provider payloads.",
            "Keep recovery actions behind human approval.",
            "Link every recommendation to evidence endpoints and A2A trace metadata.",
        ],
        "evidence_links": [
            {"label": endpoint.strip("/") or "dashboard", "endpoint": endpoint}
            for endpoint in evidence_endpoints
        ],
        "updated_by": agent.get("updated_by", "system")
        if include_sensitive
        else "redacted",
        "updated_at": agent.get("updated_at"),
        "detail_level": "full" if include_sensitive else "customer_safe_summary",
    }


def agent_prompt_contract_console(
    store: CoreStore, *, include_sensitive: bool = False
) -> dict[str, Any]:
    """Return the admin prompt-contract control plane."""

    contracts = []
    for agent in store.list_dashboard_agents():
        contract = agent_prompt_contract(agent, include_sensitive=include_sensitive)
        history = store.list_agent_prompt_contract_versions(
            agent["agent_id"], include_sensitive=False
        )
        latest_version = history[0]["version"] if history else 0
        contract_update = {
            "latest_version": latest_version,
            "history_count": len(history),
            "diff_policy": "hash_length_field_diff",
            "rollback_policy": "admin_scope_required_new_version_created",
            "history_endpoint": (
                f"/api/admin/agents/{agent['agent_id']}/prompt-contract/history"
            ),
        }
        if include_sensitive:
            contract_update["rollback_endpoint"] = (
                f"/api/admin/agents/{agent['agent_id']}/prompt-contract/rollback"
            )
        contract.update(contract_update)
        contracts.append(contract)
    admin_surface = {
        "read_endpoint": "/api/admin/agents/prompt-contracts",
        "history_endpoint": "/api/admin/agents/{agent_id}/prompt-contract/history",
        "registry_endpoint": "/api/admin/agents",
        "adr_endpoint": "/api/architecture/adr",
    }
    if include_sensitive:
        admin_surface.update(
            {
                "update_endpoint": "/api/admin/agents/{agent_id}/prompt-contract",
                "rollback_endpoint": "/api/admin/agents/{agent_id}/prompt-contract/rollback",
            }
        )
    return {
        "status": "ok",
        "version": __version__,
        "prepared_for": CUSTOMER_NAME,
        "prepared_by": CONTRACTOR_NAME,
        "summary": {
            "contract_count": len(contracts),
            "enabled_count": sum(1 for item in contracts if item["enabled"]),
            "a2a_link_count": sum(len(item["a2a_links"]) for item in contracts),
            "storage_policy": "customer_safe_templates_only",
            "required_scope": "agent:manage",
            "versioned_count": sum(1 for item in contracts if item["latest_version"] >= 1),
            "history_count": sum(item["history_count"] for item in contracts),
            "diff_policy": "hash_length_field_diff",
            "rollback_policy": "admin_scope_required_new_version_created",
        },
        "admin_surface": admin_surface,
        "items": contracts,
    }


def agent_tool_contract(endpoint: str, owner_agent_ids: list[str]) -> dict[str, Any]:
    """Return one bounded application-tool contract for agent use."""

    write_like = endpoint.startswith(
        ("/api/admin", "/api/recovery", "/api/agents/tasks", "/api/agents/autopilot")
    )
    return {
        "tool_id": endpoint,
        "endpoint": endpoint,
        "mcp_boundary": "application_api_tool",
        "owner_agent_ids": sorted(set(owner_agent_ids)),
        "call_type": "approval_gated_write" if write_like else "read",
        "target_required_scope": assistant_target_scope(endpoint),
        "approval_required": write_like,
        "secret_policy": "never_return_credentials_or_provider_payloads",
        "evidence_policy": "return_customer_safe_records_only",
        "schema_version": "tool.contract.v1",
    }


