def build_continuous_qa_mission(
    store: CoreStore,
    production: bool,
    request: ContinuousQAMissionRequest,
) -> dict[str, Any]:
    """Build a 60-minute continuous QA mission plan without long blocking work."""

    profiles = store.list_ai_analysis_profiles()
    profile_ids = {item["profile_id"] for item in profiles["items"]}
    if request.profile_id not in profile_ids:
        raise HTTPException(status_code=404, detail="Analysis profile not found")
    lanes = continuous_qa_lanes(store, production)
    ready_count = sum(1 for item in lanes if item["state"] == "ready")
    mission_id = "continuous-qa-plan"
    return {
        "status": "planned",
        "mission_id": mission_id,
        "profile_id": request.profile_id,
        "duration_minutes": request.duration_minutes,
        "question_rounds": request.question_rounds,
        "kpi_target": 99.99,
        "coverage_score": round(ready_count / len(lanes) * 100),
        "bounded": True,
        "lanes": lanes,
        "ab_tests": [
            {
                "test_id": "routing-layer",
                "option_a": "grounded-operations",
                "option_b": "copilot-grade-operations",
                "winner_rule": "highest grounded answer score with no credential exposure",
            },
            {
                "test_id": "visual-workflow",
                "option_a": "cockpit quick action",
                "option_b": "detailed workspace section",
                "winner_rule": "shortest path to evidence without raw service or text overflow",
            },
        ],
        "stress_profile": {
            "max_devices": 8,
            "max_telemetry_samples": 96,
            "max_question_rounds": request.question_rounds,
            "large_dataset_allowed": False,
        },
        "sla": {
            "target_success_rate": 99.99,
            "target_visual_pass_rate": 99.99,
            "target_raw_json_menu_links": 0,
            "evidence_level": "bounded_rehearsal_plan",
        },
        "closed_loop": {
            "source": "continuous_qa_mission",
            "findings_recorded": 0,
            "lesson": "Every failed mission lane must become a closed-loop finding before release.",
        },
    }


def latest_continuous_qa_mission(
    store: CoreStore, production: bool
) -> dict[str, Any]:
    """Return current continuous QA mission status for reports and dashboard UI."""

    mission = build_continuous_qa_mission(
        store,
        production,
        ContinuousQAMissionRequest(),
    )
    findings = [
        item
        for item in store.list_evidence_findings()
        if item["source"] == "continuous_qa_mission"
    ]
    if not findings:
        return mission
    latest_id = findings[0]["subject_id"].split(":", 1)[0]
    recorded = [
        item for item in findings if item["subject_id"].startswith(f"{latest_id}:")
    ]
    mission["status"] = "completed"
    mission["mission_id"] = latest_id
    mission["closed_loop"]["findings_recorded"] = len(recorded)
    return mission


def qa_evidence_report(store: CoreStore, production: bool) -> dict[str, Any]:
    """Return the QA evidence report used by the admin dashboard."""

    mission = latest_continuous_qa_mission(store, production)
    challenge_runs = store.list_qa_challenge_runs()
    assistant_qa = assistant_qa_challenge_summary(store.list_ai_eval_runs())
    latest_challenge = challenge_runs[0] if challenge_runs else None
    lane_ready = all(item["state"] == "ready" for item in mission["lanes"])
    mission_recorded = mission["status"] == "completed"
    challenge_passed = bool(latest_challenge and latest_challenge["passed"])
    ab_ready = len(mission["ab_tests"]) >= 2
    stress_ready = (
        mission["stress_profile"]["max_devices"] <= 8
        and not mission["stress_profile"]["large_dataset_allowed"]
    )
    assistant_qa_ready = assistant_qa["status"] == "ready"
    gates = [
        ("qa_challenge", challenge_passed, "Run a bounded QA challenge."),
        ("continuous_mission", mission_recorded, "Record continuous QA mission evidence."),
        ("assistant_qa_60", assistant_qa_ready, "Run the 60-round assistant answer-quality review."),
        ("standard_lanes", lane_ready, "Resolve every QA mission lane."),
        ("ab_tests", ab_ready, "Keep at least two A/B comparison paths."),
        ("stress_bounds", stress_ready, "Keep stress simulation bounded and repeatable."),
    ]
    ready_count = sum(1 for _name, passed, _gap in gates if passed)
    gaps = [gap for _name, passed, gap in gates if not passed]
    latest_challenge_view = None
    if latest_challenge:
        latest_challenge_view = {
            "run_id": latest_challenge["run_id"],
            "score": latest_challenge["score"],
            "kpi_actual": latest_challenge["kpi_actual"],
            "kpi_target": latest_challenge["kpi_target"],
            "passed": latest_challenge["passed"],
            "case_count": latest_challenge["case_count"],
            "created_at": latest_challenge["created_at"],
        }
    return {
        "status": "ready" if not gaps else "review_required",
        "version": __version__,
        "score": round((ready_count / len(gates)) * 100),
        "kpi_target": 99.99,
        "latest_challenge": latest_challenge_view,
        "continuous_mission": {
            "mission_id": mission["mission_id"],
            "status": mission["status"],
            "duration_minutes": mission["duration_minutes"],
            "question_rounds": mission["question_rounds"],
            "coverage_score": mission["coverage_score"],
            "findings_recorded": mission["closed_loop"]["findings_recorded"],
        },
        "assistant_qa_challenge": assistant_qa,
        "standards": mission["lanes"],
        "ab_tests": mission["ab_tests"],
        "stress_profile": mission["stress_profile"],
        "gaps": gaps,
        "evidence_links": [
            {"label": "QA challenges", "endpoint": "/api/qa/challenge-runs"},
            {"label": "Continuous mission", "endpoint": "/api/qa/continuous-mission"},
            {"label": "UI/UX gate", "endpoint": "/api/ui/quality-gate"},
            {"label": "Agent A2A", "endpoint": "/api/orchestration/evidence-matrix"},
            {"label": "Evidence findings", "endpoint": "/api/evidence/findings"},
            {"label": "Dashboard reports", "endpoint": "/api/reports/dashboard"},
        ],
    }


def record_continuous_qa_mission(
    store: CoreStore,
    production: bool,
    request: ContinuousQAMissionRequest,
    *,
    actor: str,
) -> dict[str, Any]:
    """Record a bounded continuous QA mission rehearsal as closed-loop evidence."""

    mission = build_continuous_qa_mission(store, production, request)
    mission_id = f"continuous-qa-{int(time.time() * 1000)}-{secrets.token_hex(3)}"
    for lane in mission["lanes"]:
        store.add_evidence_finding(
            source="continuous_qa_mission",
            subject_id=f"{mission_id}:{lane['lane_id']}",
            outcome=lane["state"],
            severity="info" if lane["state"] == "ready" else "review_required",
            evidence=f"{lane['standard']} gate {lane['gate']}: {lane['evidence']}",
            lesson="Keep continuous QA mission lanes tied to an owner agent, endpoint, and release gate.",
        )
    store.add_audit_event(
        event_type="qa.continuous_mission.completed",
        subject_id=mission_id,
        actor=actor,
        detail=json.dumps(
            {
                "duration_minutes": request.duration_minutes,
                "question_rounds": request.question_rounds,
                "lanes": len(mission["lanes"]),
                "coverage_score": mission["coverage_score"],
            },
            separators=(",", ":"),
        ),
    )
    mission["status"] = "completed"
    mission["mission_id"] = mission_id
    mission["closed_loop"]["findings_recorded"] = len(mission["lanes"])
    return mission


