def release_evidence_console(store: CoreStore, production: bool) -> dict[str, Any]:
    """Build an actionable, customer-safe release evidence console."""

    mission = latest_release_mission_status(store, production)
    summary = mission.get("summary", {})
    gates = mission.get("gates", [])
    plan = mission.get("remediation_plan", {})
    mission_status = str(mission.get("status", "waiting_for_run"))
    evidence_current = bool(mission.get("evidence_current"))
    evidence_freshness = (
        "not_run"
        if mission.get("mission_id") == "not-run"
        else ("current_version" if evidence_current else "stale_stored")
    )
    gates_ready = int(summary.get("gates_passed", 0) or 0)
    gates_total = int(summary.get("gates_total", len(gates)) or len(gates))
    kpi_score = float(summary.get("kpi_score", 0) or 0)
    sla_target = float(summary.get("sla_target", 99.99) or 99.99)
    sla_gap = round(float(summary.get("sla_gap", max(0.0, sla_target - kpi_score)) or 0), 2)
    action_plan = plan.get("actions", [])
    status = (
        "ready"
        if mission_status in {"completed", "ready"}
        and evidence_current
        and gates_ready == gates_total
        and sla_gap == 0
        else "review_required"
    )
    production_plan = production_action_plan(store, production)
    production_acceptance = {
        "state": production_plan["status"],
        "customer_acceptance_claimed": False,
        "production_owner_signoff_claimed": False,
        "open_action_count": production_plan["summary"]["action_count"],
        "open_control_count": production_plan["summary"]["open_control_count"],
        "open_decision_count": production_plan["summary"]["open_decision_count"],
        "customer_decision_required": production_plan["summary"][
            "customer_decision_required"
        ],
        "evidence_endpoint": "/api/production/action-plan",
        "boundary": (
            "Release evidence readiness is not final production acceptance; "
            "customer and production-owner gates remain separate until recorded."
        ),
    }
    gate_evidence = [
        {
            "gate_id": gate["gate_id"],
            "label": gate["label"],
            "status": gate["status"],
            "score": gate["score"],
            "evidence": gate["evidence"],
            "owner_agent_id": release_evidence_gate_owner(gate["gate_id"]),
            "evidence_endpoint": release_evidence_gate_endpoint(gate["gate_id"]),
            "acceptance_gate": release_evidence_acceptance_gate(gate["gate_id"]),
        }
        for gate in gates
    ]
    return {
        "status": status,
        "version": __version__,
        "prepared_for": CUSTOMER_NAME,
        "prepared_by": CONTRACTOR_NAME,
        "summary": {
            "mission_id": mission.get("mission_id", "not-run"),
            "mission_label": mission.get("mission_label", "No release mission run stored yet"),
            "mission_status": mission_status,
            "kpi_score": kpi_score,
            "sla_target": sla_target,
            "sla_gap": sla_gap,
            "assistant_rounds": int(summary.get("assistant_rounds", 0) or 0),
            "requested_assistant_rounds": int(
                summary.get("requested_assistant_rounds", 0) or 0
            ),
            "assistant_minimum_rounds": int(
                summary.get("assistant_minimum_rounds", RELEASE_ASSISTANT_QA_MIN_ROUNDS)
                or RELEASE_ASSISTANT_QA_MIN_ROUNDS
            ),
            "assistant_round_policy": summary.get(
                "assistant_round_policy", "release_minimum_satisfied"
            ),
            "gates_ready": gates_ready,
            "gates_total": gates_total,
            "evidence_freshness": evidence_freshness,
            "evidence_current": evidence_current,
            "evidence_version": mission.get("evidence_version", "unknown"),
            "action_count": int(plan.get("action_count", len(action_plan)) or 0),
            "provider_calls": int(summary.get("provider_calls", 0) or 0),
            "production_acceptance_state": production_acceptance["state"],
            "customer_acceptance_claimed": False,
            "customer_safe": True,
        },
        "production_acceptance": production_acceptance,
        "gate_evidence": gate_evidence,
        "action_plan": action_plan,
        "charts": [
            {
                "chart_id": "release-evidence-readiness",
                "title": "Release Evidence Readiness",
                "type": "bar",
                "unit": "records",
                "series": [
                    {"label": "Ready gates", "value": gates_ready},
                    {"label": "Open gates", "value": max(0, gates_total - gates_ready)},
                    {"label": "Actions", "value": int(plan.get("action_count", len(action_plan)) or 0)},
                ],
            },
            {
                "chart_id": "release-evidence-sla",
                "title": "Release Evidence SLA",
                "type": "bar",
                "unit": "percent",
                "series": [
                    {"label": "Current", "value": kpi_score},
                    {"label": "Target", "value": sla_target},
                    {"label": "Gap", "value": sla_gap},
                ],
            },
            release_mission_remediation_chart(plan),
        ],
        "evidence_links": release_evidence_links(),
        "privacy": {
            "customer_safe": "true",
            "prompt_storage": "hash_only_or_not_stored",
            "provider_payload_storage": "not_stored",
            "local_path_storage": "not_stored",
            "private_contact_storage": "not_stored",
        },
        "execution_controls": release_evidence_execution_controls(),
    }


def release_gap_closure_console(store: CoreStore, production: bool) -> dict[str, Any]:
    """Map open release gaps to executable, operator-gated closure actions."""

    release = release_evidence_console(store, production)
    summary = release["summary"]
    token_configured = configured_operator_token() is not None
    token_ready = operator_token_ready_for_runtime(production)
    identity_configured = identity_provider_config()["state"] == "configured"
    runnable_now = token_ready or identity_configured
    meta = {
        "baseline-ai-eval": (1, "Run baseline local AI evaluation", "/api/ai/evaluations/runs?suite=baseline&rounds=60", {}, "A baseline_ai_eval run exists, passes, and stores no provider payload."),
        "assistant-qa-challenge": (2, "Run 60-round assistant answer-quality review", "/api/ai/evaluations/runs?suite=assistant_qa_60&rounds=60", {}, "60 hash-only answer-quality cases pass with zero unintended provider calls."),
        "agent-autopilot": (3, "Run section-agent autopilot", "/api/agents/autopilot/run", {"mission_label": "Release gap closure", "include_disabled": False}, "Each enabled section agent records task, A2A trace, evidence links, and HITL boundary."),
        "continuous-qa-mission": (4, "Record continuous QA mission evidence", "/api/qa/continuous-mission", {"duration_minutes": 60, "question_rounds": 60, "profile_id": "grounded-operations"}, "All bounded QA lanes are recorded as closed-loop evidence findings."),
    }
    closure_plan = []
    for gate in release["gate_evidence"]:
        order, label, endpoint, body, evidence = meta[gate["gate_id"]]
        score = float(gate.get("score", 0) or 0)
        open_gate = gate["status"] != "ready"
        blocked_by = [] if (runnable_now or not open_gate) else ["strong_operator_token_or_identity_not_configured"]
        closure_plan.append({
            "gate_id": gate["gate_id"],
            "label": gate["label"],
            "status": gate["status"],
            "owner_agent_id": gate["owner_agent_id"],
            "a2a_next_hop": "release_compliance_controller",
            "current_score": score,
            "target_score": 100,
            "score_gap": round(max(0.0, 100.0 - score), 2),
            "run_order": order,
            "run_label": label,
            "method": "POST",
            "run_endpoint": endpoint,
            "request_body": body,
            "requires_scope": "agent:run",
            "runnable_now": runnable_now and open_gate,
            "blocked_by": blocked_by,
            "acceptance_gate": gate["acceptance_gate"],
            "acceptance_evidence": evidence,
            "safe_command": "Use the dashboard run control or curl with X-Operator-Token: <runtime-token>; never store the token in Git.",
            "kpi_input": "release_gate_evidence",
            "customer_safe": True,
        })
    closure_plan.sort(key=lambda item: (item["status"] == "ready", item["run_order"]))
    open_items = [item for item in closure_plan if item["status"] != "ready"]
    auth_state = "ready" if runnable_now else "operator_setup_required"
    handoff = final_handoff_console(store, production)
    handoff_acceptance_plan = []
    for order, item in enumerate(handoff["action_queue"][:12], start=1):
        state = str(item.get("state", "open"))
        blocking_category = str(item.get("blocking_category", "customer_decision"))
        handoff_acceptance_plan.append(
            {
                "action_id": item["action_id"],
                "priority": item.get("priority", "P1"),
                "status": "ready" if state in {"approved", "ready"} else "open",
                "source": "final_handoff",
                "created_from": "delivery_handoff_console",
                "owner_agent_id": item["owner_agent_id"],
                "action": item["action"],
                "run_order": len(closure_plan) + order,
                "method": "REVIEW",
                "run_endpoint": item["evidence_endpoint"],
                "request_body": {},
                "requires_scope": "owner:approve",
                "runnable_now": False,
                "blocked_by": [blocking_category],
                "blocking_category": blocking_category,
                "can_close_without_customer_secret": item[
                    "can_close_without_customer_secret"
                ],
                "customer_decision_required": item["customer_decision_required"],
                "safe_next_step": item["safe_next_step"],
                "required_input": item["required_input"],
                "acceptance_impact": item["acceptance_impact"],
                "evidence_endpoint": item["evidence_endpoint"],
                "acceptance_gate": item["acceptance_gate"],
                "acceptance_evidence": item["required_input"],
                "a2a_next_hop": "project_delivery_coordinator",
                "customer_safe": True,
            }
        )
    release_action_queue = [
        {
            **item,
            "source": "release_gap",
            "created_from": "release_gate_evidence",
            "action": item["run_label"],
            "blocking_category": "runtime_auth"
            if item["blocked_by"]
            else "release_evidence",
            "can_close_without_customer_secret": True,
            "customer_decision_required": False,
            "safe_next_step": item["safe_command"],
            "required_input": item["acceptance_evidence"],
            "acceptance_impact": "improves_runtime_readiness",
            "evidence_endpoint": item["run_endpoint"],
        }
        for item in open_items
    ]
    action_queue = release_action_queue + handoff_acceptance_plan
    status = (
        "ready"
        if release["status"] == "ready"
        else "ready_to_run" if runnable_now else auth_state
    )
    return {
        "status": status,
        "version": __version__,
        "prepared_for": CUSTOMER_NAME,
        "prepared_by": CONTRACTOR_NAME,
        "summary": {
            "mission_status": summary["mission_status"],
            "kpi_score": summary["kpi_score"],
            "sla_target": summary["sla_target"],
            "sla_gap": summary["sla_gap"],
            "ready_gate_count": summary["gates_ready"],
            "open_gate_count": len(open_items),
            "total_gate_count": summary["gates_total"],
            "runnable_now": runnable_now,
            "auth_state": auth_state,
            "next_executable_gate": open_items[0]["gate_id"] if open_items else "none",
            "next_action": (
                "Run the full release mission, then recheck drift control and release evidence."
                if open_items and runnable_now
                else (
                    handoff["next_action"]
                    if handoff_acceptance_plan
                    else "Configure an operator token file, token env, or OIDC operator/admin identity before running release evidence actions."
                )
            ),
            "handoff_action_count": len(handoff_acceptance_plan),
            "customer_decision_required": handoff["action_summary"][
                "customer_decision_required"
            ],
            "secret_free_close_count": handoff["action_summary"][
                "secret_free_close_count"
            ],
            "engineering_closeable_action_count": handoff["action_summary"][
                "engineering_closeable_action_count"
            ],
            "final_acceptance_status": handoff["status"],
        },
        "auth_gate": {
            "status": auth_state,
            "required_scope": "agent:run",
            "operator_token_configured": token_configured,
            "operator_token_strength": configured_operator_token_strength(),
            "identity_provider_configured": identity_configured,
            "runnable_now": runnable_now,
            "required_runtime_setup": ["Configure a strong operator token or OIDC bearer role with agent:run."] if not runnable_now else [],
            "credential_values_returned": False,
        },
        "gate_closure_plan": closure_plan,
        "handoff_acceptance_plan": handoff_acceptance_plan,
        "action_queue": action_queue,
        "execution_sequence": [
            {"step": 1, "label": "Configure run identity", "status": "ready" if runnable_now else "blocked", "owner_agent_id": "admin_governance_agent", "evidence_endpoint": "/readyz", "operator_note": "Use a runtime token or OIDC bearer. Do not store token values in project files."},
            {"step": 2, "label": "Run full release mission", "status": "ready_to_run" if runnable_now else "waiting_for_auth", "owner_agent_id": "project_delivery_coordinator", "method": "POST", "evidence_endpoint": "/api/release/mission/run", "safe_command": "POST /api/release/mission/run with X-Operator-Token: <runtime-token>."},
            {"step": 3, "label": "Recheck KPI/SLA drift", "status": "waiting_for_mission" if open_items else "ready", "owner_agent_id": "release_compliance_controller", "method": "GET", "evidence_endpoint": "/api/project/drift-control", "acceptance_gate": "Release block clears only when the release KPI reaches the 99.99 SLA target."},
            {"step": 4, "label": "Resolve final handoff actions", "status": "owner_review_required" if handoff_acceptance_plan else "ready", "owner_agent_id": "project_delivery_coordinator", "method": "REVIEW", "evidence_endpoint": "/api/delivery/handoff-console", "acceptance_gate": "Final acceptance requires owner/customer evidence without secrets."},
        ],
        "charts": [
            {"chart_id": "release-gap-closure-readiness", "title": "Release Gap Closure Readiness", "type": "bar", "unit": "gates", "series": [{"label": "Ready", "value": summary["gates_ready"]}, {"label": "Open", "value": len(open_items)}, {"label": "Runnable", "value": len([item for item in open_items if item["runnable_now"]])}]},
            {"chart_id": "release-gap-score-debt", "title": "Release Gate Score Debt", "type": "bar", "unit": "score_gap", "series": [{"label": item["label"], "value": item["score_gap"]} for item in closure_plan]},
            {"chart_id": "release-handoff-acceptance-actions", "title": "Final Handoff Acceptance Actions", "type": "bar", "unit": "actions", "series": [{"label": category, "value": sum(1 for item in handoff_acceptance_plan if item["blocking_category"] == category)} for category in sorted({item["blocking_category"] for item in handoff_acceptance_plan})]},
        ],
        "evidence_links": [
            {"label": "Gap closure", "endpoint": "/api/release/gap-closure-console"},
            {"label": "Release mission", "endpoint": "/api/release/mission"},
            {"label": "Release evidence", "endpoint": "/api/release/evidence-console"},
            {"label": "Final handoff", "endpoint": "/api/delivery/handoff-console"},
            {"label": "AI evaluations", "endpoint": "/api/ai/evaluations/runs"},
            {"label": "Agent autopilot", "endpoint": "/api/agents/autopilot/run"},
            {"label": "Continuous QA", "endpoint": "/api/qa/continuous-mission"},
            {"label": "Drift control", "endpoint": "/api/project/drift-control"},
        ],
        "privacy": {"customer_safe": "true", "raw_prompts_returned": "false", "provider_payload_storage": "not_stored", "credential_values_returned": "false", "local_path_storage": "not_stored"},
    }


def release_agent_autopilot_score(autopilot_summary: dict[str, Any]) -> int:
    """Return coverage score for the current section-agent autopilot mission."""

    runs_created = int(autopilot_summary.get("runs_created", 0) or 0)
    selected_agents = int(autopilot_summary.get("selected_agents", 0) or 0)
    expected_agents = int(autopilot_summary.get("expected_agents", 0) or 0)
    target_agents = max(1, selected_agents or expected_agents)
    return min(100, round((runs_created / target_agents) * 100))


def build_release_mission_gates(
    ai_eval: dict[str, Any],
    assistant_qa: dict[str, Any],
    autopilot: dict[str, Any],
    continuous_qa: dict[str, Any],
) -> list[dict[str, Any]]:
    """Build the four mandatory release mission quality gates."""

    autopilot_summary = autopilot.get("summary", {})
    return [
        {
            "gate_id": "baseline-ai-eval",
            "label": "Baseline AI evaluation",
            "status": release_mission_gate_status(bool(ai_eval.get("passed"))),
            "score": int(ai_eval.get("score", 0) or 0),
            "evidence": ai_eval.get("run_id", "Run the baseline AI evaluation."),
        },
        {
            "gate_id": "assistant-qa-challenge",
            "label": "Assistant answer-quality review",
            "status": release_mission_gate_status(
                bool(assistant_qa.get("passed"))
                and int(assistant_qa.get("provider_calls", 0) or 0) == 0
            ),
            "score": int(assistant_qa.get("score", 0) or 0),
            "evidence": (
                f"{int(assistant_qa.get('case_count', 0) or 0)} hash-only case(s), "
                f"{int(assistant_qa.get('provider_calls', 0) or 0)} provider call(s)."
            ),
        },
        {
            "gate_id": "agent-autopilot",
            "label": "Agent autopilot",
            "status": release_mission_gate_status(
                int(autopilot_summary.get("runs_created", 0) or 0) >= 1
            ),
            "score": release_agent_autopilot_score(autopilot_summary),
            "evidence": (
                f"{int(autopilot_summary.get('runs_created', 0) or 0)} run(s), "
                f"{int(autopilot_summary.get('a2a_trace_steps', 0) or 0)} A2A step(s), "
                f"target {int((autopilot_summary.get('selected_agents') or autopilot_summary.get('expected_agents') or 0))} agent(s)."
            ),
        },
        {
            "gate_id": "continuous-qa-mission",
            "label": "Continuous QA mission",
            "status": release_mission_gate_status(continuous_qa.get("status") == "completed"),
            "score": int(continuous_qa.get("coverage_score", 0) or 0),
            "evidence": (
                f"{int(continuous_qa.get('question_rounds', 0) or 0)} question round(s), "
                f"{int(continuous_qa.get('closed_loop', {}).get('findings_recorded', 0) or 0)} finding(s)."
            ),
        },
    ]


def release_mission_charts(
    gates: list[dict[str, Any]], summary: dict[str, Any]
) -> list[dict[str, Any]]:
    """Return compact charts for the release mission dashboard."""

    return [
        {
            "chart_id": "release-mission-gates",
            "title": "Release Mission Gates",
            "type": "bar",
            "unit": "score",
            "series": [
                {"label": gate["label"], "value": gate["score"]}
                for gate in gates
            ],
        },
        {
            "chart_id": "release-mission-evidence",
            "title": "Release Mission Evidence",
            "type": "bar",
            "unit": "records",
            "series": [
                {"label": "Ready gates", "value": summary["gates_passed"]},
                {"label": "Agent runs", "value": summary["agent_runs"]},
                {"label": "Assistant rounds", "value": summary["assistant_rounds"]},
                {"label": "Provider calls", "value": summary["provider_calls"]},
            ],
        },
        {
            "chart_id": "release-mission-sla",
            "title": "Release Mission SLA",
            "type": "bar",
            "unit": "percent",
            "series": [
                {"label": "Actual", "value": summary["kpi_score"]},
                {"label": "Target", "value": summary["sla_target"]},
                {"label": "Gap", "value": summary["sla_gap"]},
            ],
        },
        release_mission_remediation_chart(
            release_mission_remediation_plan(
                summary,
                gates,
                {
                    "target_success_rate": summary["sla_target"],
                    "actual_success_rate": summary["kpi_score"],
                    "gap": summary["sla_gap"],
                },
            )
        ),
    ]


def release_decision_score_input(
    gates: list[dict[str, Any]],
    ai_eval: dict[str, Any],
    assistant_qa: dict[str, Any],
    decision_brief: dict[str, Any],
) -> dict[str, Any]:
    """Separate release gate readiness from live operational risk scoring."""

    operational_score = float(
        decision_brief.get("summary", {}).get("decision_readiness_score", 0) or 0
    )
    provider_calls = int(ai_eval.get("provider_calls", 0) or 0) + int(
        assistant_qa.get("provider_calls", 0) or 0
    )
    qa_evidence_ready = bool(
        decision_brief.get("summary", {}).get("qa_evidence_ready")
    )
    release_ready = (
        all(gate["status"] == "ready" for gate in gates)
        and qa_evidence_ready
        and provider_calls == 0
    )
    score = 100 if release_ready else int(operational_score)
    return {
        "component_id": "assistant-decision-readiness",
        "label": "Assistant release decision readiness",
        "score": score,
        "operational_decision_score": round(operational_score, 1),
        "status": "ready" if score >= 99 else "review_required",
        "source_endpoint": "/api/assistant/decision-brief",
        "evidence_state": (
            "Release QA gates ready; operational decision score retained separately."
            if release_ready
            else "Operational decision readiness from grounded assistant brief."
        ),
        "score_basis": (
            "release_quality_gates_ready"
            if release_ready
            else "operational_decision_readiness"
        ),
        "provider_calls": provider_calls,
        "qa_evidence_ready": qa_evidence_ready,
    }


def release_mission_summary(
    gates: list[dict[str, Any]],
    ai_eval: dict[str, Any],
    assistant_qa: dict[str, Any],
    autopilot: dict[str, Any],
    continuous_qa: dict[str, Any],
    decision_brief: dict[str, Any],
    requested_assistant_rounds: int | None = None,
) -> dict[str, Any]:
    """Summarize release mission execution without exposing prompts."""

    autopilot_summary = autopilot.get("summary", {})
    gates_passed = sum(1 for gate in gates if gate["status"] == "ready")
    assistant_rounds = int(assistant_qa.get("case_count", 0) or 0)
    requested_rounds = int(requested_assistant_rounds or assistant_rounds)
    score_inputs = [
        {
            "component_id": "baseline-ai-eval",
            "label": "Baseline AI evaluation",
            "score": int(ai_eval.get("score", 0) or 0),
            "status": gates[0]["status"],
            "source_endpoint": "/api/ai/evaluations/runs",
            "evidence_state": gates[0]["evidence"],
        },
        {
            "component_id": "assistant-qa-challenge",
            "label": "Assistant answer-quality review",
            "score": int(assistant_qa.get("score", 0) or 0),
            "status": gates[1]["status"],
            "source_endpoint": "/api/ai/evaluations/runs",
            "evidence_state": gates[1]["evidence"],
        },
        {
            "component_id": "continuous-qa-mission",
            "label": "Continuous QA mission",
            "score": int(continuous_qa.get("coverage_score", 0) or 0),
            "status": gates[3]["status"],
            "source_endpoint": "/api/qa/continuous-mission",
            "evidence_state": gates[3]["evidence"],
        },
        release_decision_score_input(gates, ai_eval, assistant_qa, decision_brief),
    ]
    kpi_score = round(
        sum(item["score"] for item in score_inputs) / max(1, len(score_inputs)),
        1,
    )
    sla_target = 99.99
    sla_gap = round(max(0.0, sla_target - kpi_score), 2)
    return {
        "gates_total": len(gates),
        "gates_passed": gates_passed,
        "assistant_rounds": assistant_rounds,
        "requested_assistant_rounds": requested_rounds,
        "assistant_minimum_rounds": RELEASE_ASSISTANT_QA_MIN_ROUNDS,
        "assistant_round_policy": (
            "release_minimum_enforced"
            if assistant_rounds > requested_rounds
            else "release_minimum_satisfied"
        ),
        "provider_calls": int(ai_eval.get("provider_calls", 0) or 0)
        + int(assistant_qa.get("provider_calls", 0) or 0),
        "agent_runs": int(autopilot_summary.get("runs_created", 0) or 0),
        "a2a_steps": int(autopilot_summary.get("a2a_trace_steps", 0) or 0),
        "qa_findings": int(
            continuous_qa.get("closed_loop", {}).get("findings_recorded", 0) or 0
        ),
        "kpi_score": kpi_score,
        "sla_target": sla_target,
        "sla_gap": sla_gap,
        "sla_state": "ready" if sla_gap == 0 else "review_required",
        "score_inputs": score_inputs,
        "blocking_gates": [
            {
                "gate_id": gate["gate_id"],
                "label": gate["label"],
                "status": gate["status"],
                "score": gate["score"],
                "source_endpoint": release_evidence_gate_endpoint(gate["gate_id"]),
                "evidence_state": gate["evidence"],
            }
            for gate in gates
            if gate["status"] != "ready"
        ],
    }


def latest_ai_eval_by_label(
    eval_runs: list[dict[str, Any]], label: str
) -> dict[str, Any]:
    """Return the latest evaluation run matching a benchmark label."""

    return next(
        (run for run in reversed(eval_runs) if run.get("benchmark_label") == label),
        {},
    )


def release_requested_rounds_from_evidence(
    evidence: str, default_rounds: int
) -> int:
    """Read the operator-requested assistant rounds from stored release evidence."""

    match = re.search(r"requested\s+(\d+)\s+assistant round", evidence.lower())
    if not match:
        return default_rounds
    return max(0, int(match.group(1)))


def release_mission_evidence_version(evidence: str) -> str:
    """Return the release version recorded in release-mission evidence."""

    match = re.search(r"\brelease_version=([0-9]+\.[0-9]+\.[0-9]+)\b", evidence)
    return match.group(1) if match else "unknown"


def release_mission_evidence_is_current(evidence: str) -> bool:
    """Return whether release-mission evidence belongs to the running version."""

    return release_mission_evidence_version(evidence) == __version__


def release_mission_public_label(
    latest: dict[str, Any] | None, evidence_current: bool
) -> str:
    """Return a customer-safe release mission label without operator text."""

    if not latest:
        return "No release mission run stored yet"
    if not evidence_current:
        return "Stale release mission evidence"
    return f"Release mission {__version__}"


def latest_release_mission_status(
    store: CoreStore, production: bool
) -> dict[str, Any]:
    """Return the latest release mission status, or a waiting state."""

    findings = [
        item
        for item in store.list_evidence_findings()
        if item["source"] == "release_mission"
    ]
    latest = findings[0] if findings else None
    latest_evidence = str(latest.get("evidence", "")) if latest else ""
    evidence_version = (
        release_mission_evidence_version(latest_evidence) if latest else "not-run"
    )
    evidence_current = bool(
        latest and release_mission_evidence_is_current(latest_evidence)
    )
    eval_runs = store.list_ai_eval_runs()
    ai_eval = latest_ai_eval_by_label(eval_runs, "baseline_ai_eval")
    assistant_qa = latest_ai_eval_by_label(eval_runs, "assistant_qa_60")
    autopilot_summary = autopilot_mission_summary(store.list_agent_runs())
    autopilot = {"status": autopilot_summary["status"], "summary": autopilot_summary}
    continuous_qa = latest_continuous_qa_mission(store, production)
    closed_loop_session = {
        "status": (
            "waiting_for_release_mission"
            if not latest
            else (
                "recorded_in_release_run"
                if evidence_current
                else "stale_release_run"
            )
        ),
        "session_id": latest["subject_id"] if latest else "not-run",
        "raw_prompt_stored": False,
        "answer_text_stored": False,
        "provider_call": "not_performed",
        "evidence_endpoint": "/api/assistant/sessions",
    }
    decision_brief = assistant_decision_brief(store, production)
    gates = build_release_mission_gates(
        ai_eval, assistant_qa, autopilot, continuous_qa
    )
    summary = release_mission_summary(
        gates, ai_eval, assistant_qa, autopilot, continuous_qa, decision_brief
    )
    if latest:
        requested_rounds = release_requested_rounds_from_evidence(
            str(latest.get("evidence", "")),
            int(summary.get("assistant_rounds", 0) or 0),
        )
        summary["requested_assistant_rounds"] = requested_rounds
        summary["assistant_round_policy"] = (
            "release_minimum_enforced"
            if int(summary.get("assistant_rounds", 0) or 0) > requested_rounds
            else "release_minimum_satisfied"
        )
    sla = release_mission_sla(summary)
    remediation_plan = release_mission_remediation_plan(summary, gates, sla)
    status = latest["outcome"] if latest else "waiting_for_run"
    if latest and not evidence_current:
        status = "stale_evidence"
    elif status == "completed" and not sla["passed"]:
        status = "review_required"
    return {
        "status": status,
        "version": __version__,
        "prepared_for": CUSTOMER_NAME,
        "prepared_by": CONTRACTOR_NAME,
        "mission_id": latest["subject_id"] if latest else "not-run",
        "mission_label": release_mission_public_label(latest, evidence_current),
        "evidence_version": evidence_version,
        "evidence_current": evidence_current,
        "created_at": latest["created_at"] if latest else utc_now(),
        "summary": summary,
        "gates": gates,
        "charts": release_mission_charts(gates, summary),
        "ai_eval": ai_eval,
        "assistant_qa": assistant_qa,
        "closed_loop_session": closed_loop_session,
        "agent_autopilot": autopilot,
        "continuous_qa": continuous_qa,
        "decision_brief": decision_brief,
        "sla": sla,
        "remediation_plan": remediation_plan,
        "evidence_links": release_mission_evidence_links(),
        "privacy": release_mission_privacy(),
    }


def record_release_mission_session_evidence(
    store: CoreStore,
    *,
    mission_id: str,
    actor: str,
) -> dict[str, Any]:
    """Record input-redacted assistant continuity evidence for release missions."""

    message = "Review release evidence and closed-loop readiness."
    client_message_id = f"{mission_id}-closed-loop"
    started_at = time.perf_counter()
    response = grounded_diagnosis(
        store,
        message,
        actor=actor,
        allow_provider_runtime=False,
    )
    latency_ms = round((time.perf_counter() - started_at) * 1000)
    response.answer_review = assistant_answer_review(response, message)
    response.coworker_package = assistant_coworker_package(
        store, message, response, latency_ms
    )
    interaction = store.add_assistant_interaction(
        message=message,
        response=response,
        actor=actor,
        latency_ms=latency_ms,
        requested_session_id=mission_id,
        client_message_id=client_message_id,
    )
    session = assistant_session_state(
        message=message,
        requested_session_id=mission_id,
        client_message_id=client_message_id,
        parent_message_id=None,
        response=response,
        interaction=interaction,
        latency_ms=latency_ms,
    )
    return {
        "status": "recorded",
        "session_id": str(session["session_id"]),
        "message_id": str(session["message_id"]),
        "interaction_id": str(interaction["interaction_id"]),
        "prompt_hash": str(interaction["prompt_hash"]),
        "raw_prompt_stored": False,
        "answer_text_stored": False,
        "provider_call": "not_performed",
        "evidence_endpoint": "/api/assistant/sessions",
    }


def run_release_mission(
    store: CoreStore,
    request: ReleaseMissionRequest,
    *,
    actor: str,
    production: bool,
) -> dict[str, Any]:
    """Run all release quality agents under one operator-gated command."""

    mission_id = f"release-mission-{int(time.time() * 1000)}-{secrets.token_hex(3)}"
    created_at = utc_now()
    ai_eval = run_ai_eval_suite(store, actor=actor, production=production)
    assistant_rounds = max(RELEASE_ASSISTANT_QA_MIN_ROUNDS, request.assistant_rounds)
    assistant_qa = run_assistant_qa_challenge(
        store,
        actor=actor,
        production=production,
        rounds=assistant_rounds,
    )
    autopilot = run_agent_autopilot_mission(
        store,
        AgentAutopilotRequest(
            mission_label=request.mission_label,
            include_disabled=request.include_disabled_agents,
        ),
        actor=actor,
        production=production,
    )
    continuous_qa = record_continuous_qa_mission(
        store,
        production,
        ContinuousQAMissionRequest(
            duration_minutes=60,
            question_rounds=assistant_rounds,
        ),
        actor=actor,
    )
    closed_loop_session = record_release_mission_session_evidence(
        store,
        mission_id=mission_id,
        actor=actor,
    )
    decision_brief = assistant_decision_brief(store, production)
    gates = build_release_mission_gates(
        ai_eval, assistant_qa, autopilot, continuous_qa
    )
    summary = release_mission_summary(
        gates,
        ai_eval,
        assistant_qa,
        autopilot,
        continuous_qa,
        decision_brief,
        requested_assistant_rounds=request.assistant_rounds,
    )
    sla = release_mission_sla(summary)
    remediation_plan = release_mission_remediation_plan(summary, gates, sla)
    status = (
        "completed"
        if summary["gates_passed"] == summary["gates_total"] and sla["passed"]
        else "review_required"
    )
    store.add_evidence_finding(
        source="release_mission",
        subject_id=mission_id,
        outcome=status,
        severity="info" if status == "completed" else "review_required",
        evidence=(
            f"{request.mission_label}: {summary['gates_passed']}/"
            f"{summary['gates_total']} gates ready, "
            f"release_version={__version__}, "
            f"source_commit={source_commit_id()}, "
            f"requested {summary['requested_assistant_rounds']} assistant rounds, "
            f"ran {summary['assistant_rounds']} assistant rounds, "
            f"{summary['agent_runs']} agent runs, "
            f"SLA gap {summary['sla_gap']}%."
        ),
        lesson="Run release mission after AI, agent, UI, or delivery changes before customer review.",
    )
    store.add_audit_event(
        event_type="release.mission.completed",
        subject_id=mission_id,
        actor=actor,
        detail=json.dumps(
            {
                "status": status,
                "gates_passed": summary["gates_passed"],
                "assistant_rounds": summary["assistant_rounds"],
                "agent_runs": summary["agent_runs"],
                "sla_gap": summary["sla_gap"],
            },
            separators=(",", ":"),
        ),
    )
    return {
        "status": status,
        "version": __version__,
        "prepared_for": CUSTOMER_NAME,
        "prepared_by": CONTRACTOR_NAME,
        "mission_id": mission_id,
        "mission_label": request.mission_label,
        "created_at": created_at,
        "summary": summary,
        "gates": gates,
        "charts": release_mission_charts(gates, summary),
        "ai_eval": ai_eval,
        "assistant_qa": assistant_qa,
        "closed_loop_session": closed_loop_session,
        "agent_autopilot": autopilot,
        "continuous_qa": continuous_qa,
        "decision_brief": decision_brief,
        "sla": sla,
        "remediation_plan": remediation_plan,
        "evidence_links": release_mission_evidence_links(),
        "privacy": release_mission_privacy(),
    }


def command_center_readiness_chart(
    *,
    summary: dict[str, Any],
    agents: list[dict[str, Any]],
    rag_base: dict[str, Any],
    ux_quality: dict[str, Any],
) -> dict[str, Any]:
    """Build a compact score chart for the operational command center."""

    enabled_agents = sum(1 for agent in agents if agent["enabled"])
    agent_score = round(enabled_agents / max(1, len(agents)) * 100)
    rag_score = min(100, rag_base["metrics"]["document_count"] * 20)
    recovery_score = 0 if summary["counters"]["pending_recovery"] else 100
    return {
        "chart_id": "command-center-readiness",
        "title": "Command Center Readiness",
        "type": "bar",
        "unit": "score",
        "series": [
            {
                "label": "Operations",
                "value": summary["phase_readiness_score"],
            },
            {"label": "Agents", "value": agent_score},
            {"label": "UI/UX", "value": ux_quality["score"]},
            {"label": "Knowledge", "value": rag_score},
            {"label": "Recovery gate", "value": recovery_score},
        ],
    }


def operation_command_center(store: CoreStore, production: bool) -> dict[str, Any]:
    """Return menu-owned operational actions instead of long static reports."""

    summary = operation_summary(store, production)
    agents = store.list_dashboard_agents()
    agent_reports = agent_section_reports(store, production)["items"]
    registry = agent_orchestration_registry(store)
    access = access_policy(store)
    ai_route = ai_routing_status(store)
    rag_base = rag_knowledge_base(store)
    ux_quality = ui_ux_quality_gate()
    chart = command_center_readiness_chart(
        summary=summary,
        agents=agents,
        rag_base=rag_base,
        ux_quality=ux_quality,
    )
    report_by_agent = {item["agent_id"]: item for item in agent_reports}

    def report_value(agent_id: str, key: str, fallback: Any) -> Any:
        return report_by_agent.get(agent_id, {}).get(key, fallback)

    def card(
        *,
        area: str,
        agent_id: str,
        kpi: str,
        primary_endpoint: str,
        action_label: str,
        evidence: str,
    ) -> dict[str, Any]:
        readiness = report_value(agent_id, "readiness", "review_required")
        blocked_by = "none" if readiness in {"ready", "monitoring_active"} else readiness
        return {
            "area": area,
            "agent_id": agent_id,
            "agent": report_value(agent_id, "display_name", agent_id),
            "state": readiness,
            "kpi": kpi,
            "next_action": report_value(
                agent_id,
                "next_action",
                summary["next_actions"][0],
            ),
            "primary_endpoint": primary_endpoint,
            "evidence": evidence,
            "blocked_by": blocked_by,
            "action_label": action_label,
        }

    counters = summary["counters"]
    command_cards = [
        card(
            area="Operations command",
            agent_id="operations_coordinator",
            kpi=f"{summary['phase_readiness_score']}% readiness",
            primary_endpoint="/api/operations/summary",
            action_label="Review next operator action",
            evidence=summary["operational_state"].replace("_", " "),
        ),
        card(
            area="Device fleet",
            agent_id="device_fleet_agent",
            kpi=f"{counters['devices']} device(s), {counters['config_profiles']} profile(s)",
            primary_endpoint="/api/devices",
            action_label="Validate device and profile coverage",
            evidence="/api/config/profiles",
        ),
        card(
            area="Alert and recovery",
            agent_id="alert_recovery_agent",
            kpi=f"{counters['open_alerts']} open alert(s), {counters['pending_recovery']} pending",
            primary_endpoint="/api/recovery/proposals",
            action_label="Triage recovery approvals",
            evidence="/api/alerts",
        ),
        card(
            area="Assistant and RAG",
            agent_id="ai_diagnosis_agent",
            kpi=ai_route["active_route"],
            primary_endpoint="/api/chat",
            action_label="Check grounded assistant route",
            evidence="/api/rag/search",
        ),
        card(
            area="Reports and delivery",
            agent_id="reporting_compliance_agent",
            kpi="16 chart(s)",
            primary_endpoint="/api/reports/dashboard",
            action_label="Refresh acceptance evidence",
            evidence="/api/delivery/evidence-pack",
        ),
        card(
            area="UI/UX quality",
            agent_id="ui_ux_experience_auditor",
            kpi=f"{ux_quality['score']}% score",
            primary_endpoint="/api/ui/quality-gate",
            action_label="Audit menu and visual quality",
            evidence=f"{ux_quality['metrics']['raw_json_menu_links']} raw service menu link(s)",
        ),
        card(
            area="Access governance",
            agent_id="admin_governance_agent",
            kpi=f"{len(access['roles'])} role(s)",
            primary_endpoint="/api/access/policy",
            action_label="Review roles and admin scopes",
            evidence="/api/admin/access/users",
        ),
    ]

    return {
        "status": "ok",
        "version": __version__,
        "prepared_for": CUSTOMER_NAME,
        "prepared_by": CONTRACTOR_NAME,
        "summary": {
            "operational_state": summary["operational_state"],
            "phase_readiness_score": summary["phase_readiness_score"],
            "active_risk": summary["current_risk"]["label"],
            "next_action": summary["next_actions"][0],
            "open_alerts": counters["open_alerts"],
            "pending_recovery": counters["pending_recovery"],
            "enabled_agents": sum(1 for agent in agents if agent["enabled"]),
        },
        "kpis": [
            {
                "kpi_id": "operations-readiness",
                "label": "Operations readiness",
                "value": summary["phase_readiness_score"],
                "unit": "%",
                "state": summary["operational_state"],
                "evidence": "/api/operations/summary",
            },
            {
                "kpi_id": "agent-readiness",
                "label": "Agent readiness",
                "value": sum(1 for agent in agents if agent["enabled"]),
                "unit": "enabled agents",
                "state": "ready",
                "evidence": "/api/agents/section-reports",
            },
            {
                "kpi_id": "ui-ux-quality",
                "label": "UI/UX quality",
                "value": ux_quality["score"],
                "unit": "%",
                "state": "ready" if ux_quality["score"] >= 90 else "review_required",
                "evidence": "/api/ui/quality-gate",
            },
            {
                "kpi_id": "rag-knowledge",
                "label": "RAG knowledge",
                "value": rag_base["metrics"]["document_count"],
                "unit": "documents",
                "state": "ready",
                "evidence": "/api/rag/knowledge-base",
            },
            {
                "kpi_id": "pending-recovery",
                "label": "Pending recovery",
                "value": counters["pending_recovery"],
                "unit": "proposal(s)",
                "state": "operator_action_required"
                if counters["pending_recovery"]
                else "clear",
                "evidence": "/api/recovery/proposals",
            },
        ],
        "command_cards": command_cards,
        "agent_routes": registry["edges"],
        "charts": [chart],
    }


def agent_section_reports(store: CoreStore, production: bool) -> dict[str, Any]:
    """Return per-agent operating reports with evidence and next actions."""

    agents = store.list_dashboard_agents()
    runs = store.list_agent_runs()
    summary = operation_summary(store, production)
    charts = [{"chart_id": "dashboard-report"}] * 16
    access = access_policy(store)
    final_package = final_delivery_package()
    ai_route = ai_routing_status(store)
    eval_runs = store.list_ai_eval_runs()
    ux_quality = ui_ux_quality_gate()
    devices = store.list_rows("devices")
    config_profiles = store.list_rows("config_profiles")
    alerts = store.list_rows("alerts")
    proposals = store.list_rows("recovery_proposals")
    audit_events = store.list_rows("audit_events")

    latest_run_by_agent: dict[str, dict[str, Any]] = {}
    for run in runs:
        latest_run_by_agent[run["primary_agent_id"]] = run

    def report_for(agent: dict[str, Any]) -> dict[str, Any]:
        agent_id = agent["agent_id"]
        if not agent["enabled"]:
            readiness = "disabled"
            next_action = "Enable the agent before assigning operational work."
            records = {"enabled": 0}
        elif agent_id == "operations_coordinator":
            readiness = summary["operational_state"]
            next_action = summary["next_actions"][0]
            records = summary["counters"]
        elif agent_id == "device_fleet_agent":
            readiness = "ready" if devices and config_profiles else "waiting_for_device_context"
            next_action = (
                "Validate device registration, configuration profile, firmware, and broker readiness."
            )
            records = {
                "devices": len(devices),
                "config_profiles": len(config_profiles),
                "mqtt_devices": sum(1 for item in devices if item["adapter"] == "mqtt"),
            }
        elif agent_id == "alert_recovery_agent":
            pending = sum(1 for item in proposals if item["status"] != "approved")
            open_alerts = sum(1 for item in alerts if item["status"] == "open")
            readiness = "operator_action_required" if pending or open_alerts else "ready"
            next_action = "Review open alerts and approve recovery only after physical checks."
            records = {
                "open_alerts": open_alerts,
                "pending_recovery": pending,
                "audit_events": len(audit_events),
            }
        elif agent_id == "ai_diagnosis_agent":
            readiness = "ready" if eval_runs else "waiting_for_eval_run"
            next_action = "Keep answers grounded and run evaluation before production model claims."
            records = {
                "active_route": ai_route["active_route"],
                "eval_runs": len(eval_runs),
                "runtime_allowed": int(ai_route["runtime_allowed"]),
            }
        elif agent_id == "reporting_compliance_agent":
            readiness = "ready" if charts else "waiting_for_reports"
            next_action = "Keep customer-safe reports, charts, release manifest, and license evidence current."
            records = {
                "charts": len(charts),
                "reports": 7,
                "open_delivery_gates": len(final_package["open_gates"]),
            }
        elif agent_id == "ui_ux_experience_auditor":
            readiness = "ready" if ux_quality["score"] >= 90 and charts and agents else "review_required"
            next_action = "Verify menus use dashboard section anchors, charts render visually, and no primary menu opens raw service."
            records = {
                "navigation_mode": "dashboard_section_anchors",
                "raw_json_menu_links": ux_quality["metrics"]["raw_json_menu_links"],
                "quality_score": ux_quality["score"],
                "charts": len(charts),
                "agent_map_nodes": len(agents),
            }
        else:
            readiness = (
                "ready"
                if access["identity_provider"]["state"] == "configured"
                else "customer_action_required"
            )
            next_action = "Maintain role scopes, admin controls, owner decisions, and A2A governance gates."
            records = {
                "roles": len(access["roles"]),
                "identity_provider_configured": int(
                    access["identity_provider"]["state"] == "configured"
                ),
                "owner_decisions": len(production_approval_package(store, production)["decision_items"]),
            }
        latest_run = latest_run_by_agent.get(agent_id)
        return {
            "agent_id": agent_id,
            "display_name": agent["display_name"],
            "section": agent["section"],
            "mode": agent["mode"],
            "enabled": agent["enabled"],
            "readiness": readiness,
            "runtime_records": records,
            "managed_endpoints": agent["tools"],
            "evidence_links": [
                {"label": "Primary tool", "endpoint": agent["tools"][0]},
                {"label": "Agent registry", "endpoint": "/api/admin/agents"},
                {"label": "Dashboard reports", "endpoint": "/api/reports/dashboard"},
            ],
            "connected_agents": agent["connected_agents"],
            "latest_run_id": latest_run["run_id"] if latest_run else None,
            "latest_run_at": latest_run["created_at"] if latest_run else None,
            "next_action": next_action,
            "quality_gate": "human_approval_required"
            if agent["a2a_card"]["approval_required"]
            else "evidence_grounded",
        }

    return {
        "status": "ok",
        "version": __version__,
        "prepared_for": CUSTOMER_NAME,
        "prepared_by": CONTRACTOR_NAME,
        "items": [report_for(agent) for agent in agents],
    }


