def evidence_action_board(store: CoreStore, production: bool) -> dict[str, Any]:
    """Convert closed-loop evidence and QA gaps into owner-assigned actions."""

    findings = store.list_evidence_findings()
    review_findings = [
        item for item in findings if item.get("source") == "evidence_action_review"
    ]
    reviewed_action_keys: dict[str, int] = {}
    for item in review_findings:
        subject_id = str(item.get("subject_id") or "")
        if subject_id:
            reviewed_action_keys[subject_id] = reviewed_action_keys.get(subject_id, 0) + 1
    action_findings = [
        item for item in findings if item.get("source") != "evidence_action_review"
    ]
    qa_report = qa_evidence_report(store, production)
    agent_runs = store.list_agent_runs()
    owner_by_source = {
        "assistant_chat": "ai_diagnosis_agent",
        "agent_task": "operations_coordinator",
        "qa_challenge": "ui_ux_experience_auditor",
        "continuous_qa_mission": "reporting_compliance_agent",
        "ai_eval": "ai_diagnosis_agent",
        "release_mission": "admin_governance_agent",
    }
    priority_by_severity = {
        "critical": "P0",
        "review_required": "P1",
        "warning": "P1",
        "report": "P2",
        "info": "P3",
    }
    actions: list[dict[str, Any]] = []
    for index, finding in enumerate(action_findings[:12], start=1):
        source = finding.get("source", "evidence")
        severity = finding.get("severity", "info")
        owner = owner_by_source.get(source, "reporting_compliance_agent")
        priority = priority_by_severity.get(severity, "P2")
        created_from = f"evidence-ref-{index:03d}"
        actions.append(
            {
                "action_id": f"eab-{index:03d}",
                "priority": priority,
                "status": "ready" if severity == "info" else "open",
                "source": source,
                "created_from": created_from,
                "created_from_ids": [created_from],
                "occurrence_count": 1,
                "owner_agent_id": owner,
                "action": "Review evidence, apply the lesson, and update the owned dashboard gate.",
                "evidence": "Closed-loop finding is available in the Evidence workspace.",
                "lesson": "Review the finding lesson in the Evidence workspace before closing this action.",
                "evidence_endpoint": "/api/evidence/findings",
                "primary_cta": {
                    "label": "Open Findings",
                    "route": "/evidence",
                    "target": "shell-evidence-finding-body",
                },
                "acceptance_gate": "finding_lesson_reviewed_without_prompt_or_secret_leak",
                "a2a_next_hop": (
                    "admin_governance_agent"
                    if owner != "admin_governance_agent"
                    else "reporting_compliance_agent"
                ),
            }
        )
    raw_finding_actions = len(actions)
    include_qa_gaps = (
        bool(qa_report["latest_challenge"])
        or qa_report["continuous_mission"]["status"] == "completed"
        or qa_report["assistant_qa_challenge"]["status"] == "ready"
    )
    for gap in qa_report["gaps"] if include_qa_gaps else []:
        actions.append(
            {
                "action_id": f"eab-gap-{len(actions) + 1:03d}",
                "priority": "P1",
                "status": "open",
                "source": "qa_gap",
                "created_from": "qa_evidence_report",
                "created_from_ids": ["qa_evidence_report"],
                "occurrence_count": 1,
                "owner_agent_id": "ui_ux_experience_auditor",
                "action": gap,
                "evidence": "QA evidence report requires this gate before release readiness.",
                "lesson": "Run the missing bounded gate before claiming 99.99% KPI readiness.",
                "evidence_endpoint": "/api/qa/evidence-report",
                "primary_cta": {
                    "label": "Review QA Evidence",
                    "route": "/tests",
                    "target": "shell-qa-challenge-result",
                },
                "acceptance_gate": "qa_gap_closed_with_current_evidence",
                "a2a_next_hop": "reporting_compliance_agent",
            }
        )
    if not actions:
        actions.extend(
            [
                {
                    "action_id": "eab-seed-001",
                    "priority": "P2",
                    "status": "ready",
                    "source": "release_mission",
                    "created_from": "default_gate",
                    "created_from_ids": ["default_gate"],
                    "occurrence_count": 1,
                    "owner_agent_id": "admin_governance_agent",
                    "action": "Run the release mission and record acceptance evidence.",
                    "evidence": "Release gate is available for operator-controlled validation.",
                    "lesson": "Keep release evidence separate from non-customer build controls.",
                    "evidence_endpoint": "/api/release/mission",
                    "primary_cta": {
                        "label": "Open Release Mission",
                        "route": "/delivery",
                        "target": "release-mission-run-button",
                    },
                    "acceptance_gate": "release_mission_recorded",
                    "a2a_next_hop": "reporting_compliance_agent",
                },
                {
                    "action_id": "eab-seed-002",
                    "priority": "P2",
                    "status": "ready",
                    "source": "ui_quality",
                    "created_from": "default_gate",
                    "created_from_ids": ["default_gate"],
                    "occurrence_count": 1,
                    "owner_agent_id": "ui_ux_experience_auditor",
                    "action": "Review visual QA before the next delivery bundle.",
                    "evidence": "UI/UX gate tracks raw service navigation and cockpit quality.",
                    "lesson": "Visual review must happen after every frontend change.",
                    "evidence_endpoint": "/api/ui/quality-gate",
                    "primary_cta": {
                        "label": "Open UI Gate",
                        "route": "/evidence",
                        "target": "shell-evidence-workspace-card",
                    },
                    "acceptance_gate": "visual_review_passed",
                    "a2a_next_hop": "operations_coordinator",
                },
            ]
        )
    priority_order = {"P0": 0, "P1": 1, "P2": 2, "P3": 3}
    grouped_actions: dict[tuple[str, str, str, str, str, str, str, str], dict[str, Any]] = {}
    for action in actions:
        key = (
            action["priority"],
            action["status"],
            action["source"],
            action["owner_agent_id"],
            action["action"],
            action["evidence_endpoint"],
            action["acceptance_gate"],
            action["a2a_next_hop"],
        )
        action_key = "eab-" + hashlib.sha256(
            "|".join(str(part) for part in key).encode("utf-8")
        ).hexdigest()[:12]
        action["action_key"] = action_key
        if key not in grouped_actions:
            grouped_actions[key] = {**action}
            continue
        grouped = grouped_actions[key]
        grouped["occurrence_count"] += action["occurrence_count"]
        known_ids = set(grouped["created_from_ids"])
        for created_id in action["created_from_ids"]:
            if created_id not in known_ids:
                grouped["created_from_ids"].append(created_id)
                known_ids.add(created_id)
        grouped["evidence"] = (
            f"{grouped['occurrence_count']} matching evidence items are grouped "
            "for one owner review."
        )
        grouped["lesson"] = "Repeated evidence actions are grouped to keep the board operational."
    actions = list(grouped_actions.values())
    duplicate_actions_grouped = sum(item["occurrence_count"] for item in actions) - len(actions)
    for action in actions:
        review_count = reviewed_action_keys.get(action["action_key"], 0)
        action["review_state"] = "reviewed" if review_count else "pending"
        action["review_finding_count"] = review_count
        action["review_endpoint"] = f"/api/evidence/action-board/{action['action_key']}/review"
        if review_count:
            action["status"] = "ready"
            action["evidence"] = "Owner review evidence is recorded for this action."
    actions = sorted(actions, key=lambda item: (priority_order[item["priority"]], item["action_id"]))[:16]
    priorities = sorted({item["priority"] for item in actions}, key=lambda item: priority_order[item])
    statuses = sorted({item["status"] for item in actions})
    sources = sorted({item["source"] for item in actions})
    owner_agents = sorted({item["owner_agent_id"] for item in actions})
    return {
        "status": "ready" if actions else "planned",
        "version": __version__,
        "prepared_for": CUSTOMER_NAME,
        "prepared_by": CONTRACTOR_NAME,
        "summary": {
            "total_actions": len(actions),
            "open_actions": sum(1 for item in actions if item["status"] == "open"),
            "critical_actions": sum(1 for item in actions if item["priority"] == "P0"),
            "ready_actions": sum(1 for item in actions if item["status"] == "ready"),
            "reviewed_actions": sum(1 for item in actions if item.get("review_state") == "reviewed"),
            "sources": sources,
            "owner_agents": owner_agents,
            "agent_runs": len(agent_runs),
            "qa_score": qa_report["score"],
            "raw_finding_actions": raw_finding_actions,
            "grouped_action_count": len(actions),
            "duplicate_actions_grouped": duplicate_actions_grouped,
            "no_raw_prompt_storage": True,
        },
        "actions": actions,
        "charts": [
            {
                "chart_id": "evidence-action-priority",
                "title": "Evidence Action Priority",
                "type": "bar",
                "unit": "actions",
                "series": [
                    {"label": priority, "value": sum(1 for item in actions if item["priority"] == priority)}
                    for priority in priorities
                ],
            },
            {
                "chart_id": "evidence-action-status",
                "title": "Evidence Action Status",
                "type": "bar",
                "unit": "actions",
                "series": [
                    {"label": status, "value": sum(1 for item in actions if item["status"] == status)}
                    for status in statuses
                ],
            },
        ],
        "evidence_links": [
            {"label": "Action board", "endpoint": "/api/evidence/action-board"},
            {"label": "Closed-loop findings", "endpoint": "/api/evidence/findings"},
            {"label": "QA evidence", "endpoint": "/api/qa/evidence-report"},
            {"label": "Agent tasks", "endpoint": "/api/agents/tasks"},
        ],
    }


def record_evidence_action_review(
    store: CoreStore,
    production: bool,
    action_key: str,
    request: EvidenceActionReviewRequest,
    *,
    actor: str,
) -> dict[str, Any]:
    """Record a input-redacted owner review for one evidence action."""

    if not re.fullmatch(r"eab-[a-f0-9]{12}", action_key):
        raise HTTPException(status_code=404, detail="Evidence action not found")
    board = evidence_action_board(store, production)
    action = next((item for item in board["actions"] if item["action_key"] == action_key), None)
    if action is None:
        raise HTTPException(status_code=404, detail="Evidence action not found")
    audit = store.add_audit_event(
        "evidence.action.reviewed",
        action_key,
        actor,
        detail=json.dumps(
            {
                "action_key": action_key,
                "action_id": action["action_id"],
                "outcome": request.outcome,
                "acceptance_gate": action["acceptance_gate"],
                "source": action["source"],
                "raw_prompt_stored": False,
                "secret_values_stored": False,
            },
            separators=(",", ":"),
        ),
    )
    finding = store.add_evidence_finding(
        source="evidence_action_review",
        subject_id=action_key,
        outcome=request.outcome,
        severity="info",
        evidence=(
            f"Evidence action {action_key} reviewed for {action['source']} "
            f"with gate {action['acceptance_gate']}."
        ),
        lesson="Record owner action reviews as input-redacted evidence and keep repeated findings grouped.",
    )
    refreshed = evidence_action_board(store, production)
    reviewed = next(
        (item for item in refreshed["actions"] if item["action_key"] == action_key),
        {**action, "status": "ready", "review_state": "reviewed"},
    )
    return {
        "status": "recorded",
        "version": __version__,
        "prepared_for": CUSTOMER_NAME,
        "prepared_by": CONTRACTOR_NAME,
        "action": reviewed,
        "audit_event_id": audit["audit_event_id"],
        "finding_id": finding["finding_id"],
        "board_summary": refreshed["summary"],
        "privacy": {
            "raw_prompt_stored": False,
            "secret_values_stored": False,
            "contact_data_stored": False,
            "customer_delivery_safe": True,
        },
    }


