def public_chart_dto(chart: dict[str, Any]) -> dict[str, Any]:
    """Allowlist one chart shape used by customer-facing renderers."""

    return {
        "chart_id": chart["chart_id"],
        "title": chart["title"],
        "type": chart["type"],
        "unit": chart["unit"],
        "series": [
            {"label": point["label"], "value": point["value"]}
            for point in chart.get("series", [])[:12]
        ],
    }


def public_run_markers(items: list[dict[str, Any]]) -> list[dict[str, str]]:
    """Preserve UI run counts without returning IDs, inputs, routes, or traces."""

    return [
        {"status": str(item.get("status") or item.get("outcome") or "recorded")}
        for item in items[-10:]
    ]


def public_dashboard_report_package(package: dict[str, Any]) -> dict[str, Any]:
    """Build the explicit customer-facing dashboard reports DTO."""

    autopilot = package.get("autopilot_mission", {}).get("summary", {})
    return {
        "status": package["status"],
        "version": package["version"],
        "prepared_for": package["prepared_for"],
        "prepared_by": package["prepared_by"],
        "charts": [
            public_chart_dto(chart)
            for chart in package.get("charts", [])
            if chart.get("chart_id") in PUBLIC_DASHBOARD_CHART_IDS
        ][:16],
        "reports": [
            {
                "report_id": report["report_id"],
                "status": report["status"],
                "evidence": report["evidence"],
            }
            for report in package.get("reports", [])
            if report.get("report_id") in PUBLIC_DASHBOARD_REPORT_IDS
        ][:16],
        "agent_runs": public_run_markers(package.get("agent_runs", [])),
        "ai_eval_runs": public_run_markers(package.get("ai_eval_runs", [])),
        "autopilot_mission": {
            "summary": {
                "status": str(autopilot.get("status") or "waiting_for_run"),
                "runs_created": max(0, int(autopilot.get("runs_created") or 0)),
                "approval_required_runs": max(
                    0, int(autopilot.get("approval_required_runs") or 0)
                ),
            }
        },
        "next_action": str(package.get("next_action") or "Review operational status."),
    }


