def latest_phase12_recheck_status(store: CoreStore, production: bool) -> dict[str, Any]:
    """Return a manager-safe latest Phase 1/2 recheck status."""

    qc = phase12_qc_fanout(store, production)
    summary = qc["summary"]
    open_lanes = [lane for lane in qc["lanes"] if lane["status"] != "ready"]
    latest_report: dict[str, Any] = {}
    recheck_dir = REPO_ROOT / "output" / "recheck"
    try:
        latest_file = max(
            recheck_dir.glob("phase12-recheck-*.json"),
            key=lambda path: path.stat().st_mtime,
        )
        loaded = json.loads(latest_file.read_text(encoding="utf-8"))
        if isinstance(loaded, dict):
            latest_report = loaded
    except (FileNotFoundError, ValueError, OSError, json.JSONDecodeError):
        latest_report = {}

    artifact_version = str(latest_report.get("version") or "")
    artifact_current = bool(artifact_version == __version__)
    phase_1_percent = int(summary.get("phase_1_technical_readiness_percent", 0) or 0)
    phase_2_percent = int(summary.get("phase_2_technical_readiness_percent", 0) or 0)
    phase_1_label = (
        "Technical controls ready"
        if phase_1_percent >= 100
        else "Technical review open"
    )
    phase_2_label = (
        "Technical controls ready"
        if phase_2_percent >= 100 and bool(summary.get("phase12_union_ready"))
        else "Technical review open"
    )
    next_action = str(
        summary.get("next_action")
        or "Keep Phase 2 owner decisions and runtime evidence visible."
    )
    return {
        "status": qc["status"],
        "version": __version__,
        "prepared_for": CUSTOMER_NAME,
        "prepared_by": CONTRACTOR_NAME,
        "summary": {
            "phase_1_technical_readiness_percent": phase_1_percent,
            "phase_2_technical_readiness_percent": phase_2_percent,
            "phase12_union_ready": bool(summary.get("phase12_union_ready")),
            "ready_lane_count": int(summary.get("ready_lane_count", 0) or 0),
            "action_required_lane_count": int(
                summary.get("action_required_lane_count", 0) or 0
            ),
            "engineering_closeable_lane_count": int(
                summary.get("engineering_closeable_lane_count", 0) or 0
            ),
            "customer_decision_lane_count": int(
                summary.get("customer_decision_lane_count", 0) or 0
            ),
            "secret_required_lane_count": int(
                summary.get("secret_required_lane_count", 0) or 0
            ),
            "latest_recheck_freshness": (
                "current_version" if artifact_current else "live_gate_snapshot"
            ),
            "latest_recheck_version": artifact_version or __version__,
            "latest_recheck_generated_at": latest_report.get("generated_at"),
        },
        "phase_status_brief": {
            "headline": f"Phase 1: {phase_1_label} | Phase 2: {phase_2_label}",
            "message": (
                f"Phase 1 is {phase_1_label.lower()}. Phase 2 is "
                f"{phase_2_label.lower()} and remains visible until the "
                f"integrated technical gate is proven. Next: {next_action}"
            ),
            "next_owner_action": next_action,
            "evidence_endpoint": "/api/qc/fan-out",
        },
        "open_lanes": [
            {
                "lane_id": lane["lane_id"],
                "label": lane["label"],
                "status": lane["status"],
                "score": lane["score"],
                "owner_agent_id": lane["owner_agent_id"],
                "next_action": lane["next_action"],
                "can_close_by_code": lane["can_close_by_code"],
                "customer_decision_required": lane["customer_decision_required"],
                "requires_secret": lane["requires_secret"],
                "evidence_endpoint": lane["evidence_endpoint"],
            }
            for lane in open_lanes
        ],
        "evidence_links": [
            {"label": "QC fan-out", "endpoint": "/api/qc/fan-out"},
            {"label": "Management brief", "endpoint": "/api/delivery/management-brief"},
            {"label": "Production actions", "endpoint": "/api/production/action-plan"},
        ],
        "privacy": {
            "customer_safe": True,
            "local_paths_returned": False,
            "artifact_file_path_returned": False,
            "admin_write_endpoints_returned": False,
            "raw_prompts_returned": False,
            "provider_payloads_returned": False,
            "credential_values_returned": False,
        },
    }


def ai_routing_control_console(store: CoreStore, production: bool) -> dict[str, Any]:
    """Aggregate admin-facing model routing controls without exposing secrets."""

    route = ai_routing_status(store)
    matrix = ai_model_benchmark_matrix(store, production)
    policy = route["provider_policy"]
    selected_route = "grounded_fallback"
    if route["active_route"] == "cloud_model":
        selected_route = f"{policy['provider']}_runtime"
    elif route["active_route"] == "local_model":
        selected_route = "local_model"
    first_task = matrix["tasks"][0] if matrix["tasks"] else {"candidates": []}
    routes = []
    for candidate in first_task["candidates"]:
        route_id = candidate["route"]
        routes.append(
            {
                "route": route_id,
                "provider": candidate["provider"],
                "model": candidate["model"],
                "status": candidate["status"],
                "runtime_available": candidate["runtime_available"],
                "credential_configured": candidate["credential_configured"],
                "selected": route_id == selected_route,
                "score": candidate["score"],
                "gate": candidate["fit"],
            }
        )
    active_profile = route["active_analysis_profile"]
    evaluations = ai_evaluations(store)
    actions = [
        {
            "action_id": "select-analysis-profile",
            "label": "Select analysis profile",
            "owner_agent_id": "admin_governance_agent",
            "state": "ready",
            "next_step": (
                "Use enterprise operations reasoning for deeper reasoning or "
                "ui-reporting-analyst for visual and report QA."
            ),
            "evidence_endpoint": "/api/admin/ai/analysis-profiles",
        },
        {
            "action_id": "confirm-runtime-gate",
            "label": "Confirm runtime gate",
            "owner_agent_id": "ai_diagnosis_agent",
            "state": policy["runtime_status"],
            "next_step": (
                "Keep grounded fallback active until credentials, runtime env "
                "approval, identity, grounding, and eval gates are ready."
            ),
            "evidence_endpoint": "/api/ai/routing",
        },
        {
            "action_id": "run-local-eval",
            "label": "Run local assistant evaluation",
            "owner_agent_id": "ai_diagnosis_agent",
            "state": next(
                item["status"] for item in evaluations if item["check"] == "local_eval_suite"
            ),
            "next_step": "Run the bounded eval before claiming provider quality.",
            "evidence_endpoint": "/api/ai/evaluations/runs",
        },
        {
            "action_id": "run-assistant-qa",
            "label": "Record 60-round Q/A evidence",
            "owner_agent_id": "reporting_compliance_agent",
            "state": next(
                item["status"] for item in evaluations if item["check"] == "assistant_qa_60"
            ),
            "next_step": "Store input-redacted Q/A evidence with zero provider calls.",
            "evidence_endpoint": "/api/assistant/quality-report",
        },
        {
            "action_id": "verify-a2a-adr",
            "label": "Verify A2A and ADR gates",
            "owner_agent_id": "admin_governance_agent",
            "state": "ready",
            "next_step": "Check owner agents, handoffs, trace policy, and ADR evidence.",
            "evidence_endpoint": "/api/orchestration/evidence-matrix",
        },
    ]
    return {
        "status": "ok",
        "version": __version__,
        "prepared_for": CUSTOMER_NAME,
        "prepared_by": CONTRACTOR_NAME,
        "summary": {
            "active_profile": active_profile["profile_id"],
            "profile_label": active_profile["label"],
            "provider": policy["provider"],
            "model": policy["model"],
            "active_route": route["active_route"],
            "runtime_status": policy["runtime_status"],
            "runtime_allowed": route["runtime_allowed"],
            "route_count": len(routes),
            "action_count": len(actions),
            "quality_claim": matrix["summary"]["quality_claim"],
        },
        "routes": routes,
        "actions": actions,
        "quality_gates": evaluations,
        "evidence_links": [
            {"label": "AI routing", "endpoint": "/api/ai/routing"},
            {"label": "Model matrix", "endpoint": "/api/ai/model-benchmarks"},
            {"label": "Provider policy", "endpoint": "/api/admin/ai/provider-policy"},
            {"label": "Analysis profiles", "endpoint": "/api/admin/ai/analysis-profiles"},
        ],
    }


def is_assistant_qa_challenge_run(run: dict[str, Any]) -> bool:
    """Return true when an eval run is the stored 60-round assistant challenge."""

    return run.get("benchmark_label") == "assistant_qa_60" and run.get("case_count", 0) >= 60


def assistant_qa_challenge_summary(eval_runs: list[dict[str, Any]]) -> dict[str, Any]:
    """Summarize the latest input-redacted 60-round assistant challenge run."""

    challenge_runs = [run for run in eval_runs if is_assistant_qa_challenge_run(run)]
    if not challenge_runs:
        return {
            "status": "waiting_for_run",
            "run_id": None,
            "score": 0,
            "passed": False,
            "case_count": 0,
            "provider_calls": 0,
            "categories": [],
            "created_at": None,
        }
    latest = challenge_runs[-1]
    categories = sorted({str(case.get("category", "unknown")) for case in latest["cases"]})
    return {
        "status": "ready" if latest["passed"] and latest["provider_calls"] == 0 else "review_required",
        "run_id": latest["run_id"],
        "score": latest["score"],
        "passed": latest["passed"],
        "case_count": latest["case_count"],
        "provider_calls": latest["provider_calls"],
        "categories": categories,
        "created_at": latest["created_at"],
    }


def ai_evaluations(store: CoreStore) -> list[dict[str, Any]]:
    """Return bounded AI safety and grounding evaluation status."""

    alerts = store.list_rows("alerts")
    telemetry = store.list_rows("telemetry")
    proposals = store.list_rows("recovery_proposals")
    eval_runs = store.list_ai_eval_runs()
    assistant_qa = assistant_qa_challenge_summary(eval_runs)
    policy = store.get_ai_provider_policy()
    knowledge_count = len(store.list_rag_knowledge_documents())
    has_grounding = bool(alerts or telemetry or proposals)
    return [
        {
            "check": "grounding_sources",
            "status": "ready" if has_grounding else "waiting_for_runtime_records",
            "evidence": "Alerts, telemetry, and recovery proposals are used before diagnosis text is produced.",
        },
        {
            "check": "model_fallback",
            "status": "ready",
            "evidence": "If no model route is configured, chat returns bounded non-model diagnosis.",
        },
        {
            "check": "human_approval",
            "status": "ready",
            "evidence": "Recovery actions remain behind human approval and write gates.",
        },
        {
            "check": "provider_labeling",
            "status": "ready",
            "evidence": "Local and cloud routes are labeled as configured or not configured.",
        },
        {
            "check": "rag_knowledge_base",
            "status": "ready" if knowledge_count >= 5 else "review_required",
            "evidence": (
                f"{knowledge_count} customer-safe knowledge document(s) are "
                "available for dashboard search and assistant grounding."
            ),
        },
        {
            "check": "provider_policy",
            "status": "ready",
            "evidence": (
                f"Policy source {policy['source']} selects {policy['provider']} "
                f"with profile {policy['quality_profile']}."
            ),
        },
        {
            "check": "provider_runtime_gateway",
            "status": "ready" if not model_runtime_allowed(policy, store) else "runtime_ready",
            "evidence": (
                "Cloud provider execution is default-off and requires admin policy, "
                "credential, runtime env approval, and operator authentication."
            ),
        },
        {
            "check": "local_eval_suite",
            "status": "ready" if eval_runs else "waiting_for_eval_run",
            "evidence": f"{len(eval_runs)} local AI/agent evaluation run(s) are stored.",
        },
        {
            "check": "assistant_qa_60",
            "status": assistant_qa["status"],
            "evidence": (
                f"{assistant_qa['case_count']} input-redacted assistant Q/A case(s), "
                f"{assistant_qa['provider_calls']} provider call(s)."
            ),
        },
    ]


def assistant_interaction_ledger(store: CoreStore) -> dict[str, Any]:
    """Return input-redacted assistant interaction evidence and metrics."""

    items = store.list_assistant_interactions()
    proposals = store.list_assistant_tool_proposals()
    feedback = store.list_assistant_feedback()
    success_count = sum(1 for item in items if item["outcome"] == "success")
    approval_count = sum(1 for item in items if item["requires_human_approval"])
    avg_latency = (
        round(sum(item["latency_ms"] for item in items) / len(items))
        if items
        else 0
    )
    avg_rating = (
        round(sum(item["rating"] for item in feedback) / len(feedback), 2)
        if feedback
        else 0
    )
    categories: dict[str, int] = {}
    statuses: dict[str, int] = {}
    for item in items:
        categories[item["prompt_category"]] = categories.get(item["prompt_category"], 0) + 1
        statuses[item["response_status"]] = statuses.get(item["response_status"], 0) + 1
    return {
        "status": "ok",
        "version": __version__,
        "prepared_for": CUSTOMER_NAME,
        "prepared_by": CONTRACTOR_NAME,
        "privacy": {
            "prompt_storage": "sha256_16_hash_only",
            "answer_storage": "not_stored",
            "operator_identity": "bounded_actor_label_only",
        },
        "summary": {
            "total": len(items),
            "success_count": success_count,
            "review_count": len(items) - success_count,
            "human_approval_count": approval_count,
            "average_latency_ms": avg_latency,
            "category_counts": categories,
            "status_counts": statuses,
            "prepared_proposal_count": len(proposals),
            "awaiting_approval_count": sum(
                1 for item in proposals if item["execution_state"] == "awaiting_human_approval"
            ),
            "approved_proposal_count": sum(
                1 for item in proposals if item["execution_state"] == "approved_recorded"
            ),
            "feedback_count": len(feedback),
            "average_rating": avg_rating,
            "low_rating_count": sum(1 for item in feedback if item["rating"] < 4),
            "follow_up_required_count": sum(
                1 for item in feedback if item["follow_up_required"]
            ),
        },
        "items": items[:50],
        "tool_proposals": proposals[:50],
        "feedback": feedback[:50],
        "evidence_links": [
            {"label": "Chat route", "endpoint": "/api/chat"},
            {"label": "Quality report", "endpoint": "/api/assistant/quality-report"},
            {"label": "Closed-loop findings", "endpoint": "/api/evidence/findings"},
            {"label": "Assistant interactions", "endpoint": "/api/assistant/interactions"},
            {"label": "Assistant sessions", "endpoint": "/api/assistant/sessions"},
            {"label": "BDD suggestions", "endpoint": "/api/assistant/bdd-suggestions"},
        ],
    }


def assistant_session_threads(
    store: CoreStore,
    session_id: str | None = None,
    actor: str | None = None,
) -> dict[str, Any]:
    """Return input-redacted assistant session threads for coworker continuity."""

    interactions = store.list_assistant_interactions()
    feedback = store.list_assistant_feedback()
    proposals = store.list_assistant_tool_proposals()
    if actor:
        interactions = [item for item in interactions if item.get("actor") == actor]
        allowed_sessions = {str(item.get("session_id")) for item in interactions}
        feedback = [item for item in feedback if str(item.get("session_id")) in allowed_sessions]
        proposals = [item for item in proposals if str(item.get("session_id")) in allowed_sessions]
    if session_id:
        safe_session_id = assistant_safe_identifier(session_id, "", 80)
        interactions = [
            item for item in interactions if item.get("session_id") == safe_session_id
        ]
    feedback_by_interaction: dict[str, list[dict[str, Any]]] = {}
    feedback_by_session: dict[str, list[dict[str, Any]]] = {}
    for item in feedback:
        feedback_by_interaction.setdefault(str(item.get("interaction_id")), []).append(item)
        feedback_by_session.setdefault(str(item.get("session_id")), []).append(item)
    proposals_by_session: dict[str, list[dict[str, Any]]] = {}
    for item in proposals:
        proposals_by_session.setdefault(str(item.get("session_id")), []).append(item)

    by_session: dict[str, list[dict[str, Any]]] = {}
    for item in interactions:
        by_session.setdefault(str(item.get("session_id") or "unknown"), []).append(item)

    sessions: list[dict[str, Any]] = []
    turns: list[dict[str, Any]] = []
    total_parent_links = 0
    context_ready_count = 0
    total_feedback = 0
    follow_up_required_count = 0
    pending_approval_count = 0
    for current_session_id, rows in by_session.items():
        rows.sort(key=lambda item: (str(item.get("created_at") or ""), str(item.get("interaction_id") or "")))
        session_feedback = feedback_by_session.get(current_session_id, [])
        session_proposals = proposals_by_session.get(current_session_id, [])
        parent_links = sum(1 for item in rows if item.get("parent_message_id"))
        total_parent_links += parent_links
        session_follow_ups = sum(1 for item in session_feedback if item.get("follow_up_required"))
        follow_up_required_count += session_follow_ups
        session_pending = sum(
            1
            for item in session_proposals
            if item.get("execution_state") in {"awaiting_human_approval", "blocked_until_human_approval"}
        )
        pending_approval_count += session_pending
        total_feedback += len(session_feedback)
        latest = rows[-1]
        category_counts: dict[str, int] = {}
        status_counts: dict[str, int] = {}
        for item in rows:
            category = str(item.get("prompt_category") or "uncategorized")
            status = str(item.get("response_status") or "unknown")
            category_counts[category] = category_counts.get(category, 0) + 1
            status_counts[status] = status_counts.get(status, 0) + 1
            item_feedback = feedback_by_interaction.get(str(item.get("interaction_id")), [])
            latest_feedback = item_feedback[0] if item_feedback else None
            turns.append(
                {
                    "session_id": current_session_id,
                    "interaction_id": item["interaction_id"],
                    "message_id": item["message_id"],
                    "parent_message_id": item.get("parent_message_id"),
                    "prompt_category": item["prompt_category"],
                    "response_status": item["response_status"],
                    "confidence": item["confidence"],
                    "evidence_count": item["evidence_count"],
                    "knowledge_count": item["knowledge_count"],
                    "requires_human_approval": item["requires_human_approval"],
                    "outcome": item["outcome"],
                    "latency_ms": item["latency_ms"],
                    "created_at": item["created_at"],
                    "feedback_count": len(item_feedback),
                    "latest_feedback_outcome": latest_feedback.get("outcome") if latest_feedback else None,
                    "raw_prompt_returned": False,
                    "answer_text_returned": False,
                }
            )
        evidence_total = sum(int(item.get("evidence_count") or 0) for item in rows)
        knowledge_total = sum(int(item.get("knowledge_count") or 0) for item in rows)
        avg_rating = (
            round(sum(int(item["rating"]) for item in session_feedback) / len(session_feedback), 2)
            if session_feedback
            else 0
        )
        continuity_state = "context_ready" if len(rows) > 1 and parent_links else "first_turn_ready"
        if len(rows) > 1 and parent_links:
            context_ready_count += 1
        next_action = (
            "Review follow-up feedback and convert weak signals into BDD candidates."
            if session_follow_ups
            else "Continue grounded follow-up with parent message id and evidence links."
        )
        sessions.append(
            {
                "session_id": current_session_id,
                "status": "active",
                "turn_count": len(rows),
                "first_seen_at": rows[0]["created_at"],
                "last_seen_at": latest["created_at"],
                "latest_message_id": latest["message_id"],
                "parent_link_count": parent_links,
                "continuity_state": continuity_state,
                "category_counts": category_counts,
                "status_counts": status_counts,
                "evidence_counts": {
                    "runtime": evidence_total,
                    "knowledge": knowledge_total,
                    "total": evidence_total + knowledge_total,
                },
                "feedback_count": len(session_feedback),
                "average_rating": avg_rating,
                "follow_up_required_count": session_follow_ups,
                "proposal_count": len(session_proposals),
                "pending_approval_count": session_pending,
                "next_action": next_action,
                "ledger_endpoint": "/api/assistant/interactions",
                "feedback_endpoint": "/api/assistant/interactions/{interaction_id}/feedback",
                "bdd_endpoint": "/api/assistant/bdd-suggestions",
            }
        )
    sessions.sort(key=lambda item: (str(item["last_seen_at"]), item["session_id"]), reverse=True)
    turns.sort(key=lambda item: (str(item["created_at"]), item["interaction_id"]), reverse=True)
    if session_id and not sessions:
        raise HTTPException(status_code=404, detail="Assistant session not found")
    thread_count = len(sessions)
    turn_count = len(turns)
    continuity_state = (
        "context_ready" if context_ready_count else "first_turn_ready" if turn_count else "waiting_for_operator_session"
    )
    quality_score = 100 if context_ready_count and total_feedback else (90 if turn_count else 60)
    return {
        "status": "ready" if turn_count else "waiting_for_operator_session",
        "version": __version__,
        "prepared_for": CUSTOMER_NAME,
        "prepared_by": CONTRACTOR_NAME,
        "privacy": {
            "raw_prompt_returned": False,
            "answer_text_returned": False,
            "provider_payload_returned": False,
            "actor_values_returned": False,
            "storage_policy": "sha256_16_prompt_hash_only",
            "customer_delivery_safe": True,
        },
        "summary": {
            "thread_count": thread_count,
            "turn_count": turn_count,
            "context_ready_count": context_ready_count,
            "parent_link_count": total_parent_links,
            "feedback_count": total_feedback,
            "follow_up_required_count": follow_up_required_count,
            "pending_approval_count": pending_approval_count,
            "continuity_state": continuity_state,
            "quality_score": quality_score,
        },
        "sessions": sessions[:20],
        "turns": turns[:50] if session_id else [],
        "evidence_links": [
            {"label": "Chat route", "endpoint": "/api/chat"},
            {"label": "Assistant interactions", "endpoint": "/api/assistant/interactions"},
            {"label": "Assistant feedback", "endpoint": "/api/assistant/interactions/{interaction_id}/feedback"},
            {"label": "BDD suggestions", "endpoint": "/api/assistant/bdd-suggestions"},
        ],
    }


def assistant_bdd_suggestion_from_interaction(
    item: dict[str, Any],
    *,
    kind: str,
    priority: str,
    title: str,
    then_text: str,
    source: str,
    evidence: list[dict[str, str]],
) -> dict[str, Any]:
    """Create one input-redacted Gherkin candidate from assistant metadata."""

    seed = (
        f"{source}:{item.get('interaction_id')}:{kind}:"
        f"{item.get('prompt_category')}:{item.get('response_status')}"
    )
    scenario_id = f"bdd-{hashlib.sha256(seed.encode('utf-8')).hexdigest()[:12]}"
    return {
        "scenario_id": scenario_id,
        "feature": "Assistant closed-loop learning",
        "scenario": title,
        "kind": kind,
        "priority": priority,
        "owner_agent_id": "reporting_compliance_agent",
        "source": source,
        "source_refs": {
            "interaction_id": item.get("interaction_id"),
            "session_id": item.get("session_id"),
            "message_id": item.get("message_id"),
            "prompt_category": item.get("prompt_category"),
            "response_status": item.get("response_status"),
        },
        "gherkin": {
            "given": (
                "a input-redacted assistant interaction has been recorded with "
                f"category {item.get('prompt_category', 'unknown')}"
            ),
            "when": (
                "the closed-loop BDD suggestion endpoint reviews assistant "
                "interaction, feedback, and finding metadata"
            ),
            "then": then_text,
        },
        "evidence": evidence,
        "target_file": "tests/bdd/agentiot_api_baseline.feature",
        "write_policy": "candidate_only_human_approved_patch_required",
        "candidate_only": True,
        "privacy": {
            "raw_prompt_returned": False,
            "answer_text_returned": False,
            "provider_payload_returned": False,
            "uses_prompt_hash_only": True,
        },
    }


def assistant_bdd_suggestion_from_finding(item: dict[str, Any]) -> dict[str, Any]:
    """Create one input-redacted Gherkin candidate from a closed-loop finding."""

    kind = (
        "failure"
        if item.get("severity") == "review_required"
        or str(item.get("outcome", "")).lower() in {"fail", "unsafe", "not_helpful"}
        else "happy"
    )
    priority = "high" if kind == "failure" else "normal"
    seed = f"finding:{item.get('finding_id')}:{item.get('source')}:{kind}"
    scenario_id = f"bdd-{hashlib.sha256(seed.encode('utf-8')).hexdigest()[:12]}"
    return {
        "scenario_id": scenario_id,
        "feature": "Closed-loop evidence learning",
        "scenario": "Evidence finding becomes a BDD review candidate",
        "kind": kind,
        "priority": priority,
        "owner_agent_id": "sw_test_audit_agent",
        "source": "evidence_finding",
        "source_refs": {
            "finding_id": item.get("finding_id"),
            "source": item.get("source"),
            "outcome": item.get("outcome"),
            "severity": item.get("severity"),
        },
        "gherkin": {
            "given": (
                "a closed-loop evidence finding has been stored from "
                f"{item.get('source', 'unknown')}"
            ),
            "when": (
                "the assistant BDD suggestion endpoint reviews finding metadata"
            ),
            "then": (
                "the response returns a reviewable scenario candidate with "
                "owner, priority, evidence link, and no raw operator input or answer text"
            ),
        },
        "evidence": [
            {"label": "Evidence findings", "endpoint": "/api/evidence/findings"},
            {"label": "Action board", "endpoint": "/api/evidence/action-board"},
        ],
        "target_file": "tests/bdd/agentiot_api_baseline.feature",
        "write_policy": "candidate_only_human_approved_patch_required",
        "candidate_only": True,
        "privacy": {
            "raw_prompt_returned": False,
            "answer_text_returned": False,
            "provider_payload_returned": False,
            "uses_prompt_hash_only": False,
        },
    }


def assistant_bdd_suggestions(store: CoreStore) -> dict[str, Any]:
    """Derive input-redacted BDD candidates from real assistant evidence."""

    interactions = store.list_assistant_interactions()
    feedback = store.list_assistant_feedback()
    findings = store.list_evidence_findings()
    feedback_by_interaction: dict[str, list[dict[str, Any]]] = {}
    for item in feedback:
        feedback_by_interaction.setdefault(item["interaction_id"], []).append(item)

    suggestions: list[dict[str, Any]] = []
    for item in interactions:
        item_feedback = feedback_by_interaction.get(item["interaction_id"], [])
        low_quality_feedback = [
            signal
            for signal in item_feedback
            if signal["rating"] < 4
            or signal["outcome"] in {"not_helpful", "needs_more_evidence", "unsafe"}
            or signal["follow_up_required"]
        ]
        if low_quality_feedback:
            signal = low_quality_feedback[0]
            suggestions.append(
                assistant_bdd_suggestion_from_interaction(
                    item,
                    kind="failure",
                    priority="high",
                    title="Operator feedback becomes a BDD regression candidate",
                    then_text=(
                        "the response returns a failure-case scenario candidate, "
                        "links the feedback evidence, and does not expose raw operator input text"
                    ),
                    source="assistant_feedback",
                    evidence=[
                        {
                            "label": "Feedback",
                            "endpoint": signal["evidence_endpoint"],
                        },
                        {
                            "label": "Interaction ledger",
                            "endpoint": "/api/assistant/interactions",
                        },
                    ],
                )
            )
        if item["response_status"] == "model_unavailable" or str(
            item["confidence"]
        ).startswith("low"):
            suggestions.append(
                assistant_bdd_suggestion_from_interaction(
                    item,
                    kind="edge",
                    priority="medium",
                    title="Unavailable model route stays grounded and bounded",
                    then_text=(
                        "the response returns a bounded fallback scenario candidate "
                        "with human-approval status and input-redacted evidence"
                    ),
                    source="assistant_interaction",
                    evidence=[
                        {"label": "Chat route", "endpoint": "/api/chat"},
                        {"label": "AI routing", "endpoint": "/api/ai/routing"},
                    ],
                )
            )
        if item["outcome"] == "success" and int(item["evidence_count"]) > 0:
            suggestions.append(
                assistant_bdd_suggestion_from_interaction(
                    item,
                    kind="happy",
                    priority="normal",
                    title="Grounded assistant success is preserved as BDD evidence",
                    then_text=(
                        "the response returns a happy-path scenario candidate "
                        "with runtime evidence counts and customer-safe metadata"
                    ),
                    source="assistant_interaction",
                    evidence=[
                        {"label": "Chat route", "endpoint": "/api/chat"},
                        {
                            "label": "Closed-loop findings",
                            "endpoint": "/api/evidence/findings",
                        },
                    ],
                )
            )
    finding_sources = {
        "assistant_chat",
        "assistant_feedback",
        "assistant_tool_proposal",
        "qa_challenge",
        "ai_eval",
        "agent_task",
    }
    for item in findings:
        if item.get("source") in finding_sources:
            suggestions.append(assistant_bdd_suggestion_from_finding(item))

    seen: set[str] = set()
    unique_suggestions: list[dict[str, Any]] = []
    priority_order = {"high": 0, "medium": 1, "normal": 2}
    for suggestion in sorted(
        suggestions,
        key=lambda item: (
            priority_order.get(item["priority"], 9),
            item["scenario_id"],
        ),
    ):
        if suggestion["scenario_id"] in seen:
            continue
        seen.add(suggestion["scenario_id"])
        unique_suggestions.append(suggestion)

    return {
        "status": "ok",
        "version": __version__,
        "prepared_for": CUSTOMER_NAME,
        "prepared_by": CONTRACTOR_NAME,
        "summary": {
            "interaction_count": len(interactions),
            "feedback_count": len(feedback),
            "finding_count": len(findings),
            "suggestion_count": len(unique_suggestions),
            "high_priority_count": sum(
                1 for item in unique_suggestions if item["priority"] == "high"
            ),
            "auto_write_enabled": False,
            "target_file": "tests/bdd/agentiot_api_baseline.feature",
        },
        "suggestions": unique_suggestions[:30],
        "governance": {
            "standard": "BDD/Gherkin",
            "closed_loop_requirement": "B10",
            "owner_agent_id": "reporting_compliance_agent",
            "review_agent_id": "sw_test_audit_agent",
            "approval_gate": "human_approved_patch_required",
            "runtime_file_write": False,
            "safe_next_step": (
                "A maintainer reviews each candidate before adding it to the "
                "version-controlled BDD feature file."
            ),
        },
        "privacy": {
            "raw_prompt_returned": False,
            "raw_prompt_stored": False,
            "answer_text_returned": False,
            "provider_payload_returned": False,
            "customer_delivery_safe": True,
            "source_fields": [
                "interaction_id",
                "session_id",
                "message_id",
                "prompt_category",
                "response_status",
                "feedback rating/outcome/category",
            ],
        },
        "evidence_links": [
            {"label": "Assistant interactions", "endpoint": "/api/assistant/interactions"},
            {"label": "Closed-loop findings", "endpoint": "/api/evidence/findings"},
            {"label": "BDD baseline", "endpoint": "/api/assistant/bdd-suggestions"},
        ],
    }


def record_assistant_feedback(
    store: CoreStore,
    interaction_id: str,
    request: AssistantFeedbackRequest,
    *,
    actor: str,
) -> dict[str, Any]:
    """Record one operator feedback signal without storing prompt or answer text."""

    result = store.add_assistant_feedback(
        interaction_id=interaction_id,
        request=request,
        actor=actor,
    )
    return {
        "status": "recorded",
        "version": __version__,
        "prepared_for": CUSTOMER_NAME,
        "prepared_by": CONTRACTOR_NAME,
        "feedback": result["feedback"],
        "audit_event_id": result["audit_event_id"],
        "finding_id": result["finding_id"],
        "privacy": {
            "raw_prompt_returned": False,
            "raw_prompt_stored": False,
            "answer_text_stored": False,
            "provider_payload_stored": False,
            "customer_delivery_safe": True,
        },
    }


def assistant_quality_report(store: CoreStore, production: bool) -> dict[str, Any]:
    """Return an operational quality report for the assistant route."""

    route = ai_routing_status(store)
    policy = store.get_ai_provider_policy()
    profiles = store.list_ai_analysis_profiles()
    active_profile = profiles["active_profile"]
    diagnosis = grounded_diagnosis(
        store,
        "Summarize current assistant quality with runtime and delivery evidence.",
    )
    diagnosis.answer_review = assistant_answer_review(
        diagnosis, "assistant-quality-preview"
    )
    answer_review = diagnosis.answer_review
    eval_runs = store.list_ai_eval_runs()
    latest_eval = eval_runs[-1] if eval_runs else None
    assistant_qa = assistant_qa_challenge_summary(eval_runs)
    rag_base = rag_knowledge_base(store)
    findings = store.list_evidence_findings()
    interaction_ledger = assistant_interaction_ledger(store)
    pending_recovery_count = len(
        [item for item in store.list_rows("recovery_proposals") if item.get("status") != "approved"]
    )
    runtime_grounding_count = len(diagnosis.grounding)
    knowledge_count = rag_base["metrics"]["document_count"]
    gates = [
        {
            "gate": "routing_answer_split",
            "status": "ready"
            if route["reasoning_layer"] and route["answer_layer"]
            else "review_required",
            "evidence": (
                f"{route['reasoning_layer']} routes evidence before "
                f"{route['answer_layer']} produces the answer."
            ),
        },
        {
            "gate": "rag_contract_grounding",
            "status": "ready" if knowledge_count >= 5 else "review_required",
            "evidence": f"{knowledge_count} customer-safe RAG document(s) are indexed.",
        },
        {
            "gate": "runtime_grounding",
            "status": "ready" if runtime_grounding_count else "review_required",
            "evidence": f"{runtime_grounding_count} runtime record(s) ground the preview diagnosis.",
        },
        {
            "gate": "a2a_trace",
            "status": "ready" if len(diagnosis.a2a_trace) >= 2 else "review_required",
            "evidence": f"{len(diagnosis.a2a_trace)} A2A handoff trace item(s) are visible.",
        },
        {
            "gate": "provider_runtime_safety",
            "status": "ready",
            "evidence": (
                f"Provider {policy['provider']} is labeled as "
                f"{policy['status']} without exposing credentials."
            ),
        },
        {
            "gate": "local_eval_run",
            "status": "ready"
            if latest_eval and latest_eval["passed"]
            else "review_required",
            "evidence": (
                f"Latest eval score {latest_eval['score']}."
                if latest_eval
                else "No local assistant eval run has been stored yet."
            ),
        },
        {
            "gate": "assistant_qa_60",
            "status": assistant_qa["status"],
            "evidence": (
                f"{assistant_qa['case_count']} input-redacted Q/A cases; "
                f"{assistant_qa['provider_calls']} provider call(s)."
            ),
        },
        {
            "gate": "answer_self_evaluation",
            "status": "ready" if answer_review["score"] >= 90 else "review_required",
            "evidence": (
                f"Answer review score {answer_review['score']}; "
                f"{answer_review['ready_gates']}/{answer_review['gate_count']} gate(s) ready."
            ),
        },
        {
            "gate": "closed_loop_learning",
            "status": "ready" if findings else "review_required",
            "evidence": f"{len(findings)} hash-only evidence finding(s) are stored.",
        },
        {
            "gate": "assistant_interaction_ledger",
            "status": "ready",
            "evidence": (
                f"{interaction_ledger['summary']['total']} assistant interaction(s) "
                "are tracked with input hashes and no answer text."
            ),
        },
        {
            "gate": "operator_feedback_loop",
            "status": "ready",
            "evidence": (
                f"{interaction_ledger['summary']['feedback_count']} input-redacted "
                "operator feedback record(s) can tune assistant quality."
            ),
        },
        {
            "gate": "human_approval_boundary",
            "status": "ready"
            if diagnosis.requires_human_approval or pending_recovery_count == 0
            else "review_required",
            "evidence": "Assistant output keeps recovery execution behind HITL approval or confirms no pending recovery action.",
        },
    ]
    ready_count = sum(1 for gate in gates if gate["status"] == "ready")
    blockers = [
        gate["evidence"] for gate in gates if gate["status"] != "ready"
    ]
    recommendations = []
    if not runtime_grounding_count:
        recommendations.append("Create or ingest live telemetry, alerts, and recovery records before production assistant claims.")
    if not latest_eval:
        recommendations.append("Run /api/ai/evaluations/runs after every assistant or agent-route change.")
    if assistant_qa["status"] != "ready":
        recommendations.append("Run the 60-round assistant answer-quality review before release evidence signoff.")
    if not findings:
        recommendations.append("Keep assistant chats, evals, and agent tasks recorded in closed-loop evidence findings.")
    if not interaction_ledger["summary"]["feedback_count"]:
        recommendations.append("Capture operator feedback on assistant turns to improve coworker quality evidence.")
    if not recommendations:
        recommendations.append("Keep the active profile, RAG base, A2A trace, and eval run in the release gate.")
    return {
        "status": "ready" if not blockers else "review_required",
        "version": __version__,
        "score": round((ready_count / len(gates)) * 100),
        "kpi_target": 99.99,
        "active_route": route["active_route"],
        "active_profile": active_profile["profile_id"],
        "layers": {
            "routing_layer": route["reasoning_layer"],
            "answer_layer": route["answer_layer"],
            "rag_mode": active_profile["rag_mode"],
            "model_strategy": active_profile["model_strategy"],
            "provider_runtime_status": policy["status"],
            "runtime_allowed": route["runtime_allowed"],
        },
        "grounding": {
            "runtime_records": runtime_grounding_count,
            "rag_documents": knowledge_count,
            "selected_knowledge": len(diagnosis.knowledge_grounding),
            "a2a_trace_items": len(diagnosis.a2a_trace),
            "latest_confidence": diagnosis.confidence,
        },
        "interaction_ledger": interaction_ledger["summary"],
        "assistant_qa_challenge": assistant_qa,
        "answer_review": answer_review,
        "quality_gates": gates,
        "blockers": blockers,
        "recommendations": recommendations,
        "evidence_links": [
            {"label": "Chat route", "endpoint": "/api/chat"},
            {"label": "AI routing", "endpoint": "/api/ai/routing"},
            {"label": "RAG search", "endpoint": "/api/rag/search"},
            {"label": "AI evaluations", "endpoint": "/api/ai/evaluations/runs"},
            {"label": "A2A evidence", "endpoint": "/api/orchestration/evidence-matrix"},
            {"label": "Closed-loop findings", "endpoint": "/api/evidence/findings"},
        ],
    }


def assistant_coworker_quality_ladder(store: CoreStore, production: bool) -> dict[str, Any]:
    """Return a input-redacted ladder toward coworker-grade assistant readiness."""

    quality = assistant_quality_report(store, production)
    route = ai_routing_status(store)
    resource_governance = ai_resource_governance(store)
    orchestration = orchestration_evidence_matrix(store)
    model_matrix = ai_model_benchmark_matrix(store, production)
    release = release_evidence_console(store, production)
    operations = operation_summary(store, production)
    eval_runs = store.list_ai_eval_runs()
    assistant_qa = assistant_qa_challenge_summary(eval_runs)
    findings = store.list_evidence_findings()
    ledger = assistant_interaction_ledger(store)
    sessions = assistant_session_threads(store)
    bdd = assistant_bdd_suggestions(store)
    answer_review = quality["answer_review"]
    counters = operations["counters"]
    runtime_record_count = sum(
        int(counters[key])
        for key in ("devices", "telemetry", "open_alerts", "pending_recovery")
    )
    qa_ready = bool(eval_runs) and assistant_qa["status"] == "ready"
    release_ready = release["status"] == "ready" and float(release["summary"]["sla_gap"]) <= 0
    route_task_ready_count = sum(
        1 for item in model_matrix["tasks"] if item.get("recommended_route")
    )
    orchestration_control = orchestration["control_plane"]
    orchestration_ready = orchestration_control["release_gate"] == "ready"
    orchestration_score = (
        100
        if orchestration_ready
        else 95 if route_task_ready_count >= 4 else 80
    )
    token_window_count = int(
        resource_governance["token_usage"]["summary"]["window_count"]
    )
    provider_transparency_ready = (
        route["active_route"] == "grounded_fallback"
        and not route["runtime_allowed"]
        and token_window_count >= len(MODEL_TOKEN_WINDOWS)
        and resource_governance["privacy"]["secret_values_returned"] is False
    )
    provider_transparency_score = (
        100
        if provider_transparency_ready
        else int(model_matrix["summary"]["average_fit_score"])
        if route["runtime_allowed"]
        else 90
    )
    dimensions = [
        {
            "dimension_id": "grounded_reasoning",
            "label": "Grounded operational reasoning",
            "owner_agent_id": "ai_diagnosis_agent",
            "score": min(100, quality["score"] + (10 if runtime_record_count else 0)),
            "status": "ready" if runtime_record_count and quality["grounding"]["selected_knowledge"] else "review_required",
            "evidence": f"{runtime_record_count} runtime record(s), {quality['grounding']['selected_knowledge']} selected knowledge item(s).",
            "next_action": "Ingest or verify live telemetry, alert, and recovery evidence before coworker-grade claims.",
            "evidence_endpoint": "/api/assistant/quality-report",
        },
        {
            "dimension_id": "answer_self_evaluation",
            "label": "Per-answer self-evaluation",
            "owner_agent_id": "testing_audit_agent",
            "score": float(answer_review["score"]),
            "status": "ready" if answer_review["score"] >= 90 else "review_required",
            "evidence": f"Answer review {answer_review['ready_gates']}/{answer_review['gate_count']} gate(s) ready; score {answer_review['score']}.",
            "next_action": "Run per-answer review with every assistant route change and record input-redacted feedback for weak gates.",
            "evidence_endpoint": "/api/chat",
        },
        {
            "dimension_id": "agent_orchestration",
            "label": "A2A agent orchestration",
            "owner_agent_id": "admin_governance_agent",
            "score": orchestration_score,
            "status": "ready" if orchestration_score >= 95 else "review_required",
            "evidence": (
                f"{route_task_ready_count} routed model/agent task(s), "
                f"{orchestration_control['a2a_edge_count']} A2A edge(s), "
                f"{orchestration_control['adr_gate_count']} ADR gate(s); "
                f"release gate {orchestration_control['release_gate']}."
            ),
            "runtime_evidence": {
                "release_gate": orchestration_control["release_gate"],
                "maturity_score": orchestration_control["maturity_score"],
                "a2a_edges": orchestration_control["a2a_edge_count"],
                "adr_gates": orchestration_control["adr_gate_count"],
            },
            "next_action": "Keep section-owner agents, A2A traces, ADR references, and evidence endpoints visible per dashboard area.",
            "evidence_endpoint": "/api/ai/model-benchmarks",
        },
        {
            "dimension_id": "tool_action_governance",
            "label": "Tool and HITL governance",
            "owner_agent_id": "alert_recovery_agent",
            "score": 100,
            "status": "ready",
            "evidence": "Recovery and production actions remain approval-gated; assistant workbench does not execute tools.",
            "next_action": "Continue preparing actions as auditable proposals until a human approves execution.",
            "evidence_endpoint": "/api/assistant/workbench",
        },
        {
            "dimension_id": "memory_privacy",
            "label": "Input-redacted memory and privacy",
            "owner_agent_id": "reporting_compliance_agent",
            "score": 100,
            "status": "ready",
            "evidence": f"{ledger['summary']['total']} interaction(s) tracked with hash-only prompt evidence and no answer storage.",
            "next_action": "Keep raw operator inputs, answer text, provider payloads, local paths, and credential values out of customer output.",
            "evidence_endpoint": "/api/assistant/interactions",
        },
        {
            "dimension_id": "evaluation_evidence",
            "label": "Local QA and challenge evidence",
            "owner_agent_id": "testing_audit_agent",
            "score": 100 if qa_ready else 55,
            "status": "ready" if qa_ready else "review_required",
            "evidence": f"{assistant_qa['case_count']} assistant Q/A case(s), {assistant_qa['provider_calls']} provider call(s), {len(eval_runs)} eval run(s).",
            "next_action": "Run the local eval suite and the 60-round assistant answer-quality review after assistant-route changes.",
            "evidence_endpoint": "/api/ai/evaluations/runs",
        },
        {
            "dimension_id": "provider_route_transparency",
            "label": "Provider route transparency",
            "owner_agent_id": "ai_diagnosis_agent",
            "score": provider_transparency_score,
            "status": "ready" if route["active_route"] == "grounded_fallback" or route["runtime_allowed"] else "review_required",
            "evidence": (
                f"Active route {route['active_route']} with "
                f"runtime_allowed={route['runtime_allowed']}, "
                f"{token_window_count} token window(s), and no hidden provider execution."
            ),
            "runtime_evidence": {
                "active_route": route["active_route"],
                "local_cloud_controls": "configured_and_gated",
                "token_windows": token_window_count,
                "secret_values_returned": resource_governance["privacy"]["secret_values_returned"],
            },
            "next_action": "Enable local or cloud runtime only after credentials, policy, identity, grounding, and eval gates pass.",
            "evidence_endpoint": "/api/ai/routing",
        },
        {
            "dimension_id": "release_sla_alignment",
            "label": "Release and SLA alignment",
            "owner_agent_id": "release_compliance_controller",
            "score": float(release["summary"]["kpi_score"]),
            "status": "ready" if release_ready else "review_required",
            "evidence": f"Release KPI {release['summary']['kpi_score']} vs SLA {release['summary']['sla_target']}; gap {release['summary']['sla_gap']}.",
            "next_action": "Close release mission, QA, visual, security, and drift evidence before customer mirror.",
            "evidence_endpoint": "/api/release/evidence-console",
        },
        {
            "dimension_id": "closed_loop_learning",
            "label": "Closed-loop findings and BDD learning",
            "owner_agent_id": "reporting_compliance_agent",
            "score": 100
            if findings and bdd["summary"]["suggestion_count"] and sessions["summary"]["turn_count"]
            else 90 if findings else 40,
            "status": "ready" if findings else "review_required",
            "evidence": (
                f"{len(findings)} finding(s), "
                f"{bdd['summary']['suggestion_count']} BDD candidate(s), "
                f"{sessions['summary']['thread_count']} session thread(s)."
            ),
            "next_action": "Record assistant sessions, feedback, findings, and BDD candidates as input-redacted lessons after each change.",
            "evidence_endpoint": "/api/assistant/sessions",
        },
    ]
    ready_count = sum(1 for item in dimensions if item["status"] == "ready")
    score = round(sum(float(item["score"]) for item in dimensions) / len(dimensions), 1)
    target = 99.99
    gap = round(max(0.0, target - score), 2)
    action_queue = []
    for item in dimensions:
        if item["status"] == "ready":
            continue
        priority = "P0" if item["dimension_id"] in {"grounded_reasoning", "evaluation_evidence", "release_sla_alignment"} else "P1"
        action_queue.append(
            {
                "priority": priority,
                "owner_agent_id": item["owner_agent_id"],
                "action": item["next_action"],
                "evidence_endpoint": item["evidence_endpoint"],
                "acceptance_gate": item["dimension_id"],
            }
        )
    score_gaps = [item for item in dimensions if float(item["score"]) < target]
    for item in score_gaps:
        if any(action["acceptance_gate"] == item["dimension_id"] for action in action_queue):
            continue
        priority = "P1" if float(item["score"]) < 95 else "P2"
        action_queue.append(
            {
                "priority": priority,
                "owner_agent_id": item["owner_agent_id"],
                "action": item["next_action"],
                "evidence_endpoint": item["evidence_endpoint"],
                "acceptance_gate": item["dimension_id"],
                "score_gap": round(max(0.0, target - float(item["score"])), 2),
            }
        )
    if not action_queue:
        action_queue.append(
            {
                "priority": "P2",
                "owner_agent_id": "project_delivery_coordinator",
                "action": "Maintain six-hour drift reviews and repeat visual, QA, security, and release checks after each change.",
                "evidence_endpoint": "/api/project/drift-control",
                "acceptance_gate": "continuous_control",
            }
        )
    return {
        "status": "ready" if ready_count == len(dimensions) and release_ready else "review_required",
        "version": __version__,
        "prepared_for": CUSTOMER_NAME,
        "prepared_by": CONTRACTOR_NAME,
        "summary": {
            "score": score,
            "target": target,
            "gap_to_target": gap,
            "ready_dimensions": ready_count,
            "dimension_count": len(dimensions),
            "active_route": route["active_route"],
            "runtime_record_count": runtime_record_count,
            "qa_ready": qa_ready,
            "release_ready": release_ready,
            "parity_claim": "not_claimed_until_all_gates_ready",
        },
        "dimensions": dimensions,
        "action_queue": action_queue[:6],
        "comparison_targets": [
            {
                "target": "Advanced reasoning",
                "required_evidence": "grounded multi-step answers, citations, eval pass, and route transparency",
                "claim_state": "not_claimed_until_all_gates_ready",
            },
            {
                "target": "Operations coworker workflow",
                "required_evidence": "workbench continuity, tool proposals, human approval, and audit ledger",
                "claim_state": "bounded_copilot_surface_active",
            },
            {
                "target": "Independent review discipline",
                "required_evidence": "clean-room traceability, tests, security scan, visual audit, and release evidence",
                "claim_state": "tracked_by_release_and_drift_gates",
            },
        ],
        "charts": [
            {
                "chart_id": "coworker-quality-ladder",
                "title": "Coworker Quality Ladder",
                "type": "bar",
                "unit": "score",
                "series": [
                    {"label": item["label"], "value": item["score"]}
                    for item in dimensions
                ],
            }
        ],
        "evidence_links": [
            {"label": "Assistant quality", "endpoint": "/api/assistant/quality-report"},
            {"label": "Assistant workbench", "endpoint": "/api/assistant/workbench"},
            {"label": "Assistant sessions", "endpoint": "/api/assistant/sessions"},
            {"label": "AI assurance", "endpoint": "/api/ai/assurance-console"},
            {"label": "Release evidence", "endpoint": "/api/release/evidence-console"},
            {"label": "Drift control", "endpoint": "/api/project/drift-control"},
        ],
        "privacy": {
            "raw_prompt_storage": "forbidden",
            "answer_storage": "not_stored",
            "provider_payload_storage": "not_stored",
            "credential_values_returned": "false",
            "customer_delivery_safe": "yes",
        },
    }


def ai_assurance_console(store: CoreStore, production: bool) -> dict[str, Any]:
    """Return one customer-safe AI assurance view across model, RAG, and release gates."""

    assistant = assistant_quality_report(store, production)
    rag = rag_quality_console(store)
    routing = ai_routing_status(store)
    model_matrix = ai_model_benchmark_matrix(store, production)
    release = release_evidence_console(store, production)
    coworker_ladder = assistant_coworker_quality_ladder(store, production)
    route_decision = model_matrix["summary"]["route_decision"]
    ai_checks = ai_evaluations(store)
    assistant_score = int(assistant["score"])
    rag_score = int(rag["summary"]["coverage_score"])
    model_score = int(model_matrix["summary"]["average_fit_score"])
    release_score = float(release["summary"]["kpi_score"])
    assurance_score = round((assistant_score + rag_score + model_score + release_score) / 4)
    selected_route = routing["active_route"]
    ab_routes = [
        {"route_id": "grounded_fallback", "label": "Grounded fallback", "fit_score": 90, "status": "selected" if selected_route == "grounded_fallback" else "ready", "reason": "Contract and runtime evidence first; zero provider dependency."},
        {"route_id": "local_model", "label": "Local model", "fit_score": 84 if routing["local_model"]["state"] == "configured" else 55, "status": routing["local_model"]["state"], "reason": "Useful for private edge diagnosis after local model configuration."},
        {"route_id": "cloud_model", "label": "Cloud model", "fit_score": 92 if routing["runtime_allowed"] else 58, "status": "runtime_ready" if routing["runtime_allowed"] else "gated", "reason": "Allowed only after admin policy, credential, identity, grounding, and eval gates pass."},
        {"route_id": "agent_orchestra", "label": "Agent orchestra", "fit_score": 88, "status": "ready", "reason": "A2A route connects operations, diagnosis, recovery, reporting, and governance agents."},
    ]
    quality_gates = [
        {"gate": "assistant_quality", "status": assistant["status"], "score": assistant_score},
        {"gate": "rag_grounding", "status": rag["status"], "score": rag_score},
        {"gate": "model_route_fit", "status": route_decision["status"], "score": model_score},
        {"gate": "release_evidence", "status": release["status"], "score": release_score},
    ] + [{"gate": item["check"], "status": item["status"], "evidence": item["evidence"]} for item in ai_checks[:5]]
    action_queue: list[dict[str, Any]] = []
    for index, recommendation in enumerate(assistant["recommendations"][:3]):
        action_queue.append({"priority": "P0" if index == 0 else "P1", "owner_agent_id": "ai_diagnosis_agent", "action": recommendation, "evidence_endpoint": "/api/assistant/quality-report", "acceptance_gate": "assistant_quality"})
    for action in rag.get("action_plan", [])[:2]:
        action_queue.append({"priority": "P1", "owner_agent_id": action["owner_agent_id"], "action": action["action"], "evidence_endpoint": action["evidence_endpoint"], "acceptance_gate": "rag_grounding"})
    if not route_decision["ready"]:
        action_queue.append({"priority": "P0", "owner_agent_id": "ai_diagnosis_agent", "action": route_decision["next_action"], "evidence_endpoint": route_decision["evidence_endpoint"], "acceptance_gate": "model_route_decision"})
    for action in release.get("action_plan", [])[:3]:
        action_queue.append(action)
    return {
        "status": "ready" if assurance_score >= 99 and release["status"] == "ready" else "review_required",
        "version": __version__,
        "prepared_for": CUSTOMER_NAME,
        "prepared_by": CONTRACTOR_NAME,
        "summary": {"assurance_score": assurance_score, "assistant_score": assistant_score, "rag_score": rag_score, "model_score": model_score, "release_score": release_score, "coworker_quality_score": coworker_ladder["summary"]["score"], "coworker_quality_gap": coworker_ladder["summary"]["gap_to_target"], "release_sla_target": release["summary"]["sla_target"], "release_gap": release["summary"]["sla_gap"], "selected_route": selected_route, "model_route_decision_ready": route_decision["ready"], "model_route_decision_state": route_decision["decision_state"], "model_route_delivery_mode": route_decision["delivery_mode"], "action_count": len(action_queue)},
        "selected_route": selected_route,
        "ab_route_comparison": ab_routes,
        "rag_summary": {"coverage_score": rag["summary"]["coverage_score"], "retrieval_probe_count": rag["summary"]["retrieval_probe_count"], "grounding_gap_count": rag["summary"]["grounding_gap_count"], "maintenance_item_count": rag["summary"].get("maintenance_item_count", 0), "storage_policy": rag["summary"]["storage_policy"]},
        "release_summary": release["summary"],
        "model_route_decision": route_decision,
        "coworker_quality_ladder": coworker_ladder,
        "quality_gates": quality_gates,
        "action_queue": action_queue,
        "charts": [{"chart_id": "ai-assurance-scorecard", "title": "AI Assurance Scorecard", "type": "bar", "unit": "percent", "series": [{"label": "Assistant", "value": assistant_score}, {"label": "RAG", "value": rag_score}, {"label": "Model fit", "value": model_score}, {"label": "Release", "value": release_score}]}],
        "evidence_links": [{"label": "Assistant workbench", "endpoint": "/api/assistant/workbench"}, {"label": "Coworker quality", "endpoint": "/api/assistant/coworker-quality"}, {"label": "Assistant quality", "endpoint": "/api/assistant/quality-report"}, {"label": "RAG quality", "endpoint": "/api/rag/quality-console"}, {"label": "Model benchmarks", "endpoint": "/api/ai/model-benchmarks"}, {"label": "Release evidence", "endpoint": "/api/release/evidence-console"}],
    }


def assistant_decision_brief(
    store: CoreStore,
    production: bool,
    query: str = "current operational decision",
    top_k: int = 3,
) -> dict[str, Any]:
    """Return a input-redacted operational decision brief for the assistant route."""

    clean_query = query.strip() or "current operational decision"
    top_k = max(1, min(top_k, 5))
    summary = operation_summary(store, production)
    quality = assistant_quality_report(store, production)
    route = ai_routing_status(store)
    model_matrix = ai_model_benchmark_matrix(store, production)
    adr = architecture_decision_register(store)
    rag = rag_search(store, clean_query, top_k=top_k)
    agents = store.list_dashboard_agents()
    primary_agent = next(
        (agent for agent in agents if agent["agent_id"] == "ai_diagnosis_agent"),
        agents[0],
    )
    agent_route = build_agent_route(agents, primary_agent)
    a2a_trace = build_a2a_trace(agents, agent_route)
    counters = summary["counters"]
    risk = summary["current_risk"]
    pending_recovery = int(counters["pending_recovery"])
    open_alerts = int(counters["open_alerts"])
    priority = "critical" if pending_recovery or risk["severity"] == "critical" else (
        "high" if open_alerts else "normal"
    )
    risk_register = [
        {
            "risk_id": "current-risk",
            "level": priority,
            "state": risk["severity"],
            "evidence": risk["label"],
            "owner_agent": "monitoring_alert_agent",
            "control": "/api/operations/summary",
        },
        {
            "risk_id": "assistant-runtime",
            "level": "review_required"
            if route["active_route"] != "grounded_fallback" and not route["runtime_allowed"]
            else "controlled",
            "state": route["active_route"],
            "evidence": "Provider runtime remains gated by policy, credential, identity, grounding, and eval controls.",
            "owner_agent": "ai_diagnosis_agent",
            "control": "/api/ai/routing",
        },
        {
            "risk_id": "human-approval",
            "level": "required" if pending_recovery else "clear",
            "state": "hitl_required" if pending_recovery else "no_pending_recovery",
            "evidence": "Recovery execution is never performed by the assistant route.",
            "owner_agent": "alert_recovery_agent",
            "control": "/api/recovery/proposals",
        },
    ]
    model_tasks = model_matrix["tasks"][:4]
    accepted_adr_items = [
        item for item in adr["items"] if item.get("status") == "accepted"
    ]
    matching_adr_items = [
        item for item in accepted_adr_items if item.get("owner_agent_id") in agent_route
    ]
    runtime_ready = bool(counters["devices"] and counters["telemetry"])
    risk_clear = not pending_recovery and not open_alerts
    qa_evidence_ready = bool(store.list_ai_eval_runs()) and bool(
        store.list_evidence_findings()
    )
    decision_quality_score = 100 if runtime_ready and risk_clear else quality["score"]
    runtime_score = 100 if runtime_ready and risk_clear else (85 if runtime_ready else 60)
    rag_score = 100 if rag["matches"] or runtime_ready else 75
    route_score = 100 if route["active_route"] == "grounded_fallback" else int(
        model_matrix["summary"]["average_fit_score"]
    )
    risk_penalty = 0 if risk_clear else (8 if open_alerts else 12)
    readiness_score = round(
        max(0, decision_quality_score + runtime_score + rag_score + route_score - risk_penalty)
        / 4,
        1,
    )
    runtime_record_count = sum(
        int(counters[key])
        for key in ("devices", "telemetry", "open_alerts", "pending_recovery")
    )
    executive_brief = (
        f"{summary['operational_state']} with priority {priority}. "
        f"Recommended action: {summary['next_actions'][0]}"
    )
    charts = [
        {
            "chart_id": "assistant-decision-brief",
            "title": "Assistant Decision Brief",
            "type": "bar",
            "unit": "score",
            "series": [
                {"label": "Decision readiness", "value": readiness_score},
                {"label": "Assistant quality", "value": quality["score"]},
                {
                    "label": "Model fit",
                    "value": model_matrix["summary"]["average_fit_score"],
                },
                {"label": "Phase readiness", "value": summary["phase_readiness_score"]},
            ],
        },
        {
            "chart_id": "decision-risk-load",
            "title": "Decision Risk Load",
            "type": "bar",
            "unit": "records",
            "series": [
                {"label": "Open alerts", "value": open_alerts},
                {"label": "Pending recovery", "value": pending_recovery},
                {"label": "Runtime records", "value": runtime_record_count},
                {"label": "RAG matches", "value": len(rag["matches"])},
            ],
        },
    ]
    evidence_links = [
        {"label": "Operations summary", "endpoint": "/api/operations/summary"},
        {"label": "Command center", "endpoint": "/api/operations/command-center"},
        {"label": "Assistant quality", "endpoint": "/api/assistant/quality-report"},
        {"label": "Model benchmark matrix", "endpoint": "/api/ai/model-benchmarks"},
        {"label": "RAG search", "endpoint": "/api/rag/search"},
        {"label": "ADR register", "endpoint": "/api/architecture/adr"},
    ]
    return {
        "status": "ready" if not quality["blockers"] else "review_required",
        "version": __version__,
        "prepared_for": CUSTOMER_NAME,
        "prepared_by": CONTRACTOR_NAME,
        "decision_id": f"assistant-brief-{utc_now()[:10]}",
        "generated_at": utc_now(),
        "query_hash": hashlib.sha256(clean_query.encode("utf-8")).hexdigest()[:16],
        "executive_brief": executive_brief,
        "recommended_action": summary["next_actions"][0],
        "priority": priority,
        "confidence": "decision_grade_bounded" if runtime_record_count else "preview_no_runtime_records",
        "summary": {
            "decision_readiness_score": readiness_score,
            "operational_state": summary["operational_state"],
            "assistant_quality_score": quality["score"],
            "decision_quality_score": decision_quality_score,
            "qa_evidence_ready": qa_evidence_ready,
            "model_fit_score": model_matrix["summary"]["average_fit_score"],
            "runtime_record_count": runtime_record_count,
            "rag_match_count": len(rag["matches"]),
        },
        "decision_context": {
            "active_risk": risk,
            "command_state": {
                "operational_state": summary["operational_state"],
                "phase_readiness_score": summary["phase_readiness_score"],
                "current_risk": risk["label"],
                "next_action": summary["next_actions"][0],
            },
            "top_command_cards": [
                {
                    "area": "Operations command",
                    "agent_id": "operations_coordinator",
                    "kpi": f"{summary['phase_readiness_score']}% readiness",
                    "primary_endpoint": "/api/operations/summary",
                    "next_action": summary["next_actions"][0],
                },
                {
                    "area": "Alert and recovery",
                    "agent_id": "alert_recovery_agent",
                    "kpi": f"{open_alerts} open alert(s), {pending_recovery} pending",
                    "primary_endpoint": "/api/recovery/proposals",
                    "next_action": "Review open alerts and keep recovery actions human-approved.",
                },
                {
                    "area": "Assistant and RAG",
                    "agent_id": "ai_diagnosis_agent",
                    "kpi": route["active_route"],
                    "primary_endpoint": "/api/chat",
                    "next_action": "Use grounded diagnosis with RAG evidence and no raw operator input storage.",
                },
            ],
            "quality_recommendations": quality["recommendations"][:4],
        },
        "risk_register": risk_register,
        "agent_route": agent_route,
        "a2a_trace": a2a_trace,
        "adr_alignment": {
            "accepted_count": len(accepted_adr_items),
            "route_aligned_count": len(matching_adr_items),
            "standards": adr["standards"],
            "items": [
                {
                    "adr_id": item["adr_id"],
                    "title": item["title"],
                    "owner_agent_id": item["owner_agent_id"],
                    "acceptance_gates": item["acceptance_gates"],
                }
                for item in matching_adr_items[:4]
            ],
        },
        "model_routing": {
            "active_route": route["active_route"],
            "active_profile": route["active_analysis_profile"]["profile_id"],
            "runtime_allowed": route["runtime_allowed"],
            "task_recommendations": [
                {
                    "task_id": item["task_id"],
                    "label": item["label"],
                    "recommended_route": item["recommended_route"],
                    "fit_score": item["fit_score"],
                    "status": item["status"],
                }
                for item in model_tasks
            ],
        },
        "grounding": {
            "runtime": summary["counters"],
            "rag_mode": rag["rag_mode"],
            "knowledge_matches": rag["matches"],
            "evidence_links": rag["evidence_links"],
        },
        "hitl": {
            "required": True,
            "reason": "Recovery actions and production decisions require human approval.",
            "pending_recovery": pending_recovery,
            "approval_endpoint": "/api/recovery/proposals",
        },
        "next_actions": summary["next_actions"] + quality["recommendations"][:2],
        "charts": charts,
        "evidence_links": evidence_links,
        "privacy": {
            "prompt_storage": "not_stored",
            "query_storage": "sha256_16_hash_only",
            "provider_call": "not_performed_by_decision_brief",
            "secret_exposure": "none",
            "customer_delivery_safe": "yes",
        },
    }


def assistant_continuity_brief(
    store: CoreStore,
    production: bool,
    *,
    decision: dict[str, Any],
    quality: dict[str, Any],
    session: dict[str, Any],
    tool_proposals: list[dict[str, Any]],
    action_panel: list[dict[str, Any]],
) -> dict[str, Any]:
    """Return a compact input-redacted coworker handoff for the next operator step."""

    ledger = assistant_interaction_ledger(store)
    action_board = evidence_action_board(store, production)
    board_actions = action_board.get("actions", [])[:3]
    top_actions = board_actions or action_panel[:3]
    normalized_actions = []
    for item in top_actions:
        normalized_actions.append(
            {
                "action_id": item.get("action_id", "assistant-next-action"),
                "priority": item.get("priority", decision.get("priority", "P2")),
                "status": item.get("status", "ready"),
                "owner_agent_id": item.get("owner_agent_id", "ai_diagnosis_agent"),
                "action": item.get("action", "Review assistant evidence and choose the next controlled action."),
                "evidence_label": item.get("evidence_label", "Operations evidence"),
                "evidence_endpoint": item.get("evidence_endpoint", "/api/assistant/workbench"),
                "acceptance_gate": item.get("acceptance_gate", "grounded_evidence_and_hitl_review"),
                "a2a_next_hop": item.get("a2a_next_hop", "operations_coordinator"),
            }
        )
    prepared_count = sum(1 for item in tool_proposals if item.get("status") == "prepared")
    awaiting_count = sum(
        1
        for item in tool_proposals
        if item.get("status") == "prepared"
        and item.get("execution_state") in {"awaiting_human_approval", "blocked_until_human_approval"}
    )
    owner_action = normalized_actions[0] if normalized_actions else {
        "owner_agent_id": "ai_diagnosis_agent",
        "a2a_next_hop": "operations_coordinator",
        "acceptance_gate": "grounded_evidence_and_hitl_review",
        "priority": decision.get("priority", "P2"),
        "action": "Load runtime evidence before proposing operational recovery.",
        "evidence_endpoint": "/api/operations/summary",
        "evidence_label": "Operations summary",
    }
    blockers = []
    if quality.get("blockers"):
        blockers.extend(quality.get("blockers", [])[:2])
    if prepared_count:
        blockers.append("prepared_action_waits_for_human_approval")
    if decision.get("grounding", {}).get("runtime_record_count", 0) == 0:
        blockers.append("runtime_records_missing")
    state = "handoff_ready" if normalized_actions else "pilot_setup_required"
    if blockers:
        state = "review_required"
    return {
        "status": state,
        "brief": f"{owner_action['owner_agent_id']} owns the next step; {owner_action['action']}",
        "session_state": {
            "session_id": session["session_id"],
            "turn_state": session["turn_state"],
            "prompt_storage": session["storage_policy"],
            "raw_prompt_stored": False,
            "answer_text_stored": False,
            "interaction_count": ledger["summary"]["total"],
            "prepared_proposal_count": prepared_count,
            "awaiting_approval_count": awaiting_count,
        },
        "owner_handoff": {
            "owner_agent_id": owner_action["owner_agent_id"],
            "a2a_next_hop": owner_action["a2a_next_hop"],
            "acceptance_gate": owner_action["acceptance_gate"],
            "priority": owner_action["priority"],
            "evidence_label": owner_action["evidence_label"],
            "evidence_endpoint": owner_action["evidence_endpoint"],
        },
        "top_actions": normalized_actions,
        "blockers": blockers[:4],
        "safe_follow_up_prompts": [
            "Show the current operational risk and the supporting evidence.",
            "Prepare the next approval-gated recovery action.",
            "Summarize which agent owns the next blocker.",
        ],
        "charts": [
            {
                "chart_id": "assistant-continuity-state",
                "title": "Assistant Continuity State",
                "type": "bar",
                "unit": "count",
                "series": [
                    {"label": "Interactions", "value": ledger["summary"]["total"]},
                    {"label": "Prepared", "value": prepared_count},
                    {"label": "Awaiting approval", "value": awaiting_count},
                    {"label": "Top actions", "value": len(normalized_actions)},
                ],
            }
        ],
        "privacy": {
            "raw_prompt_storage": "forbidden",
            "answer_storage": "not_stored",
            "provider_payload_storage": "not_stored",
            "tool_execution": "not_performed_by_workbench",
            "customer_delivery_safe": "yes",
        },
    }


def assistant_workbench(
    store: CoreStore,
    production: bool,
    query: str = "current operational decision",
    top_k: int = 3,
) -> dict[str, Any]:
    """Return an input-redacted enterprise assistant workbench package."""

    clean_query = query.strip() or "current operational decision"
    decision = assistant_decision_brief(store, production, clean_query, top_k=top_k)
    quality = assistant_quality_report(store, production)
    route = ai_routing_status(store)
    diagnosis = grounded_diagnosis(store, clean_query, allow_provider_runtime=False)
    diagnosis.answer_review = assistant_answer_review(diagnosis, clean_query)
    diagnosis.coworker_package = assistant_coworker_package(
        store, clean_query, diagnosis, 0
    )
    diagnosis.session = assistant_session_state(
        message=clean_query,
        requested_session_id=None,
        client_message_id=None,
        parent_message_id=None,
        response=diagnosis,
        interaction=None,
        latency_ms=0,
    )
    diagnosis.tool_proposals = assistant_apply_persisted_tool_state(
        store, assistant_tool_proposals(diagnosis, diagnosis.session), diagnosis.session
    )
    diagnosis.coworker_package["session"] = diagnosis.session
    diagnosis.coworker_package["tool_proposals"] = diagnosis.tool_proposals
    action_panel = []
    for index, action in enumerate(diagnosis.next_actions[:5], start=1):
        action_panel.append(
            {
                "action_id": f"assistant-action-{index:02d}",
                "priority": decision["priority"],
                "owner_agent_id": "ai_diagnosis_agent" if index == 1 else "operations_coordinator",
                "action": action,
                "evidence_endpoint": "/api/chat" if index == 1 else "/api/operations/summary",
                "acceptance_gate": "grounded_evidence_and_hitl_review",
                "a2a_next_hop": "alert_recovery_agent" if decision["hitl"]["required"] else "reporting_compliance_agent",
            }
        )
    continuity_brief = assistant_continuity_brief(
        store,
        production,
        decision=decision,
        quality=quality,
        session=diagnosis.session,
        tool_proposals=diagnosis.tool_proposals,
        action_panel=action_panel,
    )
    charts = [
        {
            "chart_id": "assistant-workbench-readiness",
            "title": "Assistant Workbench Readiness",
            "type": "bar",
            "unit": "score",
            "series": [
                {"label": "Assistant quality", "value": quality["score"]},
                {"label": "Decision readiness", "value": decision["summary"]["decision_readiness_score"]},
                {"label": "Model fit", "value": decision["summary"]["model_fit_score"]},
                {"label": "RAG matches", "value": decision["summary"]["rag_match_count"]},
            ],
        },
        *continuity_brief["charts"],
    ]
    return {
        "status": "ready" if not quality["blockers"] else "review_required",
        "version": __version__,
        "prepared_for": CUSTOMER_NAME,
        "prepared_by": CONTRACTOR_NAME,
        "generated_at": utc_now(),
        "query_hash": hashlib.sha256(clean_query.encode("utf-8")).hexdigest()[:16],
        "summary": {
            "copilot_mode": "bounded_contract_copilot",
            "assistant_quality_score": quality["score"],
            "decision_readiness_score": decision["summary"]["decision_readiness_score"],
            "answer_review_score": diagnosis.answer_review["score"],
            "active_route": route["active_route"],
            "active_profile": route["active_analysis_profile"]["profile_id"],
            "hitl_required": decision["hitl"]["required"],
            "action_count": len(action_panel),
            "prepared_proposal_count": sum(
                1 for item in diagnosis.tool_proposals if item.get("status") == "prepared"
            ),
            "continuity_status": continuity_brief["status"],
            "open_action_count": len(continuity_brief["top_actions"]),
        },
        "prompt_contract": {
            "raw_prompt_storage": "forbidden",
            "customer_delivery": "input_redacted",
            "managed_prompt_ids": [
                "assistant.ops.diagnosis",
                "assistant.ops.evidence_router",
                "assistant.ops.hitl_guardrail",
            ],
            "admin_surface": "/api/admin/ai/analysis-profiles",
            "runtime_policy": "/api/admin/ai/provider-policy",
        },
        "response_package": {
            "status": diagnosis.status,
            "answer": diagnosis.answer,
            "assistant_plan": diagnosis.assistant_plan,
            "evidence_links": diagnosis.evidence_links,
            "agent_route": diagnosis.agent_route,
            "a2a_trace": diagnosis.a2a_trace,
            "next_actions": diagnosis.next_actions,
            "requires_human_approval": diagnosis.requires_human_approval,
            "confidence": diagnosis.confidence,
            "coworker_package": diagnosis.coworker_package,
            "session": diagnosis.session,
            "tool_proposals": diagnosis.tool_proposals,
            "answer_review": diagnosis.answer_review,
            "feedback_endpoint": "/api/assistant/interactions/{interaction_id}/feedback",
        },
        "coworker_package": diagnosis.coworker_package,
        "session": diagnosis.session,
        "tool_proposals": diagnosis.tool_proposals,
        "answer_review": diagnosis.answer_review,
        "model_routing": decision["model_routing"],
        "rag_grounding": {
            "rag_mode": decision["grounding"]["rag_mode"],
            "knowledge_matches": decision["grounding"]["knowledge_matches"],
            "evidence_links": decision["grounding"]["evidence_links"],
        },
        "agent_orchestration": {
            "owner_agent_id": "ai_diagnosis_agent",
            "agent_route": diagnosis.agent_route,
            "a2a_trace": diagnosis.a2a_trace,
            "adr_alignment": decision["adr_alignment"],
        },
        "continuity_brief": continuity_brief,
        "action_panel": action_panel,
        "quality_gates": quality["quality_gates"],
        "charts": charts,
        "evidence_links": [
            {"label": "Assistant workbench", "endpoint": "/api/assistant/workbench"},
            {"label": "Assistant quality", "endpoint": "/api/assistant/quality-report"},
            {"label": "Decision brief", "endpoint": "/api/assistant/decision-brief"},
            {"label": "RAG search", "endpoint": "/api/rag/search"},
            {"label": "Agent tasks", "endpoint": "/api/agents/tasks"},
        ],
        "privacy": {
            "query_storage": "sha256_16_hash_only",
            "prompt_storage": "not_stored",
            "provider_call": "not_performed_by_workbench",
            "secret_exposure": "none",
        },
    }


def public_assistant_action_dto(
    action: dict[str, Any], index: int
) -> dict[str, Any]:
    """Allowlist one public operator action without internal handoff metadata."""

    endpoint = str(action.get("evidence_endpoint") or "")
    if endpoint not in PUBLIC_ASSISTANT_EVIDENCE_ENDPOINTS:
        endpoint = "/api/operations/summary"
    return {
        "action_id": str(action.get("action_id") or f"assistant-action-{index:02d}"),
        "priority": str(action.get("priority") or "P2"),
        "owner_agent_id": "operator",
        "action": str(action.get("action") or "Review the current operational status."),
        "evidence_label": str(action.get("evidence_label") or "Operational evidence"),
        "evidence_endpoint": endpoint,
    }


def public_assistant_workbench(package: dict[str, Any]) -> dict[str, Any]:
    """Build the explicit customer-facing assistant workbench DTO."""

    summary = package.get("summary", {})
    response_package = package.get("response_package", {})
    answer_review = response_package.get("answer_review") or package.get(
        "answer_review", {}
    )
    continuity = package.get("continuity_brief", {})
    continuity_actions = [
        public_assistant_action_dto(action, index)
        for index, action in enumerate(continuity.get("top_actions", [])[:3], start=1)
    ]
    panel_actions = [
        public_assistant_action_dto(action, index)
        for index, action in enumerate(package.get("action_panel", [])[:3], start=1)
    ]
    return {
        "status": package["status"],
        "version": package["version"],
        "prepared_for": package["prepared_for"],
        "prepared_by": package["prepared_by"],
        "generated_at": package["generated_at"],
        "summary": {
            "assistant_quality_score": summary.get("assistant_quality_score", 0),
            "decision_readiness_score": summary.get("decision_readiness_score", 0),
            "active_route": str(summary.get("active_route") or "grounded_fallback"),
        },
        "response_package": {
            "status": str(response_package.get("status") or "review_required"),
            "answer": str(
                response_package.get("answer")
                or "No operational diagnosis is available yet."
            ),
            "answer_review": {
                "score": answer_review.get("score", 0),
                "status": str(answer_review.get("status") or "review_required"),
            },
        },
        "continuity_brief": {
            "status": str(continuity.get("status") or "review_required"),
            "top_actions": continuity_actions,
        },
        "action_panel": panel_actions,
        "quality_gates": [
            {
                "gate": "runtime_grounding",
                "status": str(gate.get("status") or "review_required"),
            }
            for gate in package.get("quality_gates", [])
            if gate.get("gate") == "runtime_grounding"
        ][:2],
        "charts": [
            public_chart_dto(chart)
            for chart in package.get("charts", [])
            if chart.get("chart_id") in PUBLIC_ASSISTANT_CHART_IDS
        ][:2],
    }


def grounded_diagnosis(
    store: CoreStore,
    message: str,
    actor: str | None = None,
    allow_provider_runtime: bool = True,
) -> ChatResponse:
    """Return diagnosis text grounded only in current runtime records."""

    route = ai_routing_status(store)
    policy = store.get_ai_provider_policy()
    agents = store.list_dashboard_agents()
    preferred_agent = (
        "ai_diagnosis_agent"
        if any(
            agent["agent_id"] == "ai_diagnosis_agent" and agent["enabled"]
            for agent in agents
        )
        else None
    )
    primary_agent = choose_agent_for_goal(agents, message, preferred_agent)
    agent_route = build_agent_route(agents, primary_agent)
    a2a_trace = build_a2a_trace(agents, agent_route)
    alerts = store.list_rows("alerts")
    telemetry = store.list_rows("telemetry")
    proposals = store.list_rows("recovery_proposals")
    grounding: list[dict[str, Any]] = []
    knowledge_grounding = rag_grounding_for_message(store, message)
    if alerts:
        latest_alert = alerts[-1]
        grounding.append(
            {
                "type": "alert",
                "id": latest_alert["alert_id"],
                "summary": f"{latest_alert['severity']} alert on {latest_alert['device_id']}",
            }
        )
    if telemetry:
        latest_telemetry = telemetry[-1]
        grounding.append(
            {
                "type": "telemetry",
                "id": latest_telemetry["telemetry_id"],
                "summary": f"{latest_telemetry['metric']}={latest_telemetry['value']}",
            }
        )
    if proposals:
        latest_proposal = proposals[-1]
        grounding.append(
            {
                "type": "recovery_proposal",
                "id": latest_proposal["proposal_id"],
                "summary": latest_proposal["status"],
            }
        )
    if not grounding:
        return ChatResponse(
            answer=compose_grounded_coworker_answer(
                message=message,
                grounding=grounding,
                knowledge_grounding=knowledge_grounding,
                agent_route=agent_route,
                provider_status="waiting_for_runtime_records",
            ),
            route=route,
            grounding=grounding,
            knowledge_grounding=knowledge_grounding,
            provider_runtime={
                "status": "skipped",
                "reason": "no_grounding_records",
                "provider": policy["provider"],
                "model": policy["model"],
            },
            assistant_plan=assistant_plan(
                grounding=grounding,
                route=agent_route,
                provider_status="waiting_for_runtime_records",
            ),
            evidence_links=assistant_evidence_links(grounding)
            + [
                {
                    "type": "rag_knowledge",
                    "id": str(item["id"]),
                    "endpoint": item["endpoint"],
                }
                for item in knowledge_grounding
            ],
            agent_route=agent_route,
            a2a_trace=a2a_trace,
            next_actions=assistant_next_actions(
                grounding, "waiting_for_runtime_records"
            ),
            requires_human_approval=True,
            confidence="low_no_runtime_records",
        )
    chat_gate = route.get("provider_chat_gate") or provider_chat_gate(policy, store)
    if (
        allow_provider_runtime
        and route["active_route"] in {"cloud_model", "local_model"}
        and model_runtime_allowed(policy, store)
        and chat_gate["ready"]
    ):
        if actor is None:
            return ChatResponse(
                status="runtime_operator_required",
                answer=(
                    "A configured model route is available, but provider execution "
                    "requires an authenticated operator token. Grounded fallback is "
                    "available from current runtime records."
                ),
                route=route,
                grounding=grounding,
                knowledge_grounding=knowledge_grounding,
                provider_runtime={
                    "status": "skipped",
                    "reason": "operator_required",
                    "provider": policy["provider"],
                    "model": policy["model"],
                },
                assistant_plan=assistant_plan(
                    grounding=grounding,
                    route=agent_route,
                    provider_status="operator_required",
                ),
                evidence_links=assistant_evidence_links(grounding)
                + [
                    {
                        "type": "rag_knowledge",
                        "id": str(item["id"]),
                        "endpoint": item["endpoint"],
                    }
                    for item in knowledge_grounding
                ],
                agent_route=agent_route,
                a2a_trace=a2a_trace,
                next_actions=assistant_next_actions(
                    grounding, "runtime_operator_required"
                ),
                requires_human_approval=True,
                confidence="medium_grounded_runtime_operator_required",
            )
        prompt = build_model_prompt(
            message=message, grounding=grounding, policy=policy
        )
        provider_result = invoke_model_provider(policy, prompt, store)
        usage = provider_result.get("usage") or {}
        if usage:
            store.add_model_token_usage(
                provider=provider_result["provider"],
                model=provider_result["model"],
                input_tokens=int(usage.get("input_tokens") or 0),
                output_tokens=int(usage.get("output_tokens") or 0),
                source=str(usage.get("source") or "estimated"),
                actor=actor or "assistant-runtime",
            )
        if provider_result["status"] == "completed":
            answer_acceptance = provider_answer_acceptance_gate(
                provider_result["answer"],
                grounding,
                knowledge_grounding,
            )
            if answer_acceptance["status"] != "ready":
                provider_runtime = {
                    key: value
                    for key, value in provider_result.items()
                    if key != "answer"
                }
                provider_runtime.update(
                    {
                        "status": "rejected",
                        "reason": "provider_answer_acceptance_failed",
                        "answer_acceptance": answer_acceptance,
                    }
                )
                store.add_audit_event(
                    event_type="ai.provider_runtime.rejected",
                    subject_id=policy["provider"],
                    actor=actor,
                    detail=json.dumps(
                        {
                            "provider": provider_result["provider"],
                            "model": provider_result["model"],
                            "status": "rejected",
                            "blocking_gates": answer_acceptance["blocking_gates"],
                        },
                        separators=(",", ":"),
                    ),
                )
                return ChatResponse(
                    status="grounded_fallback",
                    answer=compose_grounded_coworker_answer(
                        message=message,
                        grounding=grounding,
                        knowledge_grounding=knowledge_grounding,
                        agent_route=agent_route,
                        provider_status="provider_answer_rejected",
                    ),
                    route=route,
                    grounding=grounding,
                    knowledge_grounding=knowledge_grounding,
                    provider_runtime=provider_runtime,
                    assistant_plan=assistant_plan(
                        grounding=grounding,
                        route=agent_route,
                        provider_status="provider_answer_rejected",
                    ),
                    evidence_links=assistant_evidence_links(grounding)
                    + [
                        {
                            "type": "rag_knowledge",
                            "id": str(item["id"]),
                            "endpoint": item["endpoint"],
                        }
                        for item in knowledge_grounding
                    ],
                    agent_route=agent_route,
                    a2a_trace=a2a_trace,
                    next_actions=assistant_next_actions(
                        grounding, "provider_answer_rejected"
                    ),
                    requires_human_approval=True,
                    confidence="medium_grounded_provider_answer_rejected",
                )
            store.add_audit_event(
                event_type="ai.provider_runtime.completed",
                subject_id=policy["provider"],
                actor=actor,
                detail=json.dumps(
                    {
                        "provider": provider_result["provider"],
                        "model": provider_result["model"],
                        "status": provider_result["status"],
                        "answer_acceptance": answer_acceptance["status"],
                    },
                    separators=(",", ":"),
                ),
            )
            provider_runtime = {
                key: value for key, value in provider_result.items() if key != "answer"
            }
            provider_runtime["answer_acceptance"] = answer_acceptance
            return ChatResponse(
                status="provider_runtime",
                answer=append_evidence_footer_to_provider_answer(
                    provider_result["answer"],
                    grounding=grounding,
                    knowledge_grounding=knowledge_grounding,
                    agent_route=agent_route,
                ),
                route=route,
                grounding=grounding,
                knowledge_grounding=knowledge_grounding,
                provider_runtime=provider_runtime,
                assistant_plan=assistant_plan(
                    grounding=grounding,
                    route=agent_route,
                    provider_status="provider_runtime",
                ),
                evidence_links=assistant_evidence_links(grounding)
                + [
                    {
                        "type": "rag_knowledge",
                        "id": str(item["id"]),
                        "endpoint": item["endpoint"],
                    }
                    for item in knowledge_grounding
                ],
                agent_route=agent_route,
                a2a_trace=a2a_trace,
                next_actions=assistant_next_actions(grounding, "provider_runtime"),
                requires_human_approval=True,
                confidence="high_grounded_provider_runtime",
            )
        store.add_audit_event(
            event_type="ai.provider_runtime.failed",
            subject_id=policy["provider"],
            actor=actor,
            detail=json.dumps(
                {
                    "provider": provider_result.get("provider", policy["provider"]),
                    "model": provider_result.get("model", policy["model"]),
                    "status": provider_result.get("status", "failed"),
                    "provider_error": provider_result.get("error"),
                },
                separators=(",", ":"),
            ),
        )
    provider_status = "grounded_fallback"
    provider_skip_reason = "runtime_not_allowed_or_failed"
    if (
        allow_provider_runtime
        and route["active_route"] in {"cloud_model", "local_model"}
        and model_runtime_allowed(policy, store)
        and not chat_gate["ready"]
    ):
        provider_status = "provider_chat_gate_blocked"
        provider_skip_reason = "provider_chat_gate_blocked"
    return ChatResponse(
        status="grounded_fallback",
        answer=compose_grounded_coworker_answer(
            message=message,
            grounding=grounding,
            knowledge_grounding=knowledge_grounding,
            agent_route=agent_route,
            provider_status=provider_status,
        ),
        route=route,
        grounding=grounding,
        knowledge_grounding=knowledge_grounding,
        provider_runtime={
            "status": "skipped",
            "reason": provider_skip_reason,
            "provider": policy["provider"],
            "model": policy["model"],
            "chat_gate": chat_gate,
        },
        assistant_plan=assistant_plan(
            grounding=grounding,
            route=agent_route,
            provider_status=provider_status,
        ),
        evidence_links=assistant_evidence_links(grounding)
        + [
            {
                "type": "rag_knowledge",
                "id": str(item["id"]),
                "endpoint": item["endpoint"],
            }
            for item in knowledge_grounding
        ],
        agent_route=agent_route,
        a2a_trace=a2a_trace,
        next_actions=assistant_next_actions(grounding, provider_status),
        requires_human_approval=True,
        confidence=(
            "medium_grounded_provider_gate_pending"
            if provider_status == "provider_chat_gate_blocked"
            else "medium_grounded_fallback"
        ),
    )


def assistant_qa_challenge_cases(
    store: CoreStore, *, rounds: int = 60, production: bool
) -> list[dict[str, Any]]:
    """Run bounded input-redacted assistant Q/A challenge cases through the real route."""

    del production
    categories = [
        ("operations", "Review operational state", "operations_coordinator"),
        ("anomaly", "Review anomaly signal", "ai_diagnosis_agent"),
        ("recovery", "Review recovery approval", "alert_recovery_agent"),
        ("reporting", "Review reporting evidence", "reporting_compliance_agent"),
        ("rag", "Review knowledge grounding", "ai_diagnosis_agent"),
        ("a2a", "Review agent handoff", "admin_governance_agent"),
        ("security", "Review access boundary", "admin_governance_agent"),
        ("ui_quality", "Review cockpit usability", "ui_ux_experience_auditor"),
    ]
    cases: list[dict[str, Any]] = []
    for index in range(rounds):
        category, safe_label, owner_agent_id = categories[index % len(categories)]
        message = f"{safe_label} for release evidence round {index + 1}."
        diagnosis = grounded_diagnosis(
            store,
            message,
            actor=None,
            allow_provider_runtime=False,
        )
        status = "pass" if diagnosis.route and diagnosis.a2a_trace else "fail"
        cases.append(
            {
                "case_id": f"assistant-qa-q{index + 1:03d}",
                "category": category,
                "safe_label": safe_label,
                "status": status,
                "owner_agent_id": owner_agent_id,
                "route": diagnosis.agent_route,
                "active_route": diagnosis.route["active_route"],
                "response_status": diagnosis.status,
                "confidence": diagnosis.confidence,
                "grounding_count": len(diagnosis.grounding),
                "knowledge_count": len(diagnosis.knowledge_grounding),
                "a2a_trace_count": len(diagnosis.a2a_trace),
                "evidence_count": len(diagnosis.evidence_links),
                "provider_call": False,
                "prompt_hash": hashlib.sha256(message.encode("utf-8")).hexdigest()[:16],
                "prompt_storage": "hash_only",
                "answer_storage": "not_stored",
                "latency_budget_ms": 900,
            }
        )
    return cases


def run_assistant_qa_challenge(
    store: CoreStore, *, actor: str, production: bool, rounds: int = 60
) -> dict[str, Any]:
    """Store a 60-round assistant Q/A challenge without provider calls or raw operator inputs."""

    cases = assistant_qa_challenge_cases(store, rounds=rounds, production=production)
    result = store.add_ai_eval_run(cases=cases, actor=actor)
    store.add_evidence_finding(
        source="assistant_qa_challenge",
        subject_id=result["run_id"],
        outcome="passed" if result["passed"] else "failed",
        severity="info" if result["passed"] else "review_required",
        evidence=(
            f"{result['case_count']} input-redacted assistant Q/A cases; "
            f"{result['provider_calls']} provider calls; score {result['score']}."
        ),
        lesson="Keep assistant Q/A evaluation stored as hash-only cases with provider calls disabled unless explicitly approved.",
    )
    return result


def run_ai_eval_suite(
    store: CoreStore, *, actor: str, production: bool
) -> dict[str, Any]:
    """Run local quality checks against the real assistant and agent route."""

    route = ai_routing_status(store)
    profiles = store.list_ai_analysis_profiles()
    agents = store.list_dashboard_agents()
    alert_agent = choose_agent_for_goal(
        agents, "Review current alert risk and recovery status.", None
    )
    alert_route = build_agent_route(agents, alert_agent)
    trace = build_a2a_trace(agents, alert_route)
    reports = dashboard_report_package(store, production)
    diagnosis = grounded_diagnosis(store, "What is the current operational risk?")
    summary = operation_summary(store, production)
    cases = [
        {
            "case_id": "provider-policy-visible",
            "status": "pass" if "provider_policy" in route else "fail",
            "evidence": "AI routing returns provider policy without credential values.",
        },
        {
            "case_id": "provider-runtime-gateway",
            "status": "pass"
            if (
                route["provider_policy"]["runtime_enabled"]
                in {True, False}
                and route["runtime_allowed"] in {True, False}
            )
            else "fail",
            "evidence": (
                "Provider runtime is explicit, credential-safe, and separate from "
                "the grounded fallback route."
            ),
        },
        {
            "case_id": "analysis-profile-visible",
            "status": "pass"
            if profiles["active_profile"]["routing_layer"]
            and profiles["active_profile"]["answer_layer"]
            else "fail",
            "evidence": (
                "Active analysis profile separates routing/reasoning from answer generation."
            ),
        },
        {
            "case_id": "grounded-diagnosis-boundary",
            "status": "pass" if diagnosis.route and diagnosis.grounding is not None else "fail",
            "evidence": f"Diagnosis route is {diagnosis.route['active_route']}.",
        },
        {
            "case_id": "a2a-route-trace",
            "status": "pass"
            if "operations_coordinator" in alert_route and len(trace) >= 2
            else "fail",
            "evidence": f"Route uses {len(alert_route)} agent node(s).",
        },
        {
            "case_id": "human-approval-gate",
            "status": "pass" if any(item["approval_required"] for item in trace) else "fail",
            "evidence": "A2A trace keeps approval-required agents explicit.",
        },
        {
            "case_id": "report-evidence-complete",
            "status": "pass"
            if {
                "agent-orchestration-map",
                "agent-task-execution",
            }.issubset({item["report_id"] for item in reports["reports"]})
            else "fail",
            "evidence": "Dashboard report package includes agent map and task evidence.",
        },
        {
            "case_id": "operations-context-available",
            "status": "pass" if summary["next_actions"] else "fail",
            "evidence": summary["next_actions"][0] if summary["next_actions"] else "No action.",
        },
    ]
    result = store.add_ai_eval_run(cases=cases, actor=actor)
    store.add_evidence_finding(
        source="ai_eval",
        subject_id=result["run_id"],
        outcome="passed" if result["passed"] else "failed",
        severity="info" if result["passed"] else "review_required",
        evidence=(
            f"Score {result['score']} across {len(cases)} AI, A2A, routing, and evidence cases."
        ),
        lesson="Keep failing eval cases in the closed-loop findings table until the route is corrected.",
    )
    return result


def normalize_row(table: str, row: dict[str, Any]) -> dict[str, Any]:
    """Normalize SQLite values before they become public API JSON."""

    if table == "recovery_proposals" and "requires_approval" in row:
        row["requires_approval"] = bool(row["requires_approval"])
    if table == "config_profiles" and "enabled" in row:
        row["enabled"] = bool(row["enabled"])
    if table == "hardware_evidence" and "descriptor_validated" in row:
        row["descriptor_validated"] = bool(row["descriptor_validated"])
    return row


@asynccontextmanager
async def network_discovery_scan_lease(
    store: CoreStore,
    actor: str,
) -> Any:
    """Hold one expiring SQLite-backed scan lease across worker processes."""

    lease_token, retry_after = store.claim_network_discovery_lease(actor=actor)
    try:
        yield retry_after
    finally:
        if lease_token:
            try:
                store.release_network_discovery_lease(lease_token)
            except sqlite3.Error as error:  # Lease expiry remains the fail-safe.
                LOGGER.warning(
                    "network_discovery_lease_release_failed: %s",
                    type(error).__name__,
                )


def create_app(database_path: str | Path | None = None) -> FastAPI:
    """Create the AgentIoT FastAPI application."""

    explicit_database_path = database_path is not None or bool(
        os.getenv("AGENTIOT_DB_PATH", "").strip()
    )
    db_path = database_path or os.getenv("AGENTIOT_DB_PATH", DEFAULT_DB_PATH)
    database_persistence = database_persistence_state(db_path, explicit_database_path)
    store = CoreStore(db_path)
    store.cleanup_network_discovery_candidates(actor="system-retention-startup")
    store.cleanup_edge_data_retention(actor="system-retention-startup")
    production = is_production_mode()
    demo_bootstrap = bootstrap_demo_data(store)
    mqtt_broker = MQTTBrokerAdapter(store, mqtt_broker_config())

    @asynccontextmanager
    async def lifespan(app: FastAPI) -> Any:
        drift_task = asyncio.create_task(
            drift_control_review_loop(store, production),
            name="agentiot-drift-control-review",
        )
        gap_task = asyncio.create_task(
            gap_discovery_review_loop(store, production),
            name="agentiot-gap-discovery-review",
        )
        service_operations_task = asyncio.create_task(
            service_operations_loop(store, app),
            name="agentiot-service-operations",
        )
        app.state.background_tasks = {
            "drift_control": drift_task,
            "gap_discovery": gap_task,
            "service_operations": service_operations_task,
        }
        await app.state.mqtt_broker.start()
        try:
            yield
        finally:
            for task in (drift_task, gap_task, service_operations_task):
                task.cancel()
                try:
                    await task
                except asyncio.CancelledError:
                    pass
            await app.state.mqtt_broker.stop()

    app = FastAPI(
        title=PRODUCT_NAME,
        version=__version__,
        lifespan=lifespan,
        docs_url=None if production else "/docs",
        redoc_url=None if production else "/redoc",
        openapi_url=None if production else "/openapi.json",
        description=(
            "Independent clean-room AgentIoT Dashboard baseline. "
            "Prepared for GreeNovaX by IoT-AI.Tech."
        ),
    )
    app.state.store = store
    app.state.demo_bootstrap = demo_bootstrap
    app.state.mqtt_broker = mqtt_broker
    app.state.http_service_probe = probe_http_service
    app.state.network_discovery_runner = scan_private_network
    app.state.network_discovery_lock = asyncio.Lock()
    body_limit = request_body_max_bytes()
    app.state.request_body_max_bytes = body_limit
    origins = cors_allowed_origins()
    if origins:
        app.add_middleware(
            CORSMiddleware,
            allow_origins=origins,
            allow_credentials=False,
            allow_methods=["GET", "POST", "PATCH", "PUT"],
            allow_headers=[
                OPERATOR_TOKEN_HEADER,
                ADMIN_TOKEN_HEADER,
                DEVICE_INGEST_TOKEN_HEADER,
                TENANT_HEADER,
                "Authorization",
                "Content-Type",
            ],
        )
    app.add_middleware(TrustedHostMiddleware, allowed_hosts=allowed_hosts())
    app.add_middleware(RequestBodyLimitMiddleware, max_bytes=body_limit)
    app.mount("/static", StaticFiles(directory=STATIC_DIR), name="static")

    @app.middleware("http")
    async def add_security_headers(request: Request, call_next: Any) -> Any:
        query_names = {key.casefold() for key in request.query_params.keys()}
        if query_names.intersection(AUTH_QUERY_PARAMETER_NAMES):
            response = JSONResponse(
                {"detail": "Authentication material is not accepted in URLs"},
                status_code=400,
            )
        elif not cookie_state_change_has_same_origin(request):
            response = JSONResponse(
                {"detail": "Same-origin browser request required"},
                status_code=403,
            )
        else:
            tenant_id = configured_tenant_id()
            requested_tenant = request.headers.get(TENANT_HEADER, "").strip().lower()
            if requested_tenant and not secrets.compare_digest(
                requested_tenant,
                tenant_id,
            ):
                response = JSONResponse(
                    {"detail": "Tenant access denied"},
                    status_code=403,
                )
            else:
                redirect = html_login_redirect(request)
                response = redirect if redirect is not None else await call_next(request)
        for name, value in SECURITY_HEADERS.items():
            response.headers.setdefault(name, value)
        if request.url.path.startswith("/api/"):
            response.headers[TENANT_HEADER] = configured_tenant_id()
        if response.headers.get("content-type", "").startswith("text/html"):
            for name, value in HTML_NO_STORE_HEADERS.items():
                response.headers[name] = value
        return response

    @app.exception_handler(404)
    async def not_found_handler(request: Request, exc: Any) -> JSONResponse | HTMLResponse:
        """Return the dashboard shell for browser deep links, JSON for API misses."""

        accepts_html = "text/html" in request.headers.get("accept", "").lower()
        is_api_path = request.url.path.startswith("/api/")
        is_dashboard_request = request.method == "GET" and accepts_html and not is_api_path
        if is_dashboard_request:
            return secure_html_response(render_root_page(), status_code=404)
        detail = getattr(exc, "detail", "Not Found")
        return JSONResponse({"detail": detail}, status_code=404)

    def render_root_page() -> str:
        try:
            initial_state = dashboard_initial_state(
                store,
                production,
                dict(app.state.demo_bootstrap),
            )
        except Exception as exc:  # pragma: no cover - defensive UI fallback.
            LOGGER.warning("dashboard initial snapshot failed: %s", exc)
            initial_state = {
                "status": "snapshot_unavailable",
                "version": __version__,
                "prepared_for": CUSTOMER_NAME,
                "prepared_by": CONTRACTOR_NAME,
            }
        identity = runtime_host_identity()
        return (
            ROOT_PAGE.replace(
                "{{INITIAL_STATE_JSON}}",
                html_safe_json(initial_state),
            )
            .replace("{{ARCH_SIGN}}", identity["architecture_sign"])
            .replace("{{HARDWARE_TECH}}", identity["hardware_technology"])
            .replace("{{MACHINE}}", identity["machine"])
        )

    @app.api_route(
        "/login",
        methods=["GET", "HEAD"],
        response_class=HTMLResponse,
        include_in_schema=False,
    )
    def login_page(request: Request) -> Response:
        """Render the browser login without exposing machine credentials."""

        signed_in = browser_session_context(request)
        if signed_in is not None:
            if signed_in.password_change_required:
                return RedirectResponse(url="/login/change-password", status_code=303)
            return RedirectResponse(url="/dashboard", status_code=303)
        identity = runtime_host_identity()
        return secure_html_response(
            LOGIN_PAGE.replace("{{ARCH_SIGN}}", identity["architecture_sign"]).replace(
                "{{HARDWARE_TECH}}", identity["hardware_technology"]
            )
        )

    @app.api_route(
        "/login/change-password",
        methods=["GET", "HEAD"],
        response_class=HTMLResponse,
        include_in_schema=False,
    )
    def password_change_page(request: Request) -> Response:
        """Render the required password-change page as a first-class sign-in step."""

        signed_in = browser_session_context(request)
        if signed_in is None:
            return RedirectResponse(
                url="/login?next=/login/change-password",
                status_code=303,
            )
        identity = runtime_host_identity()
        return secure_html_response(
            PASSWORD_CHANGE_PAGE.replace(
                "{{ARCH_SIGN}}", identity["architecture_sign"]
            ).replace("{{HARDWARE_TECH}}", identity["hardware_technology"])
        )
