    @app.get("/readyz", response_model=ReadinessResponse, tags=["system"])
    def readyz(response: Response) -> ReadinessResponse:
        try:
            with store.connect() as connection:
                connection.execute("SELECT 1").fetchone()
            database_state = "ok"
        except sqlite3.Error:
            database_state = "error"
        token_configured = configured_operator_token() is not None
        token_ready = operator_token_ready_for_runtime(production)
        token_strength = configured_operator_token_strength()
        admin_token_ready = admin_token_ready_for_runtime(production)
        mqtt_ready = mqtt_runtime_ready(
            mqtt_broker.config,
            connected=mqtt_broker.connected,
            last_error=mqtt_broker.last_error,
            production=production,
        )
        identity_configured = identity_provider_config()["state"] == "configured"
        deployment_id_configured = configured_deployment_id() is not None
        session_secret = configured_browser_session_secret()
        browser_session_ready = bool(
            session_secret and secret_strength_state(session_secret) == "strong"
        ) and (not production or deployment_id_configured)
        trusted_hosts = allowed_hosts()
        persistence_ready = (not production) or database_persistence["persistent"]
        restore_receipt = offhost_restore_receipt_status(
            env_int(BACKUP_CADENCE_HOURS_ENV, 24, 1, 168)
        )
        offhost_restore_ready = (
            not production or restore_receipt["state"] == "recorded"
        )
        is_ready = (
            database_state == "ok"
            and persistence_ready
            and (token_ready or identity_configured)
            and admin_token_ready
            and (not browser_login_required() or browser_session_ready)
            and mqtt_ready
            and offhost_restore_ready
        )
        response.status_code = 200 if is_ready else 503
        return ReadinessResponse(
            status="ready" if is_ready else "not_ready",
            database=database_state,
            database_persistent=database_persistence["persistent"],
            database_path_configured=database_persistence["path_configured"],
            runtime_mode="production" if production else "development",
            trusted_hosts_configured=trusted_hosts != ["*"],
            operator_token_configured=token_configured or identity_configured,
            operator_token_strength=token_strength,
            identity_provider_configured=identity_configured,
            offhost_restore_ready=offhost_restore_ready,
            browser_session_ready=browser_session_ready,
            deployment_id_configured=deployment_id_configured,
        )
    @app.get("/api/system/observability", tags=["system"])
    def api_system_observability(
        _operator: OperatorContext | None = Depends(
            require_authenticated_in_production
        ),
    ) -> dict[str, Any]:
        """Return customer-safe, read-only live platform telemetry."""

        try:
            with store.connect() as connection:
                connection.execute("SELECT 1").fetchone()
            database_component = {
                "state": "available",
                "persistent": database_persistence["persistent"],
                "storage": database_persistence["storage"],
            }
        except sqlite3.Error:
            database_component = {
                "state": "unavailable",
                "persistent": database_persistence["persistent"],
                "storage": database_persistence["storage"],
            }
        try:
            mqtt_status = app.state.mqtt_broker.public_status()
            mqtt_component = {
                "state": str(mqtt_status.get("status") or "unavailable"),
                "configured": bool(mqtt_status.get("configured")),
                "connected": bool(mqtt_status.get("connected")),
                "messages_accepted": int(mqtt_status.get("messages_accepted") or 0),
                "messages_rejected": int(mqtt_status.get("messages_rejected") or 0),
                "last_observed_at": mqtt_status.get("last_message_at"),
            }
        except Exception:  # pragma: no cover - defensive telemetry fallback.
            mqtt_component = {"state": "unavailable"}
        try:
            rest_status_snapshot = rest_adapter_status(store)
            rest_component = {
                "state": str(rest_status_snapshot.get("readiness_state") or "unavailable"),
                "configured": bool(rest_status_snapshot.get("configured")),
                "device_count": int(rest_status_snapshot.get("rest_device_count") or 0),
                "telemetry_count": int(rest_status_snapshot.get("rest_telemetry_count") or 0),
                "last_observed_at": rest_status_snapshot.get("last_telemetry_at"),
            }
        except Exception:  # pragma: no cover - defensive telemetry fallback.
            rest_component = {"state": "unavailable"}
        return collect_runtime_observability(
            data_volume_path=Path(db_path).expanduser().parent,
            components={
                "api": {"state": "available"},
                "database": database_component,
                "mqtt": mqtt_component,
                "rest": rest_component,
            },
        )

    def _agentic_control_hooks() -> dict[str, Any]:
        def http_check(actor: str) -> dict[str, Any]:
            return run_http_service_checks(
                store,
                app.state.http_service_probe,
                actor=actor,
            )

        def cmdb_builder() -> dict[str, Any]:
            return build_cmdb(
                assets=store.list_rows("assets"),
                devices=store.list_rows("devices"),
                telemetry=store.list_rows("telemetry"),
                config_profiles=store.list_rows("config_profiles"),
                hardware_evidence=store.list_rows("hardware_evidence"),
            )

        def autopilot(actor: str) -> dict[str, Any]:
            return run_agent_autopilot_mission(
                store,
                AgentAutopilotRequest(mission_label="Agentic control mission"),
                actor=actor,
                production=production,
            )

        return {
            "mqtt_status": mqtt_broker.public_status(),
            "http_check": http_check,
            "cmdb_builder": cmdb_builder,
            "autopilot": autopilot,
        }

    def _control_dashboard_payload() -> dict[str, Any]:
        hooks = _agentic_control_hooks()
        return build_control_dashboard(
            store,
            mqtt_status=hooks["mqtt_status"],
            cmdb=hooks["cmdb_builder"](),
        )

