        task = execute_agent_task(
            store,
            AgentTaskRequest(
                goal=f"CONTROL:{request.action} Execute the typed agent control action.",
                action=request.action,
            ),
            actor=operator.actor,
            production=production,
            control_hooks=hooks,
        )
        return {
            "status": "ok",
            "version": __version__,
            "action": request.action,
            "agent_run_id": task.get("run_id"),
            "control": task.get("control"),
            "answer": task.get("answer"),
            "requires_human_approval": task.get("requires_human_approval"),
        }

