    @app.post("/api/services/http/solve-issues", tags=["system"])
    def api_http_services_solve_issues(
        operator: OperatorContext = Depends(require_scope("recovery:approve")),
    ) -> dict[str, Any]:
        """Prepare approval-gated proposals for unresolved service checks."""

        checked = run_http_service_checks(
            store,
            app.state.http_service_probe,
            actor=operator.actor,
        )
        unresolved = [
            item for item in checked["items"] if item["status"] != "healthy"
        ]
        proposals = prepare_http_service_issue_proposals(
            store,
            unresolved,
            actor=operator.actor,
        )
        return {
            "status": "proposals_prepared" if proposals else "no_issues",
            "version": __version__,
            "prepared_for": CUSTOMER_NAME,
            "prepared_by": CONTRACTOR_NAME,
            "summary": {
                **checked["summary"],
                "unresolved": len(unresolved),
                "proposals_prepared": len(proposals),
                "commands_executed": 0,
            },
            "policy": dict(SERVICE_OPERATIONS_POLICY),
            "items": checked["items"],
            "proposals": proposals,
            "audit_event_id": checked["audit_event_id"],
        }

    @app.post("/api/services/http/auto-heal", tags=["system"])
    def api_http_services_auto_heal(
        operator: OperatorContext = Depends(require_scope("recovery:approve")),
    ) -> dict[str, Any]:
        """Recheck service health and escalate only unresolved issues."""

        before = public_service_inventory(store.list_http_service_health())
        before_states = {
            item["service_id"]: item["status"] for item in before["items"]
        }
        checked = run_http_service_checks(
            store,
            app.state.http_service_probe,
            actor=operator.actor,
        )
        recovered = [
            item
            for item in checked["items"]
            if before_states.get(item["service_id"]) in {"degraded", "down"}
            and item["status"] == "healthy"
        ]
        unresolved = [
            item for item in checked["items"] if item["status"] != "healthy"
        ]
        proposals = prepare_http_service_issue_proposals(
            store,
            unresolved,
            actor=operator.actor,
            minimum_failures=int(
                store.get_service_operations_settings()["failure_threshold"]
            ),
        )
        audit = store.add_audit_event(
            event_type="service_operations.auto_heal.rechecked",
            subject_id="http-services",
            actor=operator.actor,
            detail=json.dumps(
                {
                    "recovered": len(recovered),
                    "unresolved": len(unresolved),
                    "proposals_prepared": len(proposals),
                    "commands_executed": 0,
                },
                separators=(",", ":"),
            ),
        )
        return {
            "status": "rechecked",
            "version": __version__,
            "prepared_for": CUSTOMER_NAME,
            "prepared_by": CONTRACTOR_NAME,
            "summary": {
                **checked["summary"],
                "recovered": len(recovered),
                "unresolved": len(unresolved),
                "proposals_prepared": len(proposals),
                "commands_executed": 0,
            },
            "policy": dict(SERVICE_OPERATIONS_POLICY),
            "items": checked["items"],
            "proposals": proposals,
            "audit_event_id": audit["audit_event_id"],
        }

    @app.post("/api/system/debug-dump", tags=["system"])
    def api_system_debug_dump(
        admin: OperatorContext = Depends(require_admin_scope("agent:manage")),
    ) -> JSONResponse:
        """Download a strict allowlist diagnostics snapshot without raw internals."""

        truth = operational_truth_snapshot(
            store,
            production,
            getattr(app.state, "background_tasks", None),
        )
        observability = api_system_observability()
        inventory = public_service_inventory(store.list_http_service_health())
        settings = store.get_service_operations_settings()
        payload: dict[str, Any] = {
            "schema_version": "agentiot.debug-dump.v1",
            "generated_at": utc_now(),
            "version": __version__,
            "tenant_id": configured_tenant_id(),
            "summary": inventory["summary"],
            "runtime": {
                "mode": truth["health"]["runtime_mode"],
                "database": truth["health"]["database"],
                "background_jobs": truth["health"]["background_jobs"],
                "observability_issue_count": len(observability["issues"]),
            },
            "inventory": {
                "assets": truth["assets"]["registered"],
                "devices": truth["assets"]["devices"],
                "telemetry_records": truth["assets"]["telemetry_records"],
                "open_alerts": truth["assets"]["open_alerts"],
                "registered_agents": truth["agents"]["registered"],
            },
            "services": [
                {
                    "service_id": item["service_id"],
                    "status": item["status"],
                    "http_status": item["http_status"],
                    "latency_ms": item["latency_ms"],
                    "security_score": item["security"]["score"],
                    "checked_at": item["checked_at"],
                    "consecutive_failures": item["consecutive_failures"],
                }
                for item in inventory["items"]
            ],
            "settings": {
                "auto_heal_enabled": settings["auto_heal_enabled"],
                "interval_minutes": settings["interval_minutes"],
                "failure_threshold": settings["failure_threshold"],
            },
            "privacy": {
                "environment_included": False,
                "credentials_included": False,
                "raw_logs_included": False,
                "request_bodies_included": False,
                "provider_payloads_included": False,
            },
        }
        audit = store.add_audit_event(
            event_type="service_operations.debug_dump.generated",
            subject_id="service-operations",
            actor=admin.actor,
            detail=json.dumps(
                {
                    "schema_version": payload["schema_version"],
                    "service_count": payload["summary"]["total"],
                },
                separators=(",", ":"),
            ),
        )
        payload["audit_event_id"] = audit["audit_event_id"]
        payload["checksum"] = payload_checksum(payload)
        filename = "agentiot-debug-dump-" + datetime.now(UTC).strftime("%Y%m%dT%H%M%SZ") + ".json"
        return JSONResponse(
            content=payload,
            headers={"Content-Disposition": f'attachment; filename="{filename}"'},
        )

