    @app.post(
        "/api/auth/login",
        response_model=LocalSessionResponse,
        tags=["access"],
    )
    def api_local_login(
        body: LocalLoginRequest,
        request: Request,
        response: Response,
    ) -> LocalSessionResponse:
        """Authenticate a local account and issue an HttpOnly browser cookie."""

        try:
            username = normalize_local_username(body.username)
        except HTTPException:
            username = ""
        record = store.authenticate_local_identity_limited(
            username,
            body.password,
            bucket_key=auth_rate_key(request, "local-login"),
            limit=ADMIN_PASSWORD_FAILURE_LIMIT,
            window_seconds=ADMIN_PASSWORD_FAILURE_WINDOW_SECONDS,
            bootstrap_password=configured_admin_password(),
        )
        if record is None:
            raise HTTPException(status_code=401, detail="Invalid username or password")
        session_token, expires_at = create_browser_session_token(record)
        store.add_audit_event(
            event_type="identity.local.login",
            subject_id=record["username"],
            actor=record["username"],
            detail=json.dumps(
                {
                    "role": record["role"],
                    "cookie_http_only": True,
                    "credential_material_stored": False,
                },
                separators=(",", ":"),
            ),
        )
        set_browser_session_cookie(response, session_token)
        return LocalSessionResponse(
            authenticated=True,
            username=record["username"],
            role=record["role"],
            expires_at=expires_at,
            password_change_required=bool(record["password_change_required"]),
        )

    @app.get(
        "/api/auth/session",
        response_model=LocalSessionResponse,
        tags=["access"],
    )
    def api_local_session(request: Request) -> LocalSessionResponse:
        """Return the current browser identity without exposing its cookie."""

        result = browser_session_claims(request)
        if result is None:
            return LocalSessionResponse(authenticated=False)
        identity, claims = result
        expires_at = datetime.fromtimestamp(int(claims["exp"]), UTC).replace(
            microsecond=0
        ).isoformat()
        return LocalSessionResponse(
            authenticated=True,
            username=identity.actor,
            role=identity.role,
            expires_at=expires_at,
            password_change_required=identity.password_change_required,
        )

    @app.post("/api/auth/logout", tags=["access"])
    def api_local_logout(request: Request, response: Response) -> dict[str, Any]:
        """End the current browser session and invalidate captured copies."""

        identity = browser_session_context(request)
        audit_event_id = None
        if identity is not None:
            audit_event_id = store.revoke_local_sessions(
                identity.actor,
                actor=identity.actor,
                reason="user_logout",
            )
        clear_browser_session_cookie(response)
        return {"status": "signed_out", "audit_event_id": audit_event_id}

    @app.patch("/api/auth/me/password", tags=["access"])
    def api_change_local_password(
        body: LocalPasswordChangeRequest,
        response: Response,
        identity: OperatorContext = Depends(require_local_browser_identity),
    ) -> dict[str, Any]:
        """Change the signed-in local account password and revoke its sessions."""

        audit_event_id = store.change_local_password(
            identity.actor,
            body.current_password,
            body.new_password,
        )
        clear_browser_session_cookie(response)
        return {
            "status": "password_changed",
            "sessions_revoked": True,
            "audit_event_id": audit_event_id,
        }

