    @app.post(
        "/api/auth/admin-session",
        response_model=AdminSessionResponse,
        status_code=201,
        tags=["admin"],
    )
    def api_create_admin_session(
        body: AdminSessionRequest,
        request: Request,
    ) -> AdminSessionResponse:
        try:
            username = normalize_local_username(body.username)
        except HTTPException:
            username = ""
        record = store.authenticate_local_identity_limited(
            username,
            body.password,
            bucket_key=auth_rate_key(request, "admin-password"),
            limit=ADMIN_PASSWORD_FAILURE_LIMIT,
            window_seconds=ADMIN_PASSWORD_FAILURE_WINDOW_SECONDS,
            required_role="admin",
            bootstrap_password=configured_admin_password(),
        )
        if record is None:
            raise HTTPException(status_code=401, detail="Admin credentials required")
        if bool(record["password_change_required"]):
            raise HTTPException(status_code=403, detail="Password change required")
        session_token, expires_at = create_admin_session_token(record)
        audit = store.add_audit_event(
            event_type="access.admin_session.created",
            subject_id=record["username"],
            actor=record["username"],
            detail=json.dumps(
                {
                    "expires_in_seconds": ADMIN_SESSION_TTL_SECONDS,
                    "password_stored": False,
                    "session_token_stored": False,
                },
                separators=(",", ":"),
            ),
        )
        return AdminSessionResponse(
            status="authenticated",
            username=record["username"],
            session_token=session_token,
            expires_at=expires_at,
            expires_in_seconds=ADMIN_SESSION_TTL_SECONDS,
            audit_event_id=audit["audit_event_id"],
        )

