    @app.post(
        "/api/admin/ai/agent-health/check",
        tags=["admin"],
    )
    def api_admin_ai_agent_health_check(
        request: AIAgentHealthCheckRequest | None = None,
        admin: OperatorContext = Depends(require_admin_scope("agent:manage")),
    ) -> dict[str, Any]:
        effective_request = request or AIAgentHealthCheckRequest()
        attempt_id = f"agent-llm-health-{secrets.token_hex(6)}"
        store.add_audit_event(
            event_type="ai.agent_llm_health.started",
            subject_id=attempt_id,
            actor=admin.actor,
            detail=json.dumps(
                {"status": "running"},
                separators=(",", ":"),
            ),
        )
        try:
            return run_agent_llm_health_check(
                store,
                effective_request,
                actor=admin.actor,
                attempt_id=attempt_id,
            )
        except Exception as error:
            store.add_audit_event(
                event_type="ai.agent_llm_health.failed",
                subject_id=attempt_id,
                actor=admin.actor,
                detail=json.dumps(
                    {"status": "failed", "error_type": error.__class__.__name__},
                    separators=(",", ":"),
                ),
            )
            raise

