    @app.get(
        "/api/project/phase-distance",
        tags=["project"],
    )
    def api_project_phase_distance() -> dict[str, Any]:
        board = project_goal_optimization_board(store, production)
        open_phase_closure_task_count = sum(
            int(item["open_task_count"]) for item in board["phase_distance"]
        )
        return {
            "schema_version": "agentiot.phase-readiness.v2",
            "status": board["status"],
            "version": board["version"],
            "source_commit": board["source_commit"],
            "prepared_for": board["prepared_for"],
            "prepared_by": board["prepared_by"],
            "current_phase": board["current_phase"],
            "summary": {
                "open_phase_closure_task_count": open_phase_closure_task_count,
                "phase_closure_task_count": board["summary"][
                    "phase_closure_task_count"
                ],
                "phase_closure_ready_task_count": board["summary"][
                    "phase_closure_ready_task_count"
                ],
                "phase_closure_review_ready_task_count": board["summary"][
                    "phase_closure_review_ready_task_count"
                ],
                "phase_closure_owner_task_count": board["summary"][
                    "phase_closure_owner_task_count"
                ],
                "phase1_evidence_status_date": board["summary"][
                    "phase1_evidence_status_date"
                ],
                "phase1_contract_milestone_count": board["summary"][
                    "phase1_contract_milestone_count"
                ],
                "phase1_due_milestone_count": board["summary"][
                    "phase1_due_milestone_count"
                ],
                "phase1_ready_milestone_count": board["summary"][
                    "phase1_ready_milestone_count"
                ],
                "phase1_overdue_milestone_count": board["summary"][
                    "phase1_overdue_milestone_count"
                ],
                "phase1_in_progress_milestone_count": board["summary"][
                    "phase1_in_progress_milestone_count"
                ],
            },
            "phase_distance": board["phase_distance"],
            "phase_closure_tasks": board["phase_closure_tasks"],
            "next_action": (
                "Execute the first non-ready phase closure task and keep owner-only items "
                "explicitly marked."
                if open_phase_closure_task_count > 0
                else "All phase distance indicators are closed; continue acceptance "
                "evidence review."
            ),
            "privacy": board["privacy"],
        }

