    @app.get("/api/hardware/discovery", tags=["hardware"])
    def hardware_discovery_overview(
        _operator: OperatorContext = Depends(require_scope("device:read")),
    ) -> dict[str, Any]:
        cmdb = build_cmdb(
            assets=store.list_rows("assets"),
            devices=store.list_rows("devices"),
            telemetry=store.list_latest_telemetry_by_device(),
            config_profiles=store.list_rows("config_profiles"),
            hardware_evidence=store.list_rows("hardware_evidence"),
            device_protocols=store.list_rows("device_protocols"),
        )
        profiles = hardware_profile_catalog()
        candidates = store.list_hardware_discovery_candidates()
        network_candidates = store.list_network_discovery_candidates()
        queued_candidates = [
            item for item in candidates if item["status"] == "queued"
        ]
        approved_candidates = [
            item for item in candidates if item["status"] == "approved"
        ]
        management = cmdb["management_summary"]
        return {
            "status": "ok",
            "version": __version__,
            "prepared_for": CUSTOMER_NAME,
            "prepared_by": CONTRACTOR_NAME,
            "summary": {
                "profile_count": len(profiles),
                "candidate_count": len(candidates),
                "network_candidate_count": len(network_candidates),
                "queued_candidate_count": len(queued_candidates),
                "approved_candidate_count": len(approved_candidates),
                "sensor_count": management["sensor_count"],
                "auto_discovered_sensor_count": management[
                    "auto_discovered_sensor_count"
                ],
                "validated_sensor_count": management["validated_sensor_count"],
                "validation_coverage_percent": management[
                    "validation_coverage_percent"
                ],
                "readiness_state": management["readiness_state"],
            },
            "plugin": {
                "hardware_simulator": simulator_status()["plugin"],
                "usb_discovery": usb_discovery_status()["plugin"],
            },
            "supported": {
                "protocols": management["supported_protocol_families"],
                "observed_protocol_hints": management["observed_protocol_hints"],
                "standards": management["supported_standard_families"],
                "boards": sorted(
                    {board for profile in profiles for board in profile["boards"]}
                ),
            },
            "workflow": {
                "catalog_endpoint": "/api/hardware/discovery/profiles",
                "candidate_endpoint": "/api/hardware/discovery/candidates",
                "network_scan_endpoint": "/api/hardware/discovery/scans",
                "usb_status_endpoint": "/api/hardware/discovery/usb/status",
                "usb_preview_endpoint": "/api/hardware/discovery/usb/sysfs",
                "cmdb_endpoint": "/api/cmdb/configuration-items",
                "next_action": management["next_action"],
            },
            "privacy": {
                "customer_safe": True,
                "raw_identifier_storage": False,
                "serial_numbers_returned": False,
                "secret_values_returned": False,
                "local_paths_returned": False,
            },
        }

