    @app.post(
        "/api/firmware/compatibility",
        response_model=FirmwareCompatibilityResponse,
        tags=["firmware"],
    )
    def check_firmware_compatibility(
        request: FirmwareCompatibilityRequest,
    ) -> FirmwareCompatibilityResponse:
        hardware_model = request.hardware_model
        firmware_version = request.firmware_version
        if request.device_id:
            device = store.get_device(request.device_id)
            if not device:
                raise HTTPException(status_code=404, detail="Device not registered")
            registered_firmware = str(device.get("firmware_version") or "")
            if firmware_version != registered_firmware:
                raise HTTPException(
                    status_code=409,
                    detail=(
                        "Firmware request conflicts with the registered device version"
                    ),
                )
            hardware_evidence = store.fetch_one(
                "SELECT hardware_model FROM hardware_evidence WHERE device_id = ?",
                (request.device_id,),
            )
            if hardware_evidence and hardware_evidence.get("hardware_model"):
                registered_hardware = str(hardware_evidence["hardware_model"])
                if normalize_hardware_model(hardware_model) != normalize_hardware_model(
                    registered_hardware
                ):
                    raise HTTPException(
                        status_code=409,
                        detail=(
                            "Hardware request conflicts with registered device evidence"
                        ),
                    )
                hardware_model = registered_hardware
            firmware_version = registered_firmware
        return FirmwareCompatibilityResponse(
            **phase1_firmware_compatibility_result(
                hardware_model=hardware_model,
                firmware_version=firmware_version,
                target_runtime=request.target_runtime,
            )
        )

