    @app.get(
        "/api/hardware/discovery/candidates",
        tags=["hardware"],
    )
    def list_hardware_discovery_candidates(
        status: str = Query(default="", max_length=24),
        source: str = Query(default="", max_length=32),
        protocol: str = Query(default="", max_length=32),
        limit: int = Query(default=100, ge=1, le=100),
        offset: int = Query(default=0, ge=0, le=10_000),
        snapshot_revision: str = Query(
            default="",
            pattern=r"^$|^sha256:[a-f0-9]{64}$",
        ),
        operator: OperatorContext = Depends(require_scope("device:read")),
    ) -> dict[str, Any]:
        del operator
        all_candidates = [
            *store.list_hardware_discovery_candidates(),
            *store.list_network_discovery_candidates(),
        ]
        facets = {
            "statuses": sorted(
                {str(item.get("status") or "unknown") for item in all_candidates}
            ),
            "sources": sorted(
                {str(item.get("source") or "unknown") for item in all_candidates}
            ),
            "protocols": sorted(
                {
                    str(value)
                    for item in all_candidates
                    for value in (
                        item.get("protocol_hints") or item.get("protocols") or []
                    )
                }
            ),
        }
        requested_status = status.strip().lower()
        requested_source = source.strip().lower()
        requested_protocol = protocol.strip().lower()
        candidates = [
            item
            for item in all_candidates
            if (not requested_status or str(item.get("status") or "").lower() == requested_status)
            and (not requested_source or str(item.get("source") or "").lower() == requested_source)
            and (
                not requested_protocol
                or requested_protocol
                in {
                    str(value).lower()
                    for value in (
                        item.get("protocol_hints") or item.get("protocols") or []
                    )
                }
            )
        ]
        matched_count = len(candidates)
        queued_count = sum(1 for item in candidates if item["status"] == "queued")
        approved_count = sum(1 for item in candidates if item["status"] == "approved")
        descriptor_validated_count = sum(
            1 for item in candidates if item.get("descriptor_validated") is True
        )
        network_candidate_count = sum(
            1 for item in candidates if item.get("source") == "network_tcp_hint"
        )
        candidates.sort(
            key=lambda item: (
                str(item.get("last_seen_at") or item.get("created_at") or ""),
                str(item.get("candidate_id") or ""),
            ),
            reverse=True,
        )
        revision_payload = [
            {
                "candidate_id": str(item.get("candidate_id") or ""),
                "fingerprint": str(item.get("evidence_fingerprint") or ""),
                "observed_at": str(
                    item.get("last_seen_at") or item.get("created_at") or ""
                ),
                "observation_revision": int(item.get("observation_revision") or 0),
                "status": str(item.get("status") or "unknown"),
            }
            for item in candidates
        ]
        queue_revision = "sha256:" + hashlib.sha256(
            json.dumps(
                revision_payload,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest()
        if offset and not snapshot_revision:
            raise HTTPException(
                status_code=400,
                detail="Queue revision is required for paginated reads",
            )
        if snapshot_revision and not hmac.compare_digest(
            snapshot_revision,
            queue_revision,
        ):
            raise HTTPException(
                status_code=409,
                detail="Discovery queue changed; restart pagination",
            )
        candidates = candidates[offset : offset + limit]
        next_offset = offset + len(candidates)
        return {
            "status": "ok",
            "version": __version__,
            "summary": {
                "candidate_count": matched_count,
                "returned_count": len(candidates),
                "offset": offset,
                "has_more": next_offset < matched_count,
                "next_offset": next_offset if next_offset < matched_count else None,
                "queue_revision": queue_revision,
                "queued_count": queued_count,
                "approved_count": approved_count,
                "descriptor_validated_count": descriptor_validated_count,
                "network_candidate_count": network_candidate_count,
            },
            "facets": facets,
            "policy": {
                "workflow": "validate_queue_approve_promote",
                "write_target": "/api/hardware/discovery/candidates",
                "approval_scopes": ["recovery:approve", "device:write"],
                "network_approval_scopes": ["recovery:approve", "device:write"],
                "network_scan_endpoint": "/api/hardware/discovery/scans",
                "network_scan_scope": "network:scan",
                "cmdb_target": "/api/cmdb/configuration-items",
                "raw_hardware_identifier_storage": False,
                "queued_address_retention_hours": DISCOVERY_CANDIDATE_TTL_HOURS,
                "approved_address_storage": "device_protocol_endpoint",
                "customer_safe": True,
                "pagination": "revision_bound_offset",
            },
            "items": candidates,
        }

