    @app.post(
        "/api/hardware/discovery/scans",
        status_code=201,
        tags=["hardware"],
    )
    async def run_network_discovery_scan(
        request: NetworkDiscoveryScanRequest,
        operator: OperatorContext = Depends(require_scope("network:scan")),
    ) -> dict[str, Any]:
        if not request.confirm_active:
            raise HTTPException(
                status_code=400,
                detail="Explicit active-scan confirmation is required",
            )
        enforce_network_discovery_scope(request.cidr, production=production)
        lock: asyncio.Lock = app.state.network_discovery_lock
        if lock.locked():
            raise HTTPException(status_code=409, detail="A network scan is already running")
        scope_subject = (
            "network-scope-"
            + hashlib.sha256(request.cidr.strip().encode("utf-8")).hexdigest()[:16]
        )
        async with lock, network_discovery_scan_lease(
            store,
            operator.actor,
        ) as lease_retry_after:
            if lease_retry_after:
                raise HTTPException(
                    status_code=409,
                    detail="A network scan is already running",
                    headers={"Retry-After": str(lease_retry_after)},
                )
            retry_after = store.claim_network_discovery_attempt(
                actor=operator.actor,
                cooldown_seconds=DISCOVERY_ACTOR_COOLDOWN_SECONDS,
            )
            if retry_after:
                raise HTTPException(
                    status_code=429,
                    detail=(
                        "Network scan cooldown active; retry after "
                        f"{retry_after} seconds"
                    ),
                )
            authorization_audit = store.add_audit_event(
                event_type="network.discovery.scan.authorized",
                subject_id=scope_subject,
                actor=operator.actor,
                detail=json.dumps(
                    {
                        "explicit_confirmation": True,
                        "max_hosts": MAX_DISCOVERY_HOSTS,
                        "payload_reads": False,
                        "credentials_used": False,
                    },
                    separators=(",", ":"),
                ),
            )
            try:
                result = await app.state.network_discovery_runner(request.cidr)
            except asyncio.CancelledError:
                store.add_audit_event(
                    event_type="network.discovery.scan.failed",
                    subject_id=scope_subject,
                    actor=operator.actor,
                    detail=json.dumps(
                        {
                            "reason": "scanner_cancelled",
                            "authorization_audit_event_id": authorization_audit[
                                "audit_event_id"
                            ],
                            "asset_inventory_mutated": False,
                        },
                        separators=(",", ":"),
                    ),
                )
                raise
            except ValueError as error:
                store.add_audit_event(
                    event_type="network.discovery.scan.failed",
                    subject_id=scope_subject,
                    actor=operator.actor,
                    detail=json.dumps(
                        {
                            "reason": "invalid_or_oversized_scope",
                            "authorization_audit_event_id": authorization_audit[
                                "audit_event_id"
                            ],
                            "asset_inventory_mutated": False,
                        },
                        separators=(",", ":"),
                    ),
                )
                raise HTTPException(status_code=400, detail=str(error)) from error
            except OSError as error:
                store.add_audit_event(
                    event_type="network.discovery.scan.failed",
                    subject_id=scope_subject,
                    actor=operator.actor,
                    detail=json.dumps(
                        {
                            "reason": "scanner_resource_or_permission_failure",
                            "error_type": type(error).__name__,
                            "errno": error.errno,
                            "authorization_audit_event_id": authorization_audit[
                                "audit_event_id"
                            ],
                            "asset_inventory_mutated": False,
                        },
                        separators=(",", ":"),
                    ),
                )
                raise HTTPException(
                    status_code=503,
                    detail="Network discovery stopped because scanner resources were unavailable",
                ) from error
            except Exception as error:
                store.add_audit_event(
                    event_type="network.discovery.scan.failed",
                    subject_id=scope_subject,
                    actor=operator.actor,
                    detail=json.dumps(
                        {
                            "reason": "scanner_unexpected_failure",
                            "error_type": type(error).__name__,
                            "authorization_audit_event_id": authorization_audit[
                                "audit_event_id"
                            ],
                            "asset_inventory_mutated": False,
                        },
                        separators=(",", ":"),
                    ),
                )
                raise HTTPException(
                    status_code=503,
                    detail="Network discovery stopped before evidence was queued",
                ) from error
            try:
                candidates, audit_event_id = store.queue_network_discovery_observations(
                    list(result["items"]),
                    actor=operator.actor,
                    completion_receipt={
                        "subject_id": scope_subject,
                        "status": result["status"],
                        "host_count": result["host_count"],
                        "observed_host_count": result["observed_host_count"],
                        "candidate_count": len(result["items"]),
                        "asset_inventory_mutated": False,
                        "payload_reads": False,
                        "credentials_used": False,
                        "authorization_audit_event_id": authorization_audit[
                            "audit_event_id"
                        ],
                    },
                )
            except Exception as error:
                store.add_audit_event(
                    event_type="network.discovery.scan.failed",
                    subject_id=scope_subject,
                    actor=operator.actor,
                    detail=json.dumps(
                        {
                            "reason": "candidate_persistence_failure",
                            "error_type": type(error).__name__,
                            "authorization_audit_event_id": authorization_audit[
                                "audit_event_id"
                            ],
                            "asset_inventory_mutated": False,
                        },
                        separators=(",", ":"),
                    ),
                )
                raise HTTPException(
                    status_code=503,
                    detail="Network discovery evidence could not be queued",
                ) from error
        return {
            **result,
            "version": __version__,
            "candidates": candidates,
            "audit_event_id": audit_event_id,
            "approval_required": True,
        }

