    @app.post(
        "/api/hardware/discovery/candidates/{candidate_id}/approve",
        response_model=HardwareDiscoveryCandidateApprovalResponse,
        tags=["hardware"],
    )
    def approve_hardware_discovery_candidate(
        candidate_id: str,
        request: NetworkDiscoveryCandidateApprovalRequest | None = None,
        operator: OperatorContext = Depends(require_scope("recovery:approve")),
    ) -> HardwareDiscoveryCandidateApprovalResponse:
        if "device:write" not in set(operator.scopes):
            raise HTTPException(status_code=403, detail="Scope required: device:write")
        if request is None or not request.confirm or not request.expected_fingerprint:
            raise HTTPException(
                status_code=400,
                detail="Explicit candidate approval is required",
            )
        if candidate_id.startswith("netdisc-"):
            if request.expected_revision is None:
                raise HTTPException(
                    status_code=400,
                    detail="Discovery candidate revision is required",
                )
            candidate = store.get_network_discovery_candidate(candidate_id)
            if candidate is None:
                raise HTTPException(
                    status_code=404,
                    detail="Network discovery candidate not found",
                )
            enforce_network_discovery_scope(
                f"{candidate['address']}/32",
                production=production,
            )
            result = store.approve_network_discovery_candidate(
                candidate_id,
                request,
                actor=operator.actor,
            )
            if result.get("registration"):
                cmdb = build_cmdb(
                    assets=store.list_rows("assets"),
                    devices=store.list_rows("devices"),
                    telemetry=store.list_latest_telemetry_by_device(),
                    config_profiles=store.list_rows("config_profiles"),
                    hardware_evidence=store.list_rows("hardware_evidence"),
                    device_protocols=store.list_rows("device_protocols"),
                )
                cmdb["graph"] = build_cmdb_graph(cmdb)
                result["registration"]["cmdb"] = cmdb
            return HardwareDiscoveryCandidateApprovalResponse(**result)
        return HardwareDiscoveryCandidateApprovalResponse(
            **store.approve_hardware_discovery_candidate(
                candidate_id,
                operator.actor,
                request.expected_fingerprint,
            )
        )

