    @app.post(
        "/api/devices/{device_id}/telemetry",
        response_model=TelemetryAccepted,
        status_code=201,
        tags=["telemetry"],
    )
    def create_device_telemetry(
        device_id: str,
        telemetry: DeviceTelemetryCreate,
        request: Request,
        device_token: str | None = Security(device_ingest_token_header),
    ) -> TelemetryAccepted:
        """Accept one current, replay-safe sample for a credential-bound device."""

        credentials = configured_device_ingest_credentials()
        if not credentials:
            raise HTTPException(
                status_code=503,
                detail="Device ingestion authentication unavailable",
            )
        expected_token = credentials.get(device_id)
        if (
            expected_token is None
            or not device_token
            or not secrets.compare_digest(device_token, expected_token)
        ):
            record_auth_failure(request, "device-ingest")
            raise HTTPException(status_code=401, detail="Device ingestion token required")
        clear_auth_failures(request, "device-ingest")
        if telemetry.device_id != device_id:
            raise HTTPException(status_code=400, detail="Telemetry device mismatch")
        if telemetry.sampled_at.tzinfo is None:
            raise HTTPException(
                status_code=400,
                detail="Telemetry sample timestamp must include a timezone",
            )
        sampled_at = telemetry.sampled_at.astimezone(UTC)
        sample_age = datetime.now(UTC) - sampled_at
        if sample_age > timedelta(seconds=DEVICE_INGEST_MAX_SAMPLE_AGE_SECONDS):
            raise HTTPException(status_code=400, detail="Telemetry sample is too old")
        if sample_age < -timedelta(seconds=DEVICE_INGEST_MAX_FUTURE_SKEW_SECONDS):
            raise HTTPException(
                status_code=400,
                detail="Telemetry sample timestamp is in the future",
            )
        result = store.add_telemetry(
            TelemetryCreate(
                device_id=telemetry.device_id,
                metric=telemetry.metric,
                value=telemetry.value,
                unit=telemetry.unit,
            ),
            audit_event_type="telemetry.edge_ingested",
            audit_actor=f"edge-ingest:{device_id}",
            source_sample_id=telemetry.sample_id,
            source_sampled_at=sampled_at.isoformat(),
        )
        return TelemetryAccepted(**result)

