    @app.get(
        "/api/audit/events",
        response_model=AuditCollectionResponse,
        tags=["audit"],
    )
    def list_audit_events(
        limit: int = Query(default=100, ge=1, le=200),
        before_id: int | None = Query(default=None, ge=1),
        operator: OperatorContext | None = Depends(optional_operator_context),
    ) -> AuditCollectionResponse:
        if operator is None:
            return AuditCollectionResponse(
                items=store.list_public_audit_events(min(limit, 12))
            )
        if "report:read" not in operator.scopes:
            raise HTTPException(status_code=403, detail="Scope required: report:read")
        if operator.role == "viewer":
            return AuditCollectionResponse(
                items=store.list_public_audit_events(min(limit, 100))
            )
        rows, next_cursor = store.list_audit_events_page(
            limit=limit,
            before_id=before_id,
        )
        return AuditCollectionResponse(items=rows, next_cursor=next_cursor)

