    def build_chat_response(
        request: ChatRequest,
        operator: OperatorContext | None,
    ) -> ChatResponse:
        """Build chat response once for JSON and SSE transports."""

        started_at = time.perf_counter()
        authenticated = operator is not None
        response = grounded_diagnosis(
            store,
            request.message,
            actor=operator.actor if operator else None,
            allow_provider_runtime=authenticated,
        )
        latency_ms = round((time.perf_counter() - started_at) * 1000)
        response.activity = assistant_activity_log(
            grounding=response.grounding,
            agent_route=response.agent_route,
            provider_runtime=response.provider_runtime,
            assistant_plan=response.assistant_plan,
            status=response.status,
        )
        response.answer = format_operator_assistant_answer(response)
        response.answer_review = assistant_answer_review(response, request.message)
        response.coworker_package = assistant_coworker_package(
            store, request.message, response, latency_ms
        )
        if (
            authenticated
            and response.token_usage_record is None
            and (
                not response.provider_runtime
                or (
                    response.provider_runtime.get("status") == "skipped"
                    and response.provider_runtime.get("provider") == "grounded_fallback"
                )
            )
        ):
            response.token_usage_record = store.add_model_token_usage(
                provider="local",
                model="non_model_grounded_answer",
                input_tokens=estimate_token_count(request.message),
                output_tokens=estimate_token_count(response.answer),
                source="assistant_fallback_estimate",
                actor=operator.actor,
            )
        interaction = None
        if authenticated:
            interaction = store.add_assistant_interaction(
                message=request.message,
                response=response,
                actor=operator.actor,
                latency_ms=latency_ms,
                requested_session_id=request.session_id,
                client_message_id=request.client_message_id,
                parent_message_id=request.parent_message_id,
            )
        response.session = assistant_session_state(
            message=request.message,
            requested_session_id=request.session_id,
            client_message_id=request.client_message_id,
            parent_message_id=request.parent_message_id,
            response=response,
            interaction=interaction,
            latency_ms=latency_ms,
        )
        response.session["persistence"] = {
            "status": "persisted" if authenticated else "preview_not_persisted",
            "reason": (
                "authenticated_operator_evidence"
                if authenticated
                else "operator_token_required_for_ledger_and_closed_loop_writes"
            ),
            "ledger_written": authenticated,
            "tool_proposals_written": False,
            "finding_written": authenticated,
            "provider_runtime_allowed": authenticated,
            "interaction_id": interaction["interaction_id"] if interaction else None,
        }
        if authenticated:
            session_context = assistant_session_context(
                store,
                session_id=response.session["session_id"],
                parent_message_id=request.parent_message_id,
                current_interaction_id=interaction["interaction_id"],
                actor=interaction["actor"],
            )
        else:
            session_context = {
                "status": "preview_not_persisted",
                "prior_turn_count": 0,
                "parent_message_id": response.session["parent_message_id"],
                "parent_match": False,
                "last_prior_turn": None,
                "category_counts": {},
                "status_counts": {},
                "evidence_counts": {"runtime": 0, "knowledge": 0, "total": 0},
                "safe_context_fields": [
                    "session_id",
                    "message_id",
                    "parent_message_id",
                    "response_status",
                    "confidence",
                    "evidence_count",
                    "knowledge_count",
                ],
                "storage_policy": "transient_preview_no_persistent_memory",
                "raw_prompt_stored": False,
                "answer_text_stored": False,
                "provider_payload_stored": False,
                "isolation_policy": "anonymous_preview_has_no_durable_context",
            }
        response.session["session_context"] = session_context
        response.tool_proposals = assistant_tool_proposals(response, response.session)
        if authenticated:
            response.tool_proposals = assistant_apply_persisted_tool_state(
                store, response.tool_proposals, response.session
            )
        response.coworker_package["session"] = response.session
        response.coworker_package["session_context"] = session_context
        response.coworker_package["memory_update"]["stored"] = authenticated
        response.coworker_package["memory_update"]["persistence"] = response.session[
            "persistence"
        ]
        response.coworker_package["memory_update"]["session_context"] = {
            "available": session_context["prior_turn_count"] > 0,
            "prior_turn_count": session_context["prior_turn_count"],
            "parent_match": session_context["parent_match"],
            "storage_policy": session_context["storage_policy"],
        }
        response.coworker_package["tool_proposals"] = response.tool_proposals
        if authenticated:
            store.add_evidence_finding(
                source="assistant_chat",
                subject_id=response.status,
                outcome=response.confidence,
                severity=(
                    "review_required"
                    if response.confidence.startswith("low")
                    else "info"
                ),
                evidence=(
                    f"Route {response.route['active_route'] if response.route else response.status}; "
                    f"grounding records {len(response.grounding)}; "
                    f"approval required {response.requires_human_approval}; "
                    f"session evidence captured; tool proposals {len(response.tool_proposals)}; "
                    f"answer review score {response.answer_review['score']}."
                ),
                lesson="Do not store raw operator prompts; keep answers grounded and route labels visible.",
            )
        return response

    @app.post("/api/chat", response_model=ChatResponse, tags=["ai"])
    def chat(
        request: ChatRequest,
        operator: OperatorContext | None = Depends(require_assistant_access),
    ) -> ChatResponse:
        return build_chat_response(request, operator)

    @app.post("/api/assistant/stream", tags=["ai"])
    def assistant_stream(
        request: ChatRequest,
        operator: OperatorContext | None = Depends(require_assistant_access),
    ) -> StreamingResponse:
        """Stream the assistant answer as customer-safe SSE events."""

        def event_stream():
            response = build_chat_response(request, operator)
            stream_id = "stream-" + assistant_prompt_hash(
                f"{response.session.get('session_id', '')}:{response.session.get('message_id', '')}"
            )
            yield assistant_sse_event(
                "start",
                {
                    "stream_id": stream_id,
                    "version": __version__,
                    "status": "started",
                    "transport": "sse.v1",
                    "customer": CUSTOMER_NAME,
                    "contractor": CONTRACTOR_NAME,
                    "privacy": {
                        "raw_prompt_returned": False,
                        "raw_prompt_stored": False,
                        "provider_payload_returned": False,
                        "secret_values_returned": False,
                    },
                },
            )
            yield assistant_sse_event(
                "route",
                {
                    "status": response.status,
                    "confidence": response.confidence,
                    "active_route": response.route.get("active_route") if response.route else response.status,
                    "provider_runtime": assistant_provider_runtime_stream_view(response),
                    "requires_human_approval": response.requires_human_approval,
                },
            )
            yield assistant_sse_event(
                "evidence",
                {
                    "grounding": response.grounding,
                    "knowledge_grounding": response.knowledge_grounding,
                    "evidence_links": response.evidence_links,
                },
            )
            yield assistant_sse_event(
                "a2a",
                {
                    "agent_route": response.agent_route,
                    "a2a_trace": response.a2a_trace,
                    "schema_version": A2A_SCHEMA_VERSION,
                },
            )
            chunks = assistant_answer_chunks(response.answer)
            for index, chunk in enumerate(chunks, start=1):
                yield assistant_sse_event(
                    "delta",
                    {
                        "index": index,
                        "chunk_count": len(chunks),
                        "text": chunk,
                    },
                )
            yield assistant_sse_event(
                "tools",
                {
                    "tool_proposals": response.tool_proposals,
                    "requires_human_approval": response.requires_human_approval,
                },
            )
            yield assistant_sse_event(
                "review",
                {
                    "answer_review": response.answer_review,
                    "session_persistence": response.session.get("persistence", {}),
                    "token_usage_record": response.token_usage_record,
                    "coworker_quality": response.coworker_package.get("quality_rubric", []),
                },
            )
            yield assistant_sse_event(
                "done",
                {
                    "stream_id": stream_id,
                    "status": response.status,
                    "session": response.session,
                    "assistant_plan": response.assistant_plan,
                    "next_actions": response.next_actions,
                    "answer_complete": True,
                    "privacy": {
                        "answer_text_stored": False,
                        "provider_payload_stored": False,
                        "customer_delivery_safe": True,
                    },
                },
            )

        return StreamingResponse(
            event_stream(),
            media_type="text/event-stream",
            headers={
                "Cache-Control": "no-cache",
                "X-Accel-Buffering": "no",
            },
        )

