    @app.patch("/api/settings", tags=["settings"])
    def update_settings(
        request: PublicSettingsUpdateRequest,
        admin: OperatorContext = Depends(require_admin_scope("agent:manage")),
    ) -> dict[str, Any]:
        current_policy = store.get_ai_memory_policy()
        policy_request = AIMemoryPolicyRequest(
            max_memory_mb=request.max_memory_mb
            if request.max_memory_mb is not None
            else int(current_policy["max_memory_mb"]),
            retention_hours=request.retention_hours
            if request.retention_hours is not None
            else int(current_policy["retention_hours"]),
            max_session_count=request.max_session_count
            if request.max_session_count is not None
            else int(current_policy["max_session_count"]),
            warn_at_percent=request.warn_at_percent
            if request.warn_at_percent is not None
            else int(current_policy["warn_at_percent"]),
            auto_prune=request.auto_prune
            if request.auto_prune is not None
            else bool(current_policy["auto_prune"]),
        )
        result = store.update_ai_memory_policy(policy_request, actor=admin.actor)
        return {
            "status": "updated",
            "version": __version__,
            "prepared_for": CUSTOMER_NAME,
            "prepared_by": CONTRACTOR_NAME,
            "items": public_settings(production, store),
            "updated_setting": "AI memory policy",
            "policy": result["policy"],
            "recommendation": ai_memory_recommendation(store),
            "audit_event_id": result["audit_event_id"],
            "privacy": {
                "credential_values_returned": False,
                "raw_prompts_returned": False,
                "local_paths_returned": False,
                "customer_safe": True,
            },
        }

